import { identityText } from "../graph/index.js";
import { createInitialMachineState, MachineRunError, stepMachine } from "../machine/index.js";
import { instrument } from "./instrumentation.js";
import { initialObservation, observationSourceReferences } from "./observation.js";
import { machineSourceReferences, resolvesInGraph } from "./references.js";
export function savamConfiguration(graph, machine, observation) {
    return Object.freeze({
        kind: "SavamConfiguration",
        graph,
        machine,
        observation
    });
}
/**
 * The initial configuration for `G`: the base machine's own initial state
 * paired with the empty observation.
 */
export function initialConfiguration(graph) {
    return savamConfiguration(graph, createInitialMachineState(graph), initialObservation());
}
/**
 * `erase(Sigma) = m`.
 *
 * Erasure discards the observation and nothing else. The source graph is not
 * discarded because it is the base relation's own parameter, not visualization
 * metadata, and the machine state is returned unchanged rather than rebuilt.
 */
export function erase(configuration) {
    return configuration.machine;
}
/**
 * The SAVAM-Step rule:
 *
 * ```text
 *   m ->_G m'      omega' = I(G, m, m')
 *   -----------------------------------
 *   <G,m,omega> ->V <G,m',omega'>
 * ```
 *
 * The base step is taken first, from `erase(Sigma)` alone. The prior
 * observation is not read, not passed to `stepMachine`, and cannot change
 * which transition applies; a visual step exists exactly when a base step
 * does.
 */
export function stepVisual(configuration) {
    const transition = stepMachine(configuration.graph, erase(configuration));
    if (transition === undefined)
        return undefined;
    return Object.freeze({
        kind: "SavamStep",
        rule: transition.rule,
        configuration: savamConfiguration(configuration.graph, transition.state, instrument(configuration.graph, erase(configuration), transition))
    });
}
const DEFAULT_MAX_STEPS = 10_000;
/**
 * Drives `<G, m_0, omega_0>` to a terminal control by repeated `stepVisual`.
 *
 * This is the observed counterpart of `runMachineToCompletion`. Because every
 * step erases to the same base step, both drivers visit the same machine
 * states in the same order; `eraseVisualTrace` makes that comparable directly.
 */
export function runVisualToCompletion(graph, options = {}) {
    const maxSteps = options.maxSteps ?? DEFAULT_MAX_STEPS;
    if (!Number.isSafeInteger(maxSteps) || maxSteps < 1) {
        throw new RangeError(`A visual step budget must be a positive safe integer; received ${maxSteps}.`);
    }
    const entries = [];
    let configuration = initialConfiguration(graph);
    for (;;) {
        const control = configuration.machine.c;
        if (control.kind === "Done") {
            return Object.freeze({
                kind: "VisualRun",
                value: control.value,
                steps: entries.length,
                trace: Object.freeze(entries)
            });
        }
        if (entries.length >= maxSteps) {
            throw new MachineRunError("STEP_BUDGET_EXHAUSTED", `The visual machine did not reach Done within ${maxSteps} transitions.`, control, entries.length, eraseVisualTrace(Object.freeze([...entries])));
        }
        const step = stepVisual(configuration);
        if (step === undefined) {
            throw new MachineRunError("STUCK", `No base transition applies after ${entries.length} visual steps.`, control, entries.length, eraseVisualTrace(Object.freeze([...entries])));
        }
        entries.push(Object.freeze({
            kind: "VisualTraceEntry",
            index: entries.length,
            rule: step.rule,
            before: configuration,
            after: step.configuration
        }));
        configuration = step.configuration;
    }
}
/**
 * Erasure lifted to traces: every visual transition erases to exactly the base
 * transition `runMachineToCompletion` records for the same graph.
 */
export function eraseVisualTrace(trace) {
    return Object.freeze(trace.map((entry) => Object.freeze({
        kind: "MachineTraceEntry",
        index: entry.index,
        rule: entry.rule,
        before: erase(entry.before).c,
        after: erase(entry.after).c
    })));
}
/**
 * The well-anchoring judgment for a configuration:
 * `srcs(m) subset of ids(G)` and every source identifier the observation
 * mentions, focus included, resolves in `G`.
 */
export function checkAnchors(configuration) {
    const { graph } = configuration;
    const diagnostics = [];
    for (const reference of machineSourceReferences(erase(configuration))) {
        if (resolvesInGraph(graph, reference))
            continue;
        diagnostics.push(Object.freeze({
            code: "UNRESOLVED_MACHINE_REFERENCE",
            path: "srcs(m)",
            message: `srcs(m) contains ${identityText(reference)}, which does not resolve in G.`,
            subject: reference
        }));
    }
    for (const reference of observationSourceReferences(configuration.observation)) {
        if (resolvesInGraph(graph, reference))
            continue;
        diagnostics.push(Object.freeze({
            code: "UNRESOLVED_OBSERVATION_REFERENCE",
            path: "omega",
            message: `omega mentions ${identityText(reference)}, which does not resolve in G.`,
            subject: reference
        }));
    }
    return Object.freeze(diagnostics);
}
/** The boolean form of `checkAnchors`. */
export function isWellAnchored(configuration) {
    return checkAnchors(configuration).length === 0;
}
