import {
  getPort,
  portReferenceRegion,
  resolveSourceId,
  sourceDomainOf,
  type Graph,
  type RegionId,
  type SourceDomain,
  type SourceId
} from "@graphlambda/core";

import type { Box, Scene } from "../canvas/scene.js";

/**
 * The semantic half of a debugger source-navigation request.
 *
 * Resolution and region ownership come from core graph queries. Coordinates
 * are deliberately absent: containment on the SVG is never used to decide
 * which lexical/source region an identity belongs to.
 */
export interface SourceNavigationTarget {
  readonly source: SourceId;
  readonly domain: SourceDomain;
  readonly region: RegionId;
}

/** Resolve a SAVAM source identity to the region in which it is projected. */
export function sourceNavigationTarget(
  graph: Graph,
  source: SourceId
): SourceNavigationTarget | undefined {
  const element = resolveSourceId(graph, source);
  if (element === undefined) return undefined;

  const domain = sourceDomainOf(element);
  const region = (() => {
    switch (domain) {
      case "node":
        return "region" in element ? element.region : undefined;
      case "port":
        return element.kind === "Port"
          ? portReferenceRegion(graph, element)?.id
          : undefined;
      case "edge": {
        if (element.kind !== "Edge" && element.kind !== "BinderUse") {
          return undefined;
        }
        const target = getPort(graph, element.target);
        return target === undefined
          ? undefined
          : portReferenceRegion(graph, target)?.id;
      }
      case "region":
        return element.kind === "Region" ? element.id : undefined;
    }
  })();

  if (region === undefined) return undefined;
  return Object.freeze({ source, domain, region });
}

/**
 * Locate an already-resolved identity in one deterministic scene.
 *
 * This is camera geometry only. It never changes the semantic target returned
 * by `sourceNavigationTarget` and has no fallback based on visual containment.
 */
export function sourceBoxInScene(
  scene: Scene,
  target: SourceNavigationTarget
): Box | undefined {
  switch (target.domain) {
    case "node":
      return scene.nodes.find((node) => node.id === target.source)?.box;
    case "port": {
      const port = scene.ports.find((candidate) => candidate.id === target.source);
      return port === undefined
        ? undefined
        : Object.freeze({ x: port.x - 14, y: port.y - 14, width: 28, height: 28 });
    }
    case "edge": {
      const use = scene.variableUses.find((candidate) => candidate.edge === target.source);
      const wire = scene.wires.find((candidate) => candidate.id === target.source);
      if (wire === undefined) return use?.box;

      const xs = wire.route.map((point) => point.x);
      const ys = wire.route.map((point) => point.y);
      const left = Math.min(...xs);
      const top = Math.min(...ys);
      return Object.freeze({
        x: left - 8,
        y: top - 8,
        width: Math.max(16, Math.max(...xs) - left + 16),
        height: Math.max(16, Math.max(...ys) - top + 16)
      });
    }
    case "region":
      return scene.regions.find((region) => region.id === target.source)?.box;
  }
}
