import { useId, useState, type JSX } from "react";
import { parseTypeText, prettyType, type Type } from "@graphlambda/core";

export interface TypeChoice { readonly id: string; readonly type: Type }

/** Common choices plus the full core type grammar, including nested arrows. */
export function TypePicker({ label, value, choices, disabled = false, arrowsOnly = false, onChange }: {
  readonly label: string;
  readonly value: Type;
  readonly choices: readonly TypeChoice[];
  readonly disabled?: boolean;
  readonly arrowsOnly?: boolean;
  readonly onChange: (type: Type) => void;
}): JSX.Element {
  const id = useId();
  const current = prettyType(value);
  const options = choices.some((choice) => prettyType(choice.type) === current)
    ? choices : [...choices, { id: current, type: value }];
  const [text, setText] = useState(current);
  const parsed = parseTypeText(text);
  const error = !parsed.ok ? parsed.diagnostics[0]?.message
    : arrowsOnly && parsed.type.kind !== "Arrow" ? "A recursive function needs an arrow type, such as Int -> Int." : undefined;
  return <div className="gl-type-picker">
    <select className="gl-input gl-mono" aria-label={label} disabled={disabled}
      value={options.find((choice) => prettyType(choice.type) === current)?.id ?? current}
      onChange={(event) => {
        const choice = options.find((option) => option.id === event.currentTarget.value);
        if (choice !== undefined) { setText(prettyType(choice.type)); onChange(choice.type); }
      }}>
      {options.map((choice) => <option key={choice.id} value={choice.id}>{prettyType(choice.type)}</option>)}
    </select>
    <details>
      <summary>Custom type</summary>
      <label htmlFor={id}>Custom type expression</label>
      <input id={id} className="gl-input gl-mono" value={text} disabled={disabled}
        aria-invalid={error !== undefined} aria-describedby={`${id}-help`}
        onChange={(event) => setText(event.currentTarget.value)} />
      <p id={`${id}-help`} className="gl-dim">{error ?? "Use Int, Bool, and arrows: (Int -> Int) -> Bool."}</p>
      <button className="gl-button" type="button" disabled={disabled || error !== undefined || (parsed.ok && prettyType(parsed.type) === current)}
        onClick={() => { if (parsed.ok && error === undefined) onChange(parsed.type); }}>Apply type</button>
    </details>
  </div>;
}
