import { identityText } from "../graph/index.js";
import { fireControl } from "./control.js";
import { createContinuation } from "./continuation.js";
import { defaultScheduler, recomputeReadyFrontier, stepMachine } from "./primitive.js";
import { createMachineState, validateMachineState } from "./state.js";
import { createEnvironment } from "./value.js";
export class MachineRunError extends Error {
    name = "MachineRunError";
    code;
    /** Absent only when the run failed before an initial control existed. */
    control;
    steps;
    trace;
    diagnostics;
    constructor(code, message, control, steps, trace, diagnostics = []) {
        super(message);
        this.code = code;
        this.control = control;
        this.steps = steps;
        this.trace = trace;
        this.diagnostics = Object.freeze([...diagnostics]);
    }
}
const DEFAULT_MAX_STEPS = 10_000;
function traceEntry(index, rule, before, after) {
    return Object.freeze({
        kind: "MachineTraceEntry",
        index,
        rule,
        before,
        after
    });
}
function describeControl(control) {
    switch (control.kind) {
        case "Fire":
            return `Fire(${identityText(control.node)})`;
        case "Enter":
            return `Enter(${identityText(control.region)})`;
        case "Return":
            return `Return(${control.value.kind})`;
        case "Done":
            return `Done(${control.value.kind})`;
    }
}
function requireBudget(maxSteps) {
    if (!Number.isSafeInteger(maxSteps) || maxSteps < 1) {
        throw new RangeError(`A machine step budget must be a positive safe integer; received ${maxSteps}.`);
    }
    return maxSteps;
}
/**
 * Build the initial state for `G`: control fires the first ready node of the
 * root region under an empty environment, store, and continuation.
 *
 * The frontier is recomputed from `G` rather than supplied, so the initial
 * state is a function of the graph alone.
 */
export function createInitialMachineState(graph, scheduler = defaultScheduler) {
    const Q = recomputeReadyFrontier(graph, [], undefined, undefined, scheduler);
    const first = Q[0];
    if (first === undefined) {
        throw new MachineRunError("NO_INITIAL_READY_NODE", "The root region of the source graph has no ready node to fire.", undefined, 0, Object.freeze([]));
    }
    return createMachineState({
        c: fireControl(first),
        rho: createEnvironment(),
        sigma: [],
        kappa: createContinuation(),
        Q
    });
}
/**
 * Drive the base abstract machine over the fixed source graph `G` until its
 * control is `Done`, and report the final value with the transitions taken.
 *
 * The driver runs the existing `stepMachine` relation to completion; it holds
 * no evaluation rules of its own. It reads `G` and never writes to it, so the
 * same graph snapshot can be run repeatedly. Termination is deterministic on
 * the supported fragment because `stepMachine` is deterministic given a fixed
 * `options.scheduler`; a run that cannot reach `Done` fails loudly instead of
 * looping (which includes a caller-supplied scheduler that strands the
 * machine — see the safety note on `SchedulerPolicy` before supplying one).
 * The default scheduler reproduces every prior run's transition order
 * exactly, and reordering among simultaneously ready primitive dataflow
 * nodes never changes the final value.
 */
export function runMachineToCompletion(graph, options = {}) {
    const maxSteps = requireBudget(options.maxSteps ?? DEFAULT_MAX_STEPS);
    const scheduler = options.scheduler ?? defaultScheduler;
    const entries = [];
    let state = createInitialMachineState(graph, scheduler);
    while (state.c.kind !== "Done") {
        if (entries.length >= maxSteps) {
            throw new MachineRunError("STEP_BUDGET_EXHAUSTED", `The machine did not reach Done within ${maxSteps} transitions; ` +
                `control was ${describeControl(state.c)}. Raise maxSteps for a ` +
                "larger program, or treat this as non-termination.", state.c, entries.length, Object.freeze([...entries]));
        }
        const before = state.c;
        const step = stepMachine(graph, state, scheduler);
        if (step === undefined) {
            throw new MachineRunError("STUCK", `No base transition applies at ${describeControl(before)} after ` +
                `${entries.length} steps.`, before, entries.length, Object.freeze([...entries]));
        }
        state = step.state;
        entries.push(traceEntry(entries.length, step.rule, before, state.c));
        if (options.validateStates === true) {
            const diagnostics = validateMachineState(graph, state);
            if (diagnostics.length > 0) {
                throw new MachineRunError("INVALID_MACHINE_STATE", `The state after ${step.rule} violates G |- m ok: ` +
                    diagnostics.map(({ message }) => message).join("; "), state.c, entries.length, Object.freeze([...entries]), diagnostics);
            }
        }
    }
    return Object.freeze({
        kind: "MachineRun",
        value: state.c.value,
        steps: entries.length,
        trace: Object.freeze(entries)
    });
}
/** Render the last `count` transitions for a disagreement report. */
export function formatMachineTraceTail(trace, count = 12) {
    const tail = trace.slice(Math.max(0, trace.length - count));
    if (tail.length === 0)
        return "  (no transitions)";
    return tail
        .map((entry) => `  ${entry.index}: ${entry.rule} ` +
        `${describeControl(entry.before)} -> ${describeControl(entry.after)}`)
        .join("\n");
}
