import { parseExpressionText, prettyExpression } from "../calculus/index.js";
import { compileTermToGraph, TermGraphCompilationError } from "./term-to-graph.js";
/** Parse, type-check, and compile textual λG source into a fresh graph snapshot. */
export function compileTextToGraph(source, options = {}) {
    const parsed = parseExpressionText(source);
    if (!parsed.ok)
        return parsed;
    try {
        const graph = compileTermToGraph(parsed.expression, {
            ...(options.identityFactory === undefined
                ? {}
                : { identityFactory: options.identityFactory })
        });
        return Object.freeze({
            ok: true,
            expression: parsed.expression,
            graph,
            canonicalText: prettyExpression(parsed.expression),
            diagnostics: Object.freeze([])
        });
    }
    catch (error) {
        if (!(error instanceof TermGraphCompilationError))
            throw error;
        return Object.freeze({
            ok: false,
            diagnostics: Object.freeze(error.diagnostics.map((diagnostic) => Object.freeze({
                code: "TYPE_ERROR",
                checkerCode: diagnostic.code,
                path: diagnostic.path,
                message: diagnostic.message
            })))
        });
    }
}
