import {
  applyGraphEdit,
  createNodeForInput,
  createRecursiveFunction,
  duplicateSubgraph,
  extractFunction,
  insertNodeOnEdge,
  inputRegion,
  applyGraphEdits,
  type EdgeId,
  type Graph,
  type GraphEditAction,
  type GraphEditDiagnostic,
  type GraphIdentity,
  type IdentityFactory,
  type NodeId,
  type NodeKind,
  type NodePropertyUpdate,
  type PortId,
  type RegionId,
  type Type
} from "@graphlambda/core";

import { projectGraph } from "../canvas/layout.js";
import type { LayoutOffset, LayoutOffsets } from "../canvas/scene.js";

/**
 * Editor state.
 *
 * The split here is the whole point of this step. `graph` is semantics and is
 * only ever replaced by a snapshot `@graphlambda/core` returned; `layout` and
 * `focusedRegion` are presentation and never reach the core at all. No code in
 * this package constructs, rewrites, or type-checks a graph.
 */
export interface EditorDocument {
  readonly graph: Graph;
  /** `MoveVisualNode` displacements. Presentation only. */
  readonly layout: LayoutOffsets;
  /** The region the canvas is showing. Presentation only. */
  readonly focusedRegion: RegionId;
}

export type EditorSelection =
  | { readonly kind: "node"; readonly id: NodeId }
  | { readonly kind: "wire"; readonly id: EdgeId }
  | null;

export interface EditorState {
  readonly document: EditorDocument;
  readonly selection: EditorSelection;
  /** The port a connection was started from, if one is in progress. */
  readonly pendingSource: EditorPendingSource;
  /** Diagnostics from the most recent rejected edit. Always from core. */
  readonly diagnostics: readonly GraphEditDiagnostic[];
  readonly past: readonly EditorDocument[];
  readonly future: readonly EditorDocument[];
}

export type EditorPendingSource = { readonly port: PortId } | null;

/**
 * Everything the editor can do.
 *
 * The first five are dispatched into `applyGraphEdit` unchanged. The next
 * action installs a complete snapshot already produced by the core text
 * compiler. The remaining actions never leave this module: they are the
 * presentation half of the split above.
 */
export type EditorAction =
  | { readonly kind: "DuplicateNodes" | "ExtractFunction" | "DeleteNodes"; readonly nodes: readonly NodeId[] }
  | { readonly kind: "MoveVisualNodes"; readonly nodes: readonly NodeId[]; readonly dx: number; readonly dy: number }
  | { readonly kind: "InsertNode"; readonly edge: EdgeId; readonly request: CreateNodeRequest; readonly inputRole: string }
  | { readonly kind: "CreateRecursiveFunction"; readonly name: string; readonly type: Type }
  | CreateNodeRequest
  | { readonly kind: "CreateForInput"; readonly request: CreateNodeRequest; readonly target: PortId }
  | { readonly kind: "DeleteNode"; readonly node: NodeId }
  | { readonly kind: "Connect"; readonly source: PortId; readonly target: PortId }
  | { readonly kind: "Disconnect"; readonly edge: EdgeId }
  | { readonly kind: "SetNodeProperty"; readonly node: NodeId; readonly update: NodePropertyUpdate }
  | { readonly kind: "ReplaceGraph"; readonly graph: Graph; readonly preserveLayout?: boolean }
  | { readonly kind: "OpenDocument"; readonly document: EditorDocument }
  | { readonly kind: "MoveVisualNode"; readonly node: NodeId; readonly dx: number; readonly dy: number }
  | { readonly kind: "EnterRegion"; readonly region: RegionId }
  | { readonly kind: "ExitRegion" }
  | { readonly kind: "Select"; readonly selection: EditorSelection }
  | { readonly kind: "BeginConnection"; readonly port: PortId }
  | { readonly kind: "CancelConnection" }
  | { readonly kind: "Undo" }
  | { readonly kind: "Redo" };

export interface CreateNodeRequest {
  readonly kind: "CreateNode";
  readonly nodeKind: NodeKind;
  /** Desired centre of the new symbol, stored only in editor layout. */
  readonly position?: { readonly x: number; readonly y: number };
  readonly value?: number | boolean;
  readonly binderName?: string;
  readonly parameterType?: Type;
  readonly recursiveType?: Type;
  readonly definition?: NodeId;
}

/** The actions that change the graph. Everything else is presentation. */
const SEMANTIC_ACTIONS: ReadonlySet<string> = new Set([
  "CreateNode",
  "DeleteNode",
  "Connect",
  "Disconnect",
  "SetNodeProperty",
  "DuplicateNodes", "ExtractFunction", "DeleteNodes", "InsertNode",
  "CreateRecursiveFunction",
  "CreateForInput",
  "OpenDocument",
  "ReplaceGraph"
]);

/** True for an action that changes the persistent semantic graph. */
export function isSemanticAction(action: EditorAction): boolean {
  return SEMANTIC_ACTIONS.has(action.kind);
}

export function createEditorState(
  graph: Graph,
  focusedRegion?: RegionId
): EditorState {
  return Object.freeze({
    document: Object.freeze({
      graph,
      layout: new Map(),
      focusedRegion: focusedRegion ?? graph.rootRegion
    }),
    selection: null,
    pendingSource: null,
    diagnostics: Object.freeze([]),
    past: Object.freeze([]),
    future: Object.freeze([])
  });
}

/**
 * Builds the reducer for one editing session.
 *
 * The identity factory is a session-scoped resource: every identity the
 * session mints comes from it, so two entities created in one session can
 * never collide. Undo does not consult it — undo restores a previous snapshot,
 * which still holds the identities it always had, so nothing is re-minted and
 * no entity that already existed acquires a new NodeId.
 */
export function createEditorReducer(
  identities: IdentityFactory
): (state: EditorState, action: EditorAction) => EditorState {
  return (state, action) => reduce(state, action, identities);
}

function reduce(
  state: EditorState,
  action: EditorAction,
  identities: IdentityFactory
): EditorState {
  switch (action.kind) {
    case "MoveVisualNodes": {
      let layout = state.document.layout;
      for (const id of visualRoots(state.document.graph, action.nodes)) layout = displace(layout, id, action.dx, action.dy);
      return commit(state, { ...state.document, layout });
    }
    case "DuplicateNodes": {
      const result = duplicateSubgraph(state.document.graph, action.nodes, { identities });
      if (!result.ok) return { ...state, diagnostics: result.diagnostics };
      let layout = state.document.layout;
      const roots = new Set(visualRoots(state.document.graph, action.nodes));
      for (const [old, fresh] of result.nodeMap ?? []) {
        const offset = layout.get(old) ?? { dx: 0, dy: 0 };
        layout = new Map(layout).set(fresh, { dx: offset.dx + (roots.has(old) ? 40 : 0), dy: offset.dy + (roots.has(old) ? 40 : 0) });
      }
      return commit({ ...state, diagnostics: [], selection: null }, { ...state.document, graph: result.graph, layout });
    }
    case "ExtractFunction": {
      const result = extractFunction(state.document.graph, action.nodes, { identities });
      return result.ok ? commit({ ...state, diagnostics: [], selection: null }, { ...state.document, graph: result.graph })
        : { ...state, diagnostics: result.diagnostics };
    }
    case "DeleteNodes": {
      const roots = action.nodes.filter((id) => {
        let region = state.document.graph.regions.find((region) => region.id === state.document.graph.nodes.find((node) => node.id === id)?.region);
        while (region && region.owner !== null) {
          if (action.nodes.includes(region.owner)) return false;
          region = state.document.graph.regions.find((entry) => entry.id === region?.parent);
        }
        return true;
      });
      const result = applyGraphEdits(state.document.graph, roots.map((node) => ({ kind: "DeleteNode", node })), { identities });
      return result.ok ? commit({ ...state, diagnostics: [], selection: null }, { ...state.document, graph: result.graph, layout: forget(state.document.layout, result.removed) })
        : { ...state, diagnostics: result.diagnostics };
    }
    case "InsertNode": {
      const target = state.document.graph.edges.find((edge) => edge.id === action.edge)?.target;
      const actionNode = toGraphEditAction(action.request, target === undefined ? state.document.focusedRegion : inputRegion(state.document.graph, target));
      if (actionNode?.kind !== "CreateNode") return state;
      const result = insertNodeOnEdge(state.document.graph, action.edge, actionNode, action.inputRole, { identities });
      return result.ok ? commit({ ...state, diagnostics: [], selection: null }, { ...state.document, graph: result.graph })
        : { ...state, diagnostics: result.diagnostics };
    }
    case "CreateRecursiveFunction": {
      const result = createRecursiveFunction(state.document.graph, state.document.focusedRegion, action.name, action.type, { identities });
      if (!result.ok) return { ...state, diagnostics: result.diagnostics };
      const lambda = result.graph.nodes.find((node) => node.kind === "Lambda" && result.created.includes(node.id));
      const body = result.graph.regions.find((region) => region.owner === lambda?.id && region.role === "lambda-body");
      return commit({ ...state, selection: null, pendingSource: null, diagnostics: [] }, {
        ...state.document, graph: result.graph, focusedRegion: body?.id ?? state.document.focusedRegion });
    }
    case "OpenDocument":
      return { ...createEditorState(action.document.graph), document: action.document };
    case "CreateNode":
    case "CreateForInput":
    case "DeleteNode":
    case "Connect":
    case "Disconnect":
    case "SetNodeProperty":
      return dispatchToCore(state, action, identities);

    case "ReplaceGraph":
      return commit(
        {
          ...state,
          selection: null,
          pendingSource: null,
          diagnostics: Object.freeze([])
        },
        {
          graph: action.graph,
          layout: action.preserveLayout ? new Map([...state.document.layout].filter(([id]) => action.graph.nodes.some((node) => node.id === id))) : new Map(),
          focusedRegion: action.preserveLayout && action.graph.regions.some((region) => region.id === state.document.focusedRegion)
            ? state.document.focusedRegion : action.graph.rootRegion
        }
      );

    case "MoveVisualNode":
      return commit(state, {
        ...state.document,
        layout: displace(state.document.layout, action.node, action.dx, action.dy)
      });

    case "EnterRegion": {
      const region = state.document.graph.regions.find(
        (candidate) => candidate.id === action.region
      );
      if (region === undefined || action.region === state.document.focusedRegion) return state;
      const selection =
        state.selection?.kind === "node" && region.owner === state.selection.id
          ? state.selection
          : null;
      return commit(
        { ...state, selection },
        { ...state.document, focusedRegion: action.region }
      );
    }

    case "ExitRegion": {
      const current = state.document.graph.regions.find(
        (region) => region.id === state.document.focusedRegion
      );
      if (current === undefined || current.parent === null) return state;
      return commit(state, { ...state.document, focusedRegion: current.parent });
    }

    case "Select":
      return Object.freeze({
        ...state,
        selection: action.selection,
        pendingSource: null
      });

    case "BeginConnection":
      return Object.freeze({
        ...state,
        pendingSource: Object.freeze({ port: action.port }),
        diagnostics: Object.freeze([])
      });

    case "CancelConnection":
      return Object.freeze({ ...state, pendingSource: null });

    case "Undo": {
      const previous = state.past.at(-1);
      if (previous === undefined) return state;
      return Object.freeze({
        ...state,
        document: previous,
        selection: null,
        pendingSource: null,
        diagnostics: Object.freeze([]),
        past: Object.freeze(state.past.slice(0, -1)),
        future: Object.freeze([state.document, ...state.future])
      });
    }

    case "Redo": {
      const next = state.future[0];
      if (next === undefined) return state;
      return Object.freeze({
        ...state,
        document: next,
        selection: null,
        pendingSource: null,
        diagnostics: Object.freeze([]),
        past: Object.freeze([...state.past, state.document]),
        future: Object.freeze(state.future.slice(1))
      });
    }
  }
}

/**
 * Sends a semantic action to the core and records whatever comes back.
 *
 * On rejection the document is untouched and the diagnostics are stored
 * verbatim. Nothing here inspects them, rewrites them, or decides on its own
 * that an edit is invalid: the only judgement in this function is `result.ok`.
 */
function dispatchToCore(
  state: EditorState,
  action: EditorAction,
  identities: IdentityFactory
): EditorState {
  const edit = toGraphEditAction(action.kind === "CreateForInput" ? action.request : action, state.document.focusedRegion);
  if (edit === undefined) return state;

  const result = action.kind === "CreateForInput" && edit.kind === "CreateNode"
    ? createNodeForInput(state.document.graph, edit, action.target, { identities })
    : applyGraphEdit(state.document.graph, edit, { identities });

  if (!result.ok) {
    return Object.freeze({
      ...state,
      pendingSource: null,
      diagnostics: result.diagnostics
    });
  }

  let layout = action.kind === "DeleteNode"
    ? forget(state.document.layout, result.removed)
    : state.document.layout;

  if (action.kind === "CreateNode" && action.position !== undefined) {
    const created = result.graph.nodes.find((node) => !state.document.graph.nodes.some((previous) => previous.id === node.id));
    if (created !== undefined) {
      const projected = projectGraph(result.graph, { root: state.document.focusedRegion, offsets: layout }).nodes.find((node) => node.id === created.id);
      if (projected !== undefined) layout = displace(layout, created.id,
        action.position.x - projected.symbolBox.x - projected.symbolBox.width / 2,
        action.position.y - projected.symbolBox.y - projected.symbolBox.height / 2);
    }
  }

  return commit(
    {
      ...state,
      selection: action.kind === "SetNodeProperty" ? state.selection : null,
      pendingSource: null,
      diagnostics: Object.freeze([])
    },
    { ...state.document, graph: result.graph, layout }
  );
}

/**
 * Translates an editor action into a core action.
 *
 * The only thing added on the way is the region a new node belongs to, which
 * is the region the canvas is currently showing. That is presentation state
 * being read, not semantics being decided here.
 */
function toGraphEditAction(
  action: EditorAction,
  region: RegionId
): GraphEditAction | undefined {
  switch (action.kind) {
    case "CreateNode":
      return {
        kind: "CreateNode",
        nodeKind: action.nodeKind,
        region,
        ...(action.value === undefined ? {} : { value: action.value }),
        ...(action.binderName === undefined ? {} : { binderName: action.binderName }),
        ...(action.parameterType === undefined
          ? {}
          : { parameterType: action.parameterType }),
        ...(action.recursiveType === undefined
          ? {}
          : { recursiveType: action.recursiveType }),
        ...(action.definition === undefined ? {} : { definition: action.definition })
      };
    case "DeleteNode":
      return { kind: "DeleteNode", node: action.node };
    case "Connect":
      return { kind: "Connect", source: action.source, target: action.target };
    case "Disconnect":
      return { kind: "Disconnect", edge: action.edge };
    case "SetNodeProperty":
      return { kind: "SetNodeProperty", node: action.node, update: action.update };
    default:
      return undefined;
  }
}

/** Pushes the current document onto the undo stack and installs a new one. */
function commit(state: EditorState, document: EditorDocument): EditorState {
  return Object.freeze({
    ...state,
    document: Object.freeze(document),
    past: Object.freeze([...state.past, state.document]),
    future: Object.freeze([])
  });
}

function displace(
  layout: LayoutOffsets,
  node: NodeId,
  dx: number,
  dy: number
): LayoutOffsets {
  const current = layout.get(node);
  const next = new Map(layout);
  next.set(node, { dx: (current?.dx ?? 0) + dx, dy: (current?.dy ?? 0) + dy });
  return next;
}

/** Drops layout state for entities a delete removed. */
function forget(
  layout: LayoutOffsets,
  removed: readonly GraphIdentity[]
): LayoutOffsets {
  const gone = new Set<string>(removed);
  const next = new Map<NodeId, LayoutOffset>();
  for (const [node, offset] of layout) {
    if (!gone.has(node)) next.set(node, offset);
  }
  return next;
}

/** Moving an owner already carries its descendants; apply a group delta once. */
function visualRoots(graph: Graph, ids: readonly NodeId[]): readonly NodeId[] {
  return ids.filter((id) => {
    let region = graph.regions.find((entry) => entry.id === graph.nodes.find((node) => node.id === id)?.region);
    const seen = new Set<RegionId>();
    while (region && region.owner !== null && !seen.has(region.id)) {
      seen.add(region.id);
      if (ids.includes(region.owner)) return false;
      region = graph.regions.find((entry) => entry.id === region?.parent);
    }
    return true;
  });
}
