import { identityText, resolveSourceId } from "../graph/index.js";
import { machineProvenanceReferences } from "./provenance.js";
/**
 * `ids(G)`: every source identity the fixed graph resolves, in stable
 * node/port/edge/region order.
 */
export function graphSourceIds(graph) {
    return Object.freeze([
        ...graph.nodes.map((node) => node.id),
        ...graph.ports.map((port) => port.id),
        ...graph.edges.map((edge) => edge.id),
        ...graph.regions.map((region) => region.id)
    ]);
}
/** Whether `id` is resolvable in `G`, i.e. `id in ids(G)`. */
export function resolvesInGraph(graph, id) {
    return resolveSourceId(graph, id) !== undefined;
}
/**
 * `srcs(m)`: the source references stored directly inside the syntax-bearing
 * components of a base-machine state — control, closure code anchors, captured
 * ports, the port store, every suspended continuation frame with its caller
 * snapshots, and the ready frontier.
 *
 * All GraphLambda anchors are intrinsic: they are already fields of the state.
 * No side provenance map is maintained, so this is a pure read of `m` and can
 * never influence a transition.
 *
 * The walk itself lives in `provenance.ts`, which additionally records where
 * each reference was found and which identity domain that position requires.
 * `srcs(m)` is that walk with the extra structure dropped and duplicates
 * removed, in stable first-occurrence order.
 */
export function machineSourceReferences(state) {
    const seen = new Set();
    const collected = [];
    for (const subject of machineProvenanceReferences(state)) {
        const key = identityText(subject.id);
        if (seen.has(key))
            continue;
        seen.add(key);
        collected.push(subject.id);
    }
    return Object.freeze(collected);
}
/** The subset of `machineSourceReferences(m)` that `G` cannot resolve. */
export function unanchoredMachineReferences(graph, state) {
    return Object.freeze(machineSourceReferences(state).filter((id) => !resolvesInGraph(graph, id)));
}
