/** Constructs an immutable bottom-to-top continuation stack. */
export function createContinuation(frames = []) {
    const snapshot = Array.from(frames, immutableContinuationFrame);
    return snapshot.length === 0
        ? EMPTY_CONTINUATION
        : Object.freeze(snapshot);
}
/** Returns the pending frame at the top of kappa without changing kappa. */
export function peekContinuation(continuation) {
    return continuation[continuation.length - 1];
}
