import { useState, type JSX, type ReactNode } from "react";

import {
  arrowType,
  boolType,
  intType,
  prettyType,
  type GraphNode,
  type GraphEditDiagnostic,
  type GraphTextProjection,
  type NodeId,
  type NodePropertyUpdate,
  type TextCompilationDiagnostic,
  type Type
} from "@graphlambda/core";

import { TypePicker } from "../components/TypePicker.js";
import type { SceneNode, SceneWire } from "../canvas/scene.js";
import type { ExampleProgram } from "../examples/programs.js";
import type { RegionNavigationItem } from "../regions/region-navigation.js";
import type {
  ApplicationReport,
  GraphReport,
  LambdaBoundaryReport,
  WireReport
} from "./graph-report.js";

export interface InspectorProps {
  readonly resizeHandle?: ReactNode;
  readonly program: ExampleProgram;
  readonly report: GraphReport;
  readonly node: SceneNode | null;
  readonly semanticNode?: GraphNode | null;
  readonly declarationType?: Type | undefined;
  readonly wire: SceneWire | null;
  readonly wireReport?: WireReport | null;
  readonly lambdaBoundary?: LambdaBoundaryReport | null;
  readonly application?: ApplicationReport | null;
  /** Exact owner/role regions available from the selected semantic node. */
  readonly regions?: readonly RegionNavigationItem[];
  /** Diagnostics from the last rejected edit, exactly as core returned them. */
  readonly rejection: readonly GraphEditDiagnostic[];
  /** Current λG code projection derived from the source graph. */
  readonly generatedCode?: GraphTextProjection;
  readonly sourceText?: string;
  readonly sourceSynchronized?: boolean;
  readonly compilationDiagnostics?: readonly TextCompilationDiagnostic[];
  /** A starting term is only shown while the graph still matches it exactly. */
  readonly sourceStillMatches: boolean;
  /** Semantic edits are unavailable while a debugger session owns a fixed G. */
  readonly readOnly?: boolean;
  readonly onDeleteNode: (node: SceneNode) => void;
  readonly onDisconnect: (wire: SceneWire) => void;
  readonly onEnterRegion?: ((region: RegionNavigationItem) => void) | undefined;
  readonly onSourceTextChange?: ((text: string) => void) | undefined;
  readonly onCompileSource?: (() => void) | undefined;
  readonly onSetNodeProperty?: ((node: NodeId, update: NodePropertyUpdate) => void) | undefined;
}

type InspectorTab = "inspector" | "properties" | "code";

/** Dense source-entity inspector. All semantic facts are supplied by core reports. */
export function Inspector({
  resizeHandle,
  program,
  report,
  node,
  semanticNode = null,
  declarationType,
  wire,
  wireReport = null,
  lambdaBoundary = null,
  application = null,
  regions = Object.freeze([]),
  rejection,
  generatedCode,
  sourceText,
  sourceSynchronized = false,
  compilationDiagnostics = Object.freeze([]),
  sourceStillMatches,
  readOnly = false,
  onDeleteNode,
  onDisconnect,
  onEnterRegion,
  onSourceTextChange,
  onCompileSource,
  onSetNodeProperty
}: InspectorProps): JSX.Element {
  const [activeTab, setActiveTab] = useState<InspectorTab>("inspector");
  const tabs: readonly { readonly id: InspectorTab; readonly label: string }[] = [
    { id: "inspector", label: "Inspector" },
    { id: "properties", label: "Type / Properties" },
    { id: "code", label: "Source Code" }
  ];

  return (
    <aside className="gl-panel gl-panel--right" aria-label="Inspector">
      <div className="gl-panel-heading">
        <span>Source entity</span>
      </div>
      <div className="gl-panel-tabs" role="tablist" aria-label="Inspector views">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            type="button"
            role="tab"
            aria-selected={activeTab === tab.id}
            className={activeTab === tab.id ? "gl-panel-tab gl-panel-tab--active" : "gl-panel-tab"}
            onClick={() => setActiveTab(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </div>

      <div className="gl-panel-tab-content" role="tabpanel">
        {activeTab === "inspector" ? (
          <>
            {rejection.length === 0 ? null : <EditDiagnostics diagnostics={rejection} />}
            <SelectionView
              node={node}
              wire={wire}
              wireReport={wireReport}
              lambdaBoundary={lambdaBoundary}
              application={application}
              semanticNode={semanticNode}
              declarationType={declarationType}
              regions={regions}
              readOnly={readOnly}
              onDeleteNode={onDeleteNode}
              onDisconnect={onDisconnect}
              onEnterRegion={onEnterRegion}
              onSetNodeProperty={onSetNodeProperty}
            />
          </>
        ) : activeTab === "properties" ? (
          <PropertiesView
            program={program}
            report={report}
            sourceStillMatches={sourceStillMatches}
          />
        ) : activeTab === "code" ? (
          <SourceCodeView
            projection={generatedCode}
            sourceText={sourceText}
            synchronized={sourceSynchronized}
            diagnostics={compilationDiagnostics}
            readOnly={readOnly}
            onChange={onSourceTextChange}
            onCompile={onCompileSource}
          />
        ) : null}
      </div>
      {resizeHandle}
    </aside>
  );
}

function SourceCodeView({
  projection,
  sourceText,
  synchronized,
  diagnostics,
  readOnly,
  onChange,
  onCompile
}: {
  readonly projection: GraphTextProjection | undefined;
  readonly sourceText: string | undefined;
  readonly synchronized: boolean;
  readonly diagnostics: readonly TextCompilationDiagnostic[];
  readonly readOnly: boolean;
  readonly onChange: ((text: string) => void) | undefined;
  readonly onCompile: (() => void) | undefined;
}): JSX.Element {
  const text = sourceText ?? (projection?.status === "ready" ? projection.code : "");
  const editable = onChange !== undefined && onCompile !== undefined;
  return (
    <Section title="Textual λG source">
      <div className="gl-code-status" data-code-status={synchronized ? "ready" : "incomplete"}>
        <span className="gl-code-status-indicator" aria-hidden="true" />
        <span>{synchronized ? "Synchronized with flowchart" : "Draft not applied or flowchart incomplete"}</span>
      </div>
      <textarea
        className="gl-mono gl-source-editor"
        aria-label="Source code editor"
        value={text}
        readOnly={!editable || readOnly}
        spellCheck={false}
        onChange={(event) => onChange?.(event.currentTarget.value)}
        onKeyDown={(event) => {
          if ((event.ctrlKey || event.metaKey) && event.key === "Enter" && !readOnly) {
            event.preventDefault();
            onCompile?.();
          }
        }}
      />
      {diagnostics.length === 0 ? null : (
        <ul className="gl-diagnostics gl-source-diagnostics" aria-label="Source code diagnostics">
          {diagnostics.map((diagnostic, index) => (
            <li key={`${diagnostic.code}:${index}`}>
              <span className="gl-mono gl-diagnostic-code">
                {diagnostic.code === "TYPE_ERROR" ? diagnostic.checkerCode : diagnostic.code}
              </span>
              <span className="gl-diagnostic-message">{diagnostic.message}</span>
            </li>
          ))}
        </ul>
      )}
      <button
        type="button"
        className="gl-button gl-button--wide gl-compile-source"
        disabled={!editable || readOnly || text.trim().length === 0}
        onClick={() => onCompile?.()}
      >
        Update Flowchart
      </button>
      <p className="gl-code-note">Press Ctrl+Enter to parse, type-check, and replace the main flowchart.</p>
    </Section>
  );
}

function SelectionView({
  node,
  semanticNode,
  declarationType,
  wire,
  wireReport,
  lambdaBoundary,
  application,
  regions,
  readOnly,
  onDeleteNode,
  onDisconnect,
  onEnterRegion,
  onSetNodeProperty
}: {
  readonly node: SceneNode | null;
  readonly semanticNode: GraphNode | null;
  readonly declarationType: Type | undefined;
  readonly wire: SceneWire | null;
  readonly wireReport: WireReport | null;
  readonly lambdaBoundary: LambdaBoundaryReport | null;
  readonly application: ApplicationReport | null;
  readonly regions: readonly RegionNavigationItem[];
  readonly readOnly: boolean;
  readonly onDeleteNode: (node: SceneNode) => void;
  readonly onDisconnect: (wire: SceneWire) => void;
  readonly onEnterRegion?: ((region: RegionNavigationItem) => void) | undefined;
  readonly onSetNodeProperty?: ((node: NodeId, update: NodePropertyUpdate) => void) | undefined;
}): JSX.Element {
  return (
    <Section title="Selection">
      {node !== null ? (
        <>
          {application !== null ? (
            <ApplicationProperties application={application} node={node} />
          ) : (
            <>
              <h3 className="gl-inspector-entity">{entityName(node)}</h3>
              {lambdaBoundary === null ? null : (
                <LambdaProperties boundary={lambdaBoundary} owningRegion={node.region} />
              )}
              <PortTable node={node} />
              <details className="gl-advanced-details">
                <summary>Advanced / IDs</summary>
                <dl className="gl-facts">
                  <Fact label="Node" value={node.id} mono />
                  <Fact label="Region" value={node.region} mono />
                </dl>
              </details>
            </>
          )}
          {semanticNode === null || onSetNodeProperty === undefined ? null : (
            <NodePropertyEditor
              key={nodePropertyRevision(semanticNode, declarationType)}
              node={semanticNode}
              declarationType={declarationType}
              readOnly={readOnly}
              onUpdate={onSetNodeProperty}
            />
          )}
          {regions.length === 0 || onEnterRegion === undefined ? null : (
            <RegionNavigation regions={regions} onEnter={onEnterRegion} />
          )}
          <button
            type="button"
            className="gl-button gl-button--wide"
            disabled={readOnly}
            onClick={() => onDeleteNode(node)}
          >
            Delete Node
          </button>
        </>
      ) : wire !== null ? (
        <>
          <h3 className="gl-inspector-entity">{wire.wireKind === "binder" ? "Binder use" : "Value connection"}</h3>
          <dl className="gl-facts">
            <Fact label="Source" value={wireReport?.source ?? "Source port"} />
            <Fact label="Target" value={wireReport?.target ?? "Target port"} />
            <Fact label="Type" value={wireReport?.typeText ?? wire.typeText} mono />
            <Fact label="Status" value={wireReport?.status ?? "Connected"} />
            {wire.binderName === undefined ? null : <Fact label="Binder" value={wire.binderName} mono />}
            {(wire.captureRegions?.length ?? 0) > 0 ? <Fact label="Boundary" value="Lambda capture" /> : null}
          </dl>
          <details className="gl-advanced-details">
            <summary>Advanced / IDs</summary>
            <dl className="gl-facts">
              <Fact label="Edge" value={wire.id} mono />
              <Fact label="Source port" value={wire.source} mono />
              <Fact label="Target port" value={wire.target} mono />
            </dl>
          </details>
          <button
            type="button"
            className="gl-button gl-button--wide"
            disabled={readOnly}
            onClick={() => onDisconnect(wire)}
          >
            Disconnect
          </button>
        </>
      ) : lambdaBoundary !== null ? (
        <>
          <h3 className="gl-inspector-entity">Lambda</h3>
          <LambdaProperties boundary={lambdaBoundary} owningRegion="Focused region" />
        </>
      ) : (
        <p className="gl-empty">Nothing selected. Select a node, port, or wire on the canvas.</p>
      )}
    </Section>
  );
}

function nodePropertyRevision(node: GraphNode, declarationType: Type | undefined): string {
  const declaredType = declarationType === undefined ? "" : prettyType(declarationType);
  switch (node.kind) {
    case "IntLiteral": return `${node.id}:Int:${node.value}`;
    case "BoolLiteral": return `${node.id}:Bool:${String(node.value)}`;
    case "Lambda": return `${node.id}:Lambda:${node.parameter.displayName}:${declaredType}`;
    case "LetRec": return `${node.id}:LetRec:${node.recursive.displayName}:${declaredType}`;
    default: return node.id;
  }
}

const TYPE_CHOICES: readonly Type[] = Object.freeze([
  intType(),
  boolType(),
  arrowType(intType(), intType()),
  arrowType(boolType(), boolType()),
  arrowType(intType(), boolType()),
  arrowType(boolType(), intType())
]);

function NodePropertyEditor({
  node,
  declarationType,
  readOnly,
  onUpdate
}: {
  readonly node: GraphNode;
  readonly declarationType: Type | undefined;
  readonly readOnly: boolean;
  readonly onUpdate: (node: NodeId, update: NodePropertyUpdate) => void;
}): JSX.Element {
  const initialName = node.kind === "Lambda"
    ? node.parameter.displayName
    : node.kind === "LetRec"
      ? node.recursive.displayName
      : "";
  const [name, setName] = useState(initialName);
  const [integer, setInteger] = useState(node.kind === "IntLiteral" ? String(node.value) : "");


  if (node.kind === "IntLiteral") {
    const value = Number(integer);
    const valid = integer.trim().length > 0 && Number.isSafeInteger(value);
    return (
      <div className="gl-node-property-editor" aria-label="Editable node properties">
        <h3 className="gl-inspector-subtitle">Editable properties</h3>
        <label className="gl-property-field">
          <span>Integer Literal Value</span>
          <input
            className="gl-mono"
            type="number"
            step="1"
            value={integer}
            disabled={readOnly}
            aria-label="Integer Literal Value"
            onChange={(event) => setInteger(event.currentTarget.value)}
          />
        </label>
        <p className="gl-property-type">Static Type <span className="gl-mono">Int</span></p>
        <button type="button" className="gl-button gl-button--wide" disabled={readOnly || !valid || value === node.value}
          onClick={() => onUpdate(node.id, { kind: "IntLiteralValue", value })}>
          Apply Value
        </button>
      </div>
    );
  }

  if (node.kind === "BoolLiteral") {
    return (
      <div className="gl-node-property-editor" aria-label="Editable node properties">
        <h3 className="gl-inspector-subtitle">Editable properties</h3>
        <label className="gl-property-field">
          <span>Boolean Literal Value</span>
          <select
            value={String(node.value)}
            disabled={readOnly}
            aria-label="Boolean Literal Value"
            onChange={(event) => onUpdate(node.id, {
              kind: "BoolLiteralValue",
              value: event.currentTarget.value === "true"
            })}
          >
            <option value="true">true</option>
            <option value="false">false</option>
          </select>
        </label>
        <p className="gl-property-type">Static Type <span className="gl-mono">Bool</span></p>
      </div>
    );
  }

  if (node.kind === "Lambda" || node.kind === "LetRec") {
    const lambda = node.kind === "Lambda";
    const availableTypes = lambda
      ? TYPE_CHOICES
      : TYPE_CHOICES.filter((type) => type.kind === "Arrow");
    return (
      <div className="gl-node-property-editor" aria-label="Editable node properties">
        <h3 className="gl-inspector-subtitle">Editable properties</h3>
        <label className="gl-property-field">
          <span>{lambda ? "Parameter Name" : "Recursive Binder Name"}</span>
          <input
            className="gl-mono"
            value={name}
            disabled={readOnly}
            aria-label={lambda ? "Parameter Name" : "Recursive Binder Name"}
            onChange={(event) => setName(event.currentTarget.value)}
          />
        </label>
        <button
          type="button"
          className="gl-button gl-button--wide"
          disabled={readOnly || name.trim().length === 0 || name === initialName}
          onClick={() => onUpdate(node.id, lambda
            ? { kind: "LambdaParameterName", name }
            : { kind: "LetRecBinderName", name })}
        >
          Rename Binder
        </button>
        <div className="gl-property-field">
          <span>{lambda ? "Parameter Type" : "Recursive Binder Type"}</span>
          {declarationType === undefined ? <p>Declaration type unavailable.</p> : <TypePicker
            label={lambda ? "Parameter Type" : "Recursive Binder Type"}
            value={declarationType} disabled={readOnly} arrowsOnly={!lambda}
            choices={availableTypes.map((type) => ({ id: prettyType(type), type }))}
            onChange={(type) => onUpdate(node.id, lambda
              ? { kind: "LambdaParameterType", type } : { kind: "LetRecBinderType", type })} />}

        </div>
      </div>
    );
  }

  return (
    <p className="gl-property-type">
      This node has no intrinsic literal or declaration to edit; its port types are fixed or inferred from connections.
    </p>
  );
}

function PropertiesView({ program, report, sourceStillMatches }: {
  readonly program: ExampleProgram;
  readonly report: GraphReport;
  readonly sourceStillMatches: boolean;
}): JSX.Element {
  return (
    <>
      <Section title="Type checking">
        <ul className="gl-checks">
          <Check label="Well-formed" passed={report.wellFormed} />
          <Check label="Type-checked" passed={report.typeChecked} />
        </ul>
        {report.diagnostics.length === 0 ? null : (
          <ul className="gl-diagnostics">
            {report.diagnostics.map((diagnostic, index) => (
              <li key={`${diagnostic.source}:${diagnostic.subject}:${index}`}>
                <span className="gl-mono gl-diagnostic-code">{diagnostic.code}</span>
                <span className="gl-diagnostic-message">{diagnostic.message}</span>
              </li>
            ))}
          </ul>
        )}
      </Section>
      <Section title="Graph properties">
        <dl className="gl-facts">
          <Fact label="Nodes" value={report.nodes} />
          <Fact label="Ports" value={report.ports} />
          <Fact label="Edges" value={report.edges} />
          <Fact label="Binder uses" value={report.binderUses} />
          <Fact label="Regions" value={report.regions} />
          <Fact label="Open inputs" value={report.openInputs} />
        </dl>
      </Section>
      <Section title="Initial term">
        {sourceStillMatches ? (
          <pre className="gl-mono gl-source">{program.source === "" ? "(no source term)" : program.source}</pre>
        ) : (
          <p className="gl-empty">The active graph has changed. Open Source Code for synchronized text.</p>
        )}
      </Section>
    </>
  );
}

function EditDiagnostics({ diagnostics }: { readonly diagnostics: readonly GraphEditDiagnostic[] }): JSX.Element {
  return (
    <Section title="Edit refused">
      <ul className="gl-diagnostics" aria-label="Edit diagnostics">
        {diagnostics.map((diagnostic, index) => (
          <li key={`${diagnostic.code}:${diagnostic.subject}:${index}`}>
            <span className="gl-mono gl-diagnostic-code">{diagnostic.checkerCode ?? diagnostic.code}</span>
            <span className="gl-diagnostic-message">{diagnostic.message}</span>
            <span className="gl-diagnostic-origin">from {diagnostic.origin}</span>
          </li>
        ))}
      </ul>
    </Section>
  );
}

function LambdaProperties({ boundary, owningRegion }: {
  readonly boundary: LambdaBoundaryReport;
  readonly owningRegion: string;
}): JSX.Element {
  return (
    <>
      <dl className="gl-facts">
        <Fact label="Parameter" value={boundary.parameter} mono />
        <Fact label="Function type" value={boundary.functionType} mono />
        <Fact label="Body result" value={boundary.bodyResult} mono />
        <Fact label="Owning region" value={owningRegion} mono />
      </dl>
      <h3 className="gl-inspector-subtitle">Captured values</h3>
      {boundary.captures.length === 0 ? <p className="gl-empty">None</p> : (
        <dl className="gl-facts" aria-label="Captured values">
          {boundary.captures.map((capture) => (
            <div key={capture.source} style={{ display: "contents" }} data-captured-source={capture.source}>
              <Fact label={capture.displayName} value={capture.typeText} mono />
            </div>
          ))}
        </dl>
      )}
    </>
  );
}

function RegionNavigation({ regions, onEnter }: {
  readonly regions: readonly RegionNavigationItem[];
  readonly onEnter: (region: RegionNavigationItem) => void;
}): JSX.Element {
  return (
    <div className="gl-region-navigation" aria-label="Region navigation">
      <h3 className="gl-inspector-subtitle">Regions</h3>
      <div className="gl-region-navigation-actions">
        {regions.map((region) => (
          <button key={region.id} type="button" className="gl-button" data-region-purpose={region.purpose} onClick={() => onEnter(region)}>
            Open {region.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function ApplicationProperties({ application, node }: {
  readonly application: ApplicationReport;
  readonly node: SceneNode;
}): JSX.Element {
  return (
    <div className="gl-application-properties" aria-label="Application properties">
      <h3 className="gl-inspector-entity">Application</h3>
      <dl className="gl-facts">
        <Fact label="function" value={application.functionType} mono />
        <Fact label="argument" value={application.argumentType} mono />
        <Fact label="result" value={application.resultType} mono />
      </dl>
      <h3 className="gl-inspector-subtitle">Connections</h3>
      <dl className="gl-facts" aria-label="Application connections">
        {application.connections.map((connection) => (
          <div key={connection.role} style={{ display: "contents" }} data-application-connection={connection.role}>
            <Fact label={`${connection.role} ${connection.direction === "incoming" ? "←" : "→"}`} value={connection.peers.length === 0 ? "Unconnected" : connection.peers.join(", ")} />
          </div>
        ))}
      </dl>
      <details className="gl-advanced-details">
        <summary>Advanced / IDs</summary>
        <dl className="gl-facts">
          <Fact label="Node" value={node.id} mono />
          <Fact label="Region" value={node.region} mono />
        </dl>
        <PortTable node={node} />
      </details>
    </div>
  );
}

function PortTable({ node }: { readonly node: SceneNode }): JSX.Element {
  return (
    <table className="gl-ports">
      <thead><tr><th scope="col">Port</th><th scope="col">Dir</th><th scope="col">Type</th></tr></thead>
      <tbody>
        {node.ports.map((port) => (
          <tr key={port.id} data-type-class={port.typeClass}>
            <td>{port.role}</td>
            <td className="gl-dim">{port.direction === "input" ? "in" : "out"}</td>
            <td className="gl-mono">{port.typeText}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function entityName(node: SceneNode): string {
  if (node.nodeKind === "Lambda") return "Lambda";
  if (node.nodeKind === "LetRec") return "LetRec";
  return node.nodeKind;
}

function Section({ title, children }: { readonly title: string; readonly children: ReactNode }): JSX.Element {
  return <section className="gl-section"><h2 className="gl-section-title">{title}</h2>{children}</section>;
}

function Fact({ label, value, mono = false }: { readonly label: string; readonly value: string | number; readonly mono?: boolean }): JSX.Element {
  return <><dt>{label}</dt><dd className={mono ? "gl-mono gl-truncate" : undefined}>{value}</dd></>;
}

function Check({ label, passed }: { readonly label: string; readonly passed: boolean }): JSX.Element {
  return <li className={passed ? "gl-check gl-check--pass" : "gl-check gl-check--fail"}><span className="gl-mono gl-check-mark">{passed ? "OK" : "!!"}</span>{label}</li>;
}
