/**
 * A deterministic textual encoding for JSON-shaped data.
 *
 * `JSON.stringify` is not canonical: its output depends on object property
 * insertion order, so two structurally identical values can serialize
 * differently. This encoder sorts object keys, which makes the text a function
 * of the value alone. That is what lets a serialized snapshot be compared for
 * equality rather than merely inspected.
 */
function encodeNumber(value) {
    if (!Number.isFinite(value)) {
        throw new RangeError(`Canonical text cannot encode the non-finite number ${String(value)}.`);
    }
    // -0 and 0 are the same source value; collapsing them keeps the encoding a
    // function of the value rather than of how it was computed.
    return JSON.stringify(Object.is(value, -0) ? 0 : value);
}
function compareKeys(left, right) {
    if (left === right)
        return 0;
    return left < right ? -1 : 1;
}
/** Encodes a JSON-shaped value with object keys in sorted order. */
export function canonicalText(value) {
    if (value === null)
        return "null";
    switch (typeof value) {
        case "string":
            return JSON.stringify(value);
        case "number":
            return encodeNumber(value);
        case "boolean":
            return value ? "true" : "false";
    }
    if (Array.isArray(value)) {
        return `[${value.map(canonicalText).join(",")}]`;
    }
    const record = value;
    const keys = Object.keys(record).sort(compareKeys);
    return `{${keys
        .map((key) => `${JSON.stringify(key)}:${canonicalText(record[key])}`)
        .join(",")}}`;
}
/**
 * Structural equality on immutable plain data: primitives, arrays, and objects
 * with own enumerable string keys.
 *
 * Machine states are rebuilt rather than mutated by every transition, so two
 * runs of the same deterministic step produce equal but not identical states.
 * The SAVAM obligations compare those states, and this is the equality they
 * use. It is intentionally not a general deep-equal: it does not handle cycles,
 * maps, sets, dates, or class instances, none of which appear in a machine
 * state or a source graph.
 */
export function structurallyEqual(left, right) {
    if (left === right)
        return true;
    if (typeof left === "number" && typeof right === "number") {
        return Number.isNaN(left) && Number.isNaN(right);
    }
    if (typeof left !== "object" || typeof right !== "object")
        return false;
    if (left === null || right === null)
        return false;
    const leftIsArray = Array.isArray(left);
    if (leftIsArray !== Array.isArray(right))
        return false;
    if (leftIsArray) {
        const leftItems = left;
        const rightItems = right;
        if (leftItems.length !== rightItems.length)
            return false;
        return leftItems.every((item, index) => structurallyEqual(item, rightItems[index]));
    }
    const leftRecord = left;
    const rightRecord = right;
    const leftKeys = Object.keys(leftRecord).sort(compareKeys);
    const rightKeys = Object.keys(rightRecord).sort(compareKeys);
    if (leftKeys.length !== rightKeys.length)
        return false;
    if (!leftKeys.every((key, index) => key === rightKeys[index]))
        return false;
    return leftKeys.every((key) => structurallyEqual(leftRecord[key], rightRecord[key]));
}
