import { deserializeGraph, serializeGraph, type NodeId, type RegionId, type PortId } from "@graphlambda/core";
import type { EditorDocument } from "./editor-state.js";
import type { Viewport } from "../canvas/viewport.js";

export interface SavedDocument {
  readonly document: EditorDocument;
  readonly name: string;
  readonly breakpoints?: ReadonlySet<NodeId>;
  readonly watches?: readonly { readonly port: PortId; readonly name: string }[];
  readonly collapsedRegions: ReadonlySet<RegionId>;
  readonly viewport: Viewport | undefined;
  readonly sourceText: string;
  readonly sourceSynchronized: boolean;
}

/** Semantic serialization belongs to core; visual metadata has its own format. */
export function encodeDocument(saved: SavedDocument): string {
  return JSON.stringify({ format: "GraphLambdaDocument", version: 1,
    graph: serializeGraph(saved.document.graph), name: saved.name,
    layout: [...saved.document.layout], focusedRegion: saved.document.focusedRegion,
    collapsedRegions: [...saved.collapsedRegions], viewport: saved.viewport,
    breakpoints: [...(saved.breakpoints ?? [])], watches: saved.watches ?? [],
    sourceText: saved.sourceText, sourceSynchronized: saved.sourceSynchronized }, null, 2);
}

export function decodeDocument(text: string): SavedDocument {
  const value = JSON.parse(text) as Record<string, unknown>;
  if (value === null || value["format"] !== "GraphLambdaDocument" || value["version"] !== 1 || typeof value["graph"] !== "string") {
    throw new Error("Choose a GraphLambda document saved with Save document.");
  }
  const graph = deserializeGraph(value["graph"]);
  const region = (id: unknown): RegionId | undefined => graph.regions.find((entry) => entry.id === id)?.id;
  const layout = new Map<NodeId, { dx: number; dy: number }>();
  if (Array.isArray(value["layout"])) for (const pair of value["layout"]) {
    if (!Array.isArray(pair) || pair.length !== 2) throw new Error("Invalid document layout.");
    const node = graph.nodes.find((entry) => entry.id === pair[0]);
    const offset = pair[1] as { dx?: unknown; dy?: unknown } | null;
    if (node === undefined || (offset === null || typeof offset !== "object") || typeof offset.dx !== "number" || !Number.isFinite(offset.dx) ||
      typeof offset.dy !== "number" || !Number.isFinite(offset.dy)) throw new Error("Invalid document position.");
    layout.set(node.id, { dx: offset.dx, dy: offset.dy });
  }
  const collapsedRegions = new Set<RegionId>();
  if (Array.isArray(value["collapsedRegions"])) for (const id of value["collapsedRegions"]) {
    const found = region(id); if (found !== undefined && found !== graph.rootRegion) collapsedRegions.add(found);
  }
  const camera = value["viewport"] as Viewport | undefined;
  const viewport = camera && camera.center && [camera.center.x, camera.center.y, camera.width, camera.height, camera.zoom]
    .every((entry) => typeof entry === "number" && Number.isFinite(entry)) && camera.width > 0 && camera.height > 0 && camera.zoom > 0
    ? { center: { x: camera.center.x, y: camera.center.y }, width: camera.width, height: camera.height,
      zoom: Math.min(2, Math.max(0.25, camera.zoom)), mode: camera.mode === "overview" ? "overview" as const : "editing" as const } : undefined;
  const breakpoints = new Set<NodeId>();
  if (Array.isArray(value["breakpoints"])) for (const id of value["breakpoints"]) {
    const found = graph.nodes.find((node) => node.id === id); if (found) breakpoints.add(found.id);
  }
  const watches: { port: PortId; name: string }[] = [];
  if (Array.isArray(value["watches"])) for (const watch of value["watches"]) {
    if (watch === null || typeof watch !== "object") continue;
    const found = graph.ports.find((port) => port.id === watch.port);
    if (found && typeof watch.name === "string") watches.push({ port: found.id, name: watch.name.slice(0, 160) });
  }
  return { breakpoints, watches, document: { graph, layout, focusedRegion: region(value["focusedRegion"]) ?? graph.rootRegion },
    name: typeof value["name"] === "string" ? value["name"].slice(0, 160) : "Untitled",
    collapsedRegions, viewport, sourceText: typeof value["sourceText"] === "string" ? value["sourceText"] : "",
    sourceSynchronized: value["sourceSynchronized"] === true };
}

export function readDraft(id: string): SavedDocument | undefined {
  try {
    const text = typeof window === "undefined" ? null : window.localStorage.getItem(`graphlambda-draft:${id}`);
    return text === null ? undefined : decodeDocument(text);
  } catch { return undefined; }
}

export function readLastProgram(fallback: string): string {
  try { return typeof window === "undefined" ? fallback : window.localStorage.getItem("graphlambda-last-program") ?? fallback; }
  catch { return fallback; }
}
