/**
 * Projects a source graph to a Scene.
 *
 * The projection is a pure function of the graph's *content*. It never mutates
 * the graph, never stores a coordinate in it, and — because every collection it
 * walks is re-sorted by identity first — produces the same Scene for two graphs
 * that differ only in the storage order of their `nodes`, `ports`, `edges`, or
 * `regions` arrays. The layout is therefore semantics-free in both directions:
 * geometry cannot reach the graph, and the graph's incidental array order
 * cannot reach the geometry.
 */
export function projectGraph(
  graph: Graph,
  options: ProjectionOptions = {}
): Scene {
  return new Projection(graph, options).run();
}

/**
 * Compares two identity strings so that `node:oracle:9` sorts before
 * `node:oracle:11`. Plain lexicographic order would interleave them, which
 * makes a layout look shuffled without being wrong.
 */
function compareIdentity(left: string, right: string): number {
  const pattern = /\d+|\D+/g;
  const leftParts = left.match(pattern) ?? [];
  const rightParts = right.match(pattern) ?? [];
  const shared = Math.min(leftParts.length, rightParts.length);

  for (let index = 0; index < shared; index += 1) {
    const a = leftParts[index] ?? "";
    const b = rightParts[index] ?? "";
    if (a === b) continue;

    const aNumeric = /^\d+$/.test(a);
    const bNumeric = /^\d+$/.test(b);

    if (aNumeric && bNumeric) {
      const difference = Number(a) - Number(b);
      if (difference !== 0) return difference;
      continue;
    }

    return a < b ? -1 : 1;
  }

  return leftParts.length - rightParts.length;
}

function byIdentity<T extends { readonly id: string }>(
  values: readonly T[]
): readonly T[] {
  return [...values].sort((left, right) => compareIdentity(left.id, right.id));
}

/** Where a port sits relative to the node that owns it. */
interface GutterAssignment {
  readonly regionRole: string;
  readonly side: "left" | "right";
}

/**
 * Ports that belong on a region frame rather than on the owning node's frame.
 *
 * A Lambda's `parameter` is an output port whose consumers all live inside the
 * body, and its `body` input is fed from inside that same region. Both are
 * boundary ports of the region, and drawing them on the node frame would send
 * every one of their wires back across the frame they just left. The same
 * holds for LetRec's binder and for the two branch results of an If.
 */
const REGION_GUTTER_PORTS: ReadonlyMap<string, GutterAssignment> = new Map<
  string,
  GutterAssignment
>([
  ["Lambda:parameter", { regionRole: "lambda-body", side: "left" }],
  ["Lambda:body", { regionRole: "lambda-body", side: "right" }],
  ["LetRec:recursive", { regionRole: "letrec-scope", side: "left" }],
  ["LetRec:definition", { regionRole: "letrec-scope", side: "right" }],
  ["LetRec:body", { regionRole: "letrec-scope", side: "right" }],
  ["If:then", { regionRole: "if-then", side: "right" }],
  ["If:else", { regionRole: "if-else", side: "right" }]
]);

const REGION_ROLE_ORDER: readonly string[] = [
  "lambda-body",
  "letrec-scope",
  "if-then",
  "if-else"
];

function regionRoleRank(role: string): number {
  const index = REGION_ROLE_ORDER.indexOf(role);
  return index === -1 ? REGION_ROLE_ORDER.length : index;
}

interface RegionBlock {
  readonly region: Region;
  readonly label: string;
  readonly width: number;
  readonly height: number;
  /** Offset from the origin of whatever contains this region. */
  readonly x: number;
  readonly y: number;
  readonly nodes: readonly NodeBlock[];
  readonly leftGutter: readonly Port[];
  readonly rightGutter: readonly Port[];
  readonly leftGutterWidth: number;
  readonly rightGutterWidth: number;
}

interface NodeBlock {
  readonly node: GraphNode;
  readonly width: number;
  readonly height: number;
  readonly symbolX: number;
  readonly symbolWidth: number;
  readonly symbolHeight: number;
  /** Offset from the content origin of the region containing this node. */
  readonly x: number;
  readonly y: number;
  readonly topPorts: readonly Port[];
  readonly leftPorts: readonly Port[];
  readonly rightPorts: readonly Port[];
  readonly regions: readonly RegionBlock[];
}

class Projection {
  readonly #graph: Graph;
  readonly #portOwner: ReadonlyMap<PortId, NodeId>;
  readonly #portTypes: ReadonlyMap<PortId, OpenInputExpectedType>;
  readonly #connectedInputs: ReadonlySet<PortId>;
  readonly #binderNames: ReadonlyMap<string, string>;
  /** The edges core reports as recursive occurrences, by identity text. */
  readonly #recursive: ReadonlySet<string>;
  readonly #captures: ReadonlyMap<RegionId, readonly RegionCapture[]>;

  readonly #offsets: LayoutOffsets;
  readonly #collapsedRegions: ReadonlySet<RegionId>;
  readonly #viewRoot: RegionId;

  readonly #regions: SceneRegion[] = [];
  readonly #nodes: SceneNode[] = [];
  readonly #ports = new Map<PortId, ScenePort>();
  /** Fixed content anchors from automatic placement, before any displacement. */
  readonly #contentAnchors = new Map<RegionId, Point>();

  constructor(graph: Graph, options: ProjectionOptions) {
    this.#graph = graph;
    this.#offsets = new Map([...(options.offsets ?? [])].filter(([, offset]) => offset.dx !== 0 || offset.dy !== 0));
    this.#collapsedRegions = options.collapsedRegions ?? new Set();
    this.#viewRoot = options.root ?? graph.rootRegion;
    this.#portOwner = new Map(graph.ports.map((port) => [port.id, port.owner]));
    this.#portTypes = collectPortTypes(graph);
    this.#connectedInputs = new Set(graph.edges.map((edge) => edge.target));
    this.#binderNames = collectBinderNames(graph);
    this.#recursive = new Set(
      recursiveOccurrences(graph).map((use) => identityText(use.id))
    );
    this.#captures = new Map(graph.regions.map((region) =>
      [region.id, getRegionCaptures(graph, region.id)]));
  }

  run(): Scene {
    const rootRegion = this.#graph.regions.find(
      (region) => region.id === this.#viewRoot
    );

    if (rootRegion === undefined) {
      throw new Error(
        `Cannot project a graph whose view root ${identityText(
          this.#viewRoot
        )} is missing.`
      );
    }

    if (this.#offsets.size === 0) {
      const root = this.#layoutRegion(rootRegion, 0, 0);
      this.#emitRegion(root, SCENE_MARGIN, SCENE_MARGIN, 0, 0, 0);
    } else {
      // Automatic placement includes fully fitted children. User displacement
      // is relative to that stable layout, never to a previous rendered frame.
      const automatic = new Projection(this.#graph, {
        root: this.#viewRoot,
        collapsedRegions: this.#collapsedRegions
      });
      const baseline = automatic.run();
      this.#regions.push(...baseline.regions);
      this.#nodes.push(...baseline.nodes);
      for (const port of baseline.ports) this.#ports.set(port.id, port);
      for (const [id, anchor] of automatic.#contentAnchors) this.#contentAnchors.set(id, anchor);
      for (const [id, offset] of this.#offsets) {
        this.#translateSubtree(id, offset.dx, offset.dy, [], [], []);
      }
    }

    const connections = this.#fitHierarchy();
    const variableUses = this.#refineVariableUses(
      connections.wires,
      connections.variableUses
    );
    const bounds = this.#bounds(
      connections.wires,
      connections.junctions,
      variableUses
    );

    return Object.freeze({
      kind: "Scene" as const,
      origin: Object.freeze({ x: bounds.x, y: bounds.y }),
      width: bounds.width,
      height: bounds.height,
      root: this.#viewRoot,
      regions: Object.freeze([...this.#regions]),
      nodes: Object.freeze([...this.#nodes]),
      ports: Object.freeze([...this.#ports.values()]),
      wires: Object.freeze(connections.wires),
      variableUses: Object.freeze(variableUses),
      junctions: Object.freeze(connections.junctions)
    });
  }

  /**
   * Owner fitting can move a nested symbol after its internal binder glyph was
   * first placed. Re-evaluate those annotations against the final scene so a
   * variable use cannot finish on top of a literal or process symbol.
   */
  #refineVariableUses(
    wires: readonly SceneWire[],
    uses: readonly SceneVariableUse[]
  ): SceneVariableUse[] {
    const obstacles = [
      ...this.#nodes.map((node) => expandBox(node.symbolBox, WIRE_CLEARANCE / 2)),
      ...this.#regions.map((region) => box(region.box.x, region.box.y,
        region.box.width, REGION_HEADER_HEIGHT)),
      ...[...this.#ports.values()].map((port) => port.labelBox)
    ];
    const placed: SceneVariableUse[] = [];

    for (const use of uses) {
      const wire = wires.find((candidate) => candidate.id === use.edge);
      if (wire === undefined) continue;
      const otherRoutes = wires.filter((other) => other.source !== wire.source)
        .flatMap((other) => other.route.slice(1).map((to, index) => {
          const from = other.route[index]!;
          return expandBox(box(Math.min(from.x, to.x), Math.min(from.y, to.y),
            Math.abs(to.x - from.x), Math.abs(to.y - from.y)), GRID / 2);
        }));
      const next = Object.freeze({
        ...use,
        box: variableUseBox(wire.route, use.box.width, use.box.height,
          [...obstacles, ...otherRoutes])
      });
      placed.push(next);
      obstacles.push(expandBox(next.box, GRID / 2));
    }

    return placed;
  }

  /**
   * The painted extent.
   *
   * Bounds are measured from what was actually emitted rather than from the
   * root block's size, because a `MoveVisualNode` displacement can push a node
   * outside its automatic position — including above or to the left of the
   * origin, which is why the scene carries an origin at all.
   */
  #bounds(
    wires: readonly SceneWire[],
    junctions: readonly SceneJunction[],
    variableUses: readonly SceneVariableUse[]
  ): Box {
    let minX = Number.POSITIVE_INFINITY;
    let minY = Number.POSITIVE_INFINITY;
    let maxX = Number.NEGATIVE_INFINITY;
    let maxY = Number.NEGATIVE_INFINITY;

    const cover = (x: number, y: number, width: number, height: number): void => {
      minX = Math.min(minX, x);
      minY = Math.min(minY, y);
      maxX = Math.max(maxX, x + width);
      maxY = Math.max(maxY, y + height);
    };

    for (const region of this.#regions) {
      cover(region.box.x, region.box.y, region.box.width, region.box.height);
    }
    for (const node of this.#nodes) {
      cover(node.box.x, node.box.y, node.box.width, node.box.height);
    }
    for (const port of this.#ports.values()) cover(port.x, port.y, 0, 0);
    for (const port of this.#ports.values()) {
      cover(
        port.labelBox.x,
        port.labelBox.y,
        port.labelBox.width,
        port.labelBox.height
      );
    }
    for (const wire of wires) {
      for (const point of wire.route) cover(point.x, point.y, 0, 0);
      if (wire.typeLabel !== undefined) {
        cover(
          wire.typeLabel.box.x,
          wire.typeLabel.box.y,
          wire.typeLabel.box.width,
          wire.typeLabel.box.height
        );
      }
    }
    for (const junction of junctions) cover(junction.point.x, junction.point.y, 0, 0);
    for (const use of variableUses) {
      cover(use.box.x, use.box.y, use.box.width, use.box.height);
    }

    if (!Number.isFinite(minX)) return box(0, 0, 2 * SCENE_MARGIN, 2 * SCENE_MARGIN);

    return box(
      minX - SCENE_MARGIN,
      minY - SCENE_MARGIN,
      maxX - minX + 2 * SCENE_MARGIN,
      maxY - minY + 2 * SCENE_MARGIN
    );
  }

  // --- measurement -------------------------------------------------------

  /**
   * Fit once, from the deepest region outwards. Child positions are anchored
   * by automatic placement plus explicit offsets; fitting never feeds a new
   * position back into that placement. Each edge is routed once, at its lowest
   * common visual container, after both endpoints have been placed. Ancestors
   * then contain the finished child frame, routes and annotations. There is no
   * render/measure loop and no dimensions to retain in editor or source state.
   */
  #fitHierarchy(): {
    wires: SceneWire[];
    junctions: SceneJunction[];
    variableUses: SceneVariableUse[];
  } {
    const wires: SceneWire[] = [];
    const junctions: SceneJunction[] = [];
    const variableUses: SceneVariableUse[] = [];
    const order = [...this.#regions].sort((a, b) => b.depth - a.depth);

    for (const initial of order) {
      // A collapsed region keeps its semantic boundary ports and compact
      // frame, but emits no descendants or internal routing.
      if (initial.collapsed) continue;
      // The automatic projection already fitted unchanged subtrees. Refit
      // only containers with a displaced descendant; fitting them a second
      // time can otherwise enlarge an unrelated owner around a new route.
      const displacedInside = [...this.#offsets].some(([id, offset]) => {
        if (offset.dx === 0 && offset.dy === 0) return false;
        const source = this.#graph.nodes.find((node) => node.id === id);
        return source !== undefined && this.#regionAncestors(source.region).includes(initial.id);
      });
      if (this.#offsets.size > 0 && !displacedInside) {
        const connections = this.#buildWires(initial.id);
        wires.push(...connections.wires);
        junctions.push(...connections.junctions);
        variableUses.push(...this.#buildVariableUses(connections.wires));
        continue;
      }
      // Direct children already include every region they own. Their own
      // coordinates stay fixed even if this frame grows left or upwards.
      const members = this.#nodes.filter((node) => node.region === initial.id);
      for (const member of members) {
        this.#fitOwner(member.id, wires, junctions, variableUses);
      }
      if (this.#offsets.size === 0) {
        const anchor = this.#contentAnchors.get(initial.id)!;
        const blocks = byIdentity(this.#nodes.filter((node) => node.region === initial.id))
          .map((node) => ({ node: this.#graph.nodes.find((source) => source.id === node.id)!,
            width: node.box.width, height: node.box.height }));
        for (const block of this.#placeInLayers(initial.id, blocks)) {
          const child = this.#nodes.find((node) => node.id === block.node.id)!;
          this.#translateSubtree(child.id, anchor.x + block.x - child.box.x,
            anchor.y + block.y - child.box.y, wires, junctions, variableUses);
        }
      } else {
        this.#clearExpandedFrames(members, wires, junctions, variableUses);
      }
      const children = this.#nodes.filter((node) => node.region === initial.id);
      const anchor = this.#contentAnchors.get(initial.id)!;
      const content = unionBoxes([
        box(anchor.x, anchor.y, REGION_MIN_CONTENT_WIDTH, REGION_MIN_CONTENT_HEIGHT),
        ...children.map((node) => node.box),
        ...children.flatMap((node) => node.ports.map((port) => this.#ports.get(port.id)!)
          .filter((port) => port.region === undefined)
          .flatMap((port) => [port.labelBox, portPaintBox(port)]))
      ]);
      const boundaryPorts = initial.owner === null ? { left: [], right: [] } :
        this.#gutterPorts(initial.owner, initial.role);
      const left = this.#gutterWidth(boundaryPorts.left);
      const right = this.#gutterWidth(boundaryPorts.right);
      const padding = REGION_CONTENT_PADDING;
      const labelWidth = estimateTextWidth(initial.label, FONT_SIZE_REGION_LABEL, true) +
        2 * REGION_PADDING + (initial.owner === null ? 0 : 2 * REGION_NAV_WIDTH);
      const draft = box(
        content.x - left - padding,
        content.y - padding - REGION_HEADER_HEIGHT,
        Math.max(content.width + left + right + 2 * padding, labelWidth),
        content.height + 2 * padding + REGION_HEADER_HEIGHT
      );
      const index = this.#regions.findIndex((region) => region.id === initial.id);
      this.#regions[index] = Object.freeze({ ...initial, box: draft });

      for (const side of ["region-left", "region-right"] as const) {
        const boundary = [...this.#ports.values()].filter(
          (port) => port.region === initial.id && port.placement === side
        );
        // Captured source labels share the binder gutter. Reserve a full
        // occurrence row so the binder's inline glyph cannot cover them.
        const hasCapture = boundary.some((port) => port.capture);
        const pitch = hasCapture ? 2 * GUTTER_ROW_HEIGHT : GUTTER_ROW_HEIGHT;
        boundary.forEach((port, row) => {
          const x = side === "region-left"
            ? draft.x + (hasCapture
              ? REGION_PADDING + Math.max(...boundary.map((entry) => entry.labelBox.width)) / 2
              : left / 2)
            : draft.x + draft.width - right / 2;
          this.#movePort(port, x, content.y + row * pitch);
        });
      }

      const connections = this.#buildWires(initial.id);
      const uses = this.#buildVariableUses(connections.wires);
      wires.push(...connections.wires);
      junctions.push(...connections.junctions);
      variableUses.push(...uses);

      // The header is placed above the actual union, including any routing
      // detour. It cannot push a child, change an endpoint, or cause rerouting.
      const interior = unionBoxes([
        box(draft.x, draft.y + REGION_HEADER_HEIGHT, draft.width,
          draft.height - REGION_HEADER_HEIGHT),
        ...[...this.#ports.values()].filter((port) => port.region === initial.id)
          .flatMap((port) => [port.labelBox, portPaintBox(port)]),
        ...connections.wires.flatMap((wire) => [
          ...wire.route.map((point) => box(point.x - 4, point.y - 4, 8, 8)),
          ...(wire.typeLabel === undefined ? [] : [wire.typeLabel.box]),
          ...(wire.feedback ? [box(wire.midpoint.x - 8, wire.midpoint.y - 8, 16, 16)] : [])
        ]),
        ...uses.map((use) => use.box)
      ]);
      const fitted = box(interior.x - REGION_PADDING,
        interior.y - REGION_HEADER_HEIGHT - REGION_PADDING,
        interior.width + 2 * REGION_PADDING,
        interior.height + REGION_HEADER_HEIGHT + 2 * REGION_PADDING);
      this.#regions[index] = Object.freeze({
        ...initial,
        box: fitted,
        gutters: Object.freeze({
          left: left + draft.x - fitted.x,
          right: right + fitted.x + fitted.width - draft.x - draft.width
        })
      });
    }

    // Refresh owned port references after boundary relocation. Semantic ids
    // and ownership have not changed; only ScenePort instances were replaced.
    for (let index = 0; index < this.#nodes.length; index += 1) {
      const node = this.#nodes[index]!;
      this.#nodes[index] = Object.freeze({
        ...node, ports: Object.freeze(node.ports.map((port) => this.#ports.get(port.id)!))
      });
    }
    return {
      wires: [...byIdentity(wires)],
      junctions: [...new Map(junctions.map((junction) => [junction.source, junction])).values()]
        .sort((a, b) => compareIdentity(a.source, b.source)),
      variableUses: variableUses.sort((a, b) => compareIdentity(a.edge, b.edge))
    };
  }

  /**
   * A growing frame must not visually adopt an unrelated automatic sibling.
   * Keep explicitly displaced subtrees pinned, and move obstructed automatic
   * siblings rightward in a finite sweep. Small moves which fit the existing
   * frame do not reflow anything. This is derived geometry, not a saved offset.
   */
  #clearExpandedFrames(
    previous: readonly SceneNode[],
    wires: SceneWire[], junctions: SceneJunction[], uses: SceneVariableUse[]
  ): void {
    const children = previous.map((node) => this.#nodes.find((child) => child.id === node.id)!);
    const expanded = children.filter((node, index) => {
      const before = previous[index]!.box;
      return node.ownedRegions.length > 0 &&
        (node.box.x < before.x || node.box.y < before.y ||
          node.box.x + node.box.width > before.x + before.width ||
          node.box.y + node.box.height > before.y + before.height);
    });
    if (expanded.length === 0) return;
    const pinned = new Set(children.filter((node) => expanded.includes(node) ||
      [...this.#offsets].some(([id, offset]) => {
        if (offset.dx === 0 && offset.dy === 0) return false;
        const source = this.#graph.nodes.find((entry) => entry.id === id);
        return id === node.id || (source !== undefined &&
          this.#regionAncestors(source.region).some((region) => node.ownedRegions.includes(region)));
      })).map((node) => node.id));
    const obstacles = children.filter((node) => pinned.has(node.id)).map((node) => node.box);
    const automatic = [...byIdentity(children)].filter((node) => !pinned.has(node.id))
      .sort((a, b) => a.box.x - b.box.x || a.box.y - b.box.y);
    for (const node of automatic) {
      let placed = node.box;
      // Every collision advances past one obstacle's right edge; sorting by
      // that edge makes one pass sufficient, with no resize/convergence loop.
      for (const obstacle of [...obstacles].sort((a, b) => a.x + a.width - b.x - b.width)) {
        if (placed.x < obstacle.x + obstacle.width && placed.x + placed.width > obstacle.x &&
          placed.y < obstacle.y + obstacle.height && placed.y + placed.height > obstacle.y) {
          placed = box(obstacle.x + obstacle.width + LAYER_GAP, placed.y, placed.width, placed.height);
        }
      }
      this.#translateSubtree(node.id, placed.x - node.box.x, 0, wires, junctions, uses);
      obstacles.push(placed);
    }
  }

  /** Rigidly moves already-fitted descendants without changing their sizes. */
  #translateSubtree(
    id: NodeId, dx: number, dy: number,
    wires: SceneWire[], junctions: SceneJunction[], uses: SceneVariableUse[]
  ): void {
    const owned = this.#regions.filter((region) => region.owner === id).map((region) => region.id);
    const regions = new Set(this.#regions.filter((region) =>
      this.#regionAncestors(region.id).some((ancestor) => owned.includes(ancestor)))
      .map((region) => region.id));
    const nodes = new Set(this.#nodes.filter((node) => node.id === id || regions.has(node.region))
      .map((node) => node.id));
    const shift = (bounds: Box): Box => box(bounds.x + dx, bounds.y + dy, bounds.width, bounds.height);
    for (let index = 0; index < this.#nodes.length; index += 1) {
      const node = this.#nodes[index]!;
      if (nodes.has(node.id)) this.#nodes[index] = Object.freeze({
        ...node, box: shift(node.box), symbolBox: shift(node.symbolBox)
      });
    }
    for (let index = 0; index < this.#regions.length; index += 1) {
      const region = this.#regions[index]!;
      if (!regions.has(region.id)) continue;
      this.#regions[index] = Object.freeze({ ...region, box: shift(region.box) });
      const anchor = this.#contentAnchors.get(region.id)!;
      this.#contentAnchors.set(region.id, Object.freeze({ x: anchor.x + dx, y: anchor.y + dy }));
    }
    const ports = new Set<PortId>();
    for (const port of this.#ports.values()) {
      if (!nodes.has(port.owner)) continue;
      ports.add(port.id);
      this.#movePort(port, port.x + dx, port.y + dy);
    }
    for (let index = 0; index < wires.length; index += 1) {
      const wire = wires[index]!;
      if (!ports.has(wire.source) || !ports.has(wire.target)) continue;
      const route = Object.freeze(wire.route.map((point) =>
        Object.freeze({ x: point.x + dx, y: point.y + dy })));
      wires[index] = Object.freeze({ ...wire, route, path: routedWirePath(route),
        midpoint: Object.freeze({ x: wire.midpoint.x + dx, y: wire.midpoint.y + dy }),
        typeLabel: wire.typeLabel === undefined ? undefined :
          Object.freeze({ ...wire.typeLabel, box: shift(wire.typeLabel.box) }) });
    }
    for (let index = 0; index < junctions.length; index += 1) {
      const junction = junctions[index]!;
      if (ports.has(junction.source)) junctions[index] = Object.freeze({ ...junction,
        point: Object.freeze({ x: junction.point.x + dx, y: junction.point.y + dy }) });
    }
    for (let index = 0; index < uses.length; index += 1) {
      const use = uses[index]!;
      if (ports.has(use.source) && ports.has(use.target)) {
        uses[index] = Object.freeze({
          ...use,
          box: shift(use.box),
          anchor: Object.freeze({ x: use.anchor.x + dx, y: use.anchor.y + dy })
        });
      }
    }
  }

  #fitOwner(
    id: NodeId,
    wires: SceneWire[],
    junctions: SceneJunction[],
    uses: SceneVariableUse[]
  ): void {
    const index = this.#nodes.findIndex((node) => node.id === id);
    const node = this.#nodes[index]!;
    const owned = this.#regions.filter((region) => region.owner === id);
    if (owned.length === 0) return;

    if (node.nodeKind === "If") {
      const branches = ["if-then", "if-else"].flatMap((role) => {
        const region = owned.find((candidate) => candidate.role === role);
        return region === undefined ? [] : [region];
      });
      let cursor = Math.min(...branches.map((region) => region.box.x));
      for (const branch of branches) {
        this.#translateRegion(
          branch.id,
          cursor - branch.box.x,
          0,
          wires,
          junctions,
          uses
        );
        const moved = this.#regions.find((region) => region.id === branch.id)!;
        cursor += moved.box.width + REGION_GAP;
      }
    }

    const fittedOwned = this.#regions.filter((region) => region.owner === id);
    const regions = unionBoxes(
      fittedOwned.map((region) => expandBox(region.box, NODE_BODY_PADDING))
    );
    const y = Math.min(node.symbolBox.y, regions.y - node.symbolBox.height);
    const symbol = box(node.symbolBox.x, y, node.symbolBox.width, node.symbolBox.height);
    for (const reference of node.ports) {
      const port = this.#ports.get(reference.id)!;
      if (port.region === undefined) this.#movePort(port, port.x, port.y + y - node.symbolBox.y);
    }
    this.#nodes[index] = Object.freeze({
      ...node, symbolBox: symbol, box: unionBoxes([symbol, regions])
    });
  }

  /** Moves one already-fitted region and its visual descendants as a rigid unit. */
  #translateRegion(
    id: RegionId,
    dx: number,
    dy: number,
    wires: SceneWire[],
    junctions: SceneJunction[],
    uses: SceneVariableUse[]
  ): void {
    if (dx === 0 && dy === 0) return;
    const regions = new Set(this.#regions.filter((region) =>
      this.#regionAncestors(region.id).includes(id)).map((region) => region.id));
    const nodes = new Set(this.#nodes.filter((node) => regions.has(node.region))
      .map((node) => node.id));
    const shift = (bounds: Box): Box =>
      box(bounds.x + dx, bounds.y + dy, bounds.width, bounds.height);

    for (let index = 0; index < this.#nodes.length; index += 1) {
      const node = this.#nodes[index]!;
      if (nodes.has(node.id)) {
        this.#nodes[index] = Object.freeze({
          ...node,
          box: shift(node.box),
          symbolBox: shift(node.symbolBox)
        });
      }
    }
    for (let index = 0; index < this.#regions.length; index += 1) {
      const region = this.#regions[index]!;
      if (!regions.has(region.id)) continue;
      this.#regions[index] = Object.freeze({ ...region, box: shift(region.box) });
      const anchor = this.#contentAnchors.get(region.id);
      if (anchor !== undefined) {
        this.#contentAnchors.set(
          region.id,
          Object.freeze({ x: anchor.x + dx, y: anchor.y + dy })
        );
      }
    }

    const ports = new Set<PortId>();
    for (const port of this.#ports.values()) {
      if (!nodes.has(port.owner) && (port.region === undefined || !regions.has(port.region))) {
        continue;
      }
      ports.add(port.id);
      this.#movePort(port, port.x + dx, port.y + dy);
    }
    for (let index = 0; index < wires.length; index += 1) {
      const wire = wires[index]!;
      if (!ports.has(wire.source) || !ports.has(wire.target)) continue;
      const route = Object.freeze(wire.route.map((point) =>
        Object.freeze({ x: point.x + dx, y: point.y + dy })));
      wires[index] = Object.freeze({
        ...wire,
        route,
        path: routedWirePath(route),
        midpoint: Object.freeze({ x: wire.midpoint.x + dx, y: wire.midpoint.y + dy }),
        typeLabel: wire.typeLabel === undefined ? undefined :
          Object.freeze({ ...wire.typeLabel, box: shift(wire.typeLabel.box) })
      });
    }
    for (let index = 0; index < junctions.length; index += 1) {
      const junction = junctions[index]!;
      if (ports.has(junction.source)) {
        junctions[index] = Object.freeze({
          ...junction,
          point: Object.freeze({ x: junction.point.x + dx, y: junction.point.y + dy })
        });
      }
    }
    for (let index = 0; index < uses.length; index += 1) {
      const use = uses[index]!;
      if (ports.has(use.source) && ports.has(use.target)) {
        uses[index] = Object.freeze({
          ...use,
          box: shift(use.box),
          anchor: Object.freeze({ x: use.anchor.x + dx, y: use.anchor.y + dy })
        });
      }
    }
  }

  #movePort(port: ScenePort, x: number, y: number): void {
    this.#ports.set(port.id, Object.freeze({
      ...port, x, y, labelBox: portLabelBox(port.label, port.placement, x, y)
    }));
  }

  /** Visual containment only: lexical legality was already decided in core. */
  #portRegion(id: PortId): RegionId {
    const port = this.#ports.get(id)!;
    return port.region ?? this.#graph.nodes.find((node) => node.id === port.owner)!.region;
  }

  #regionAncestors(id: RegionId): readonly RegionId[] {
    const result: RegionId[] = [];
    let current: RegionId | null = id;
    while (current !== null && !result.includes(current)) {
      result.push(current);
      current = this.#graph.regions.find((region) => region.id === current)?.parent ?? null;
    }
    return result;
  }

  #wireRegion(source: PortId, target: PortId): RegionId {
    const targetAncestors = new Set(this.#regionAncestors(this.#portRegion(target)));
    return this.#regionAncestors(this.#portRegion(source))
      .find((region) => targetAncestors.has(region)) ?? this.#viewRoot;
  }

  #layoutRegion(region: Region, x: number, y: number): RegionBlock {
    const collapsed = region.id !== this.#viewRoot && this.#collapsedRegions.has(region.id);
    const members = collapsed ? [] : byIdentity(nodesInRegion(this.#graph, region.id));
    const blocks = members.map((node) => this.#layoutNode(node));
    const placed = this.#placeInLayers(region.id, blocks);

    const owner = region.owner;
    const gutters =
      owner === null
        ? { left: [] as Port[], right: [] as Port[] }
        : this.#gutterPorts(owner, region.role);

    const contentWidth = placed.reduce(
      (widest, block) => Math.max(widest, block.x + block.width),
      0
    );
    const contentHeight = placed.reduce(
      (tallest, block) => Math.max(tallest, block.y + block.height),
      0
    );
    const gutterHeight =
      Math.max(gutters.left.length, gutters.right.length) * GUTTER_ROW_HEIGHT;

    const label = this.#regionLabel(region);
    const labelWidth =
      estimateTextWidth(
        label,
        FONT_SIZE_REGION_LABEL,
        false
      ) +
      2 * REGION_PADDING + (owner === null ? 0 : 2 * REGION_NAV_WIDTH);
    const leftGutterWidth = this.#gutterWidth(gutters.left);
    const rightGutterWidth = this.#gutterWidth(gutters.right);

    return {
      region,
      label,
      x,
      y,
      width: Math.max(
        labelWidth + leftGutterWidth + rightGutterWidth,
        leftGutterWidth + rightGutterWidth + 2 * REGION_PADDING + contentWidth
      ),
      height:
        REGION_HEADER_HEIGHT +
        2 * REGION_PADDING +
        Math.max(contentHeight, gutterHeight),
      nodes: placed,
      leftGutter: gutters.left,
      rightGutter: gutters.right,
      leftGutterWidth,
      rightGutterWidth
    };
  }

  #layoutNode(node: GraphNode): NodeBlock {
    const ports = byIdentity(portsOfNode(this.#graph, node.id));
    const owned = this.#ownedRegions(node.id);

    const topPorts: Port[] = [];
    const leftPorts: Port[] = [];
    const rightPorts: Port[] = [];

    for (const port of ports) {
      if (this.#gutterAssignment(node.kind, port.role) !== undefined) continue;
      if (node.kind === "If" && port.role === "condition") topPorts.push(port);
      else if (port.direction === "input") leftPorts.push(port);
      else rightPorts.push(port);
    }

    const regionBlocks: RegionBlock[] = [];
    let regionsHeight = 0;
    let regionsWidth = 0;

    for (const region of owned) {
      // A collapsed function is just its symbol. Do not reserve a body frame,
      // boundary sockets, labels, descendants, or internal routing.
      if (node.kind === "Lambda" && this.#collapsedRegions.has(region.id)) continue;
      const block = this.#layoutRegion(region, 0, 0);
      regionBlocks.push(block);
      regionsWidth = Math.max(regionsWidth, block.width);
      regionsHeight += block.height;
    }

    const branchesSideBySide = node.kind === "If" && regionBlocks.length > 1;
    if (branchesSideBySide) {
      regionsWidth = regionBlocks.reduce((total, block) => total + block.width, 0) +
        REGION_GAP * (regionBlocks.length - 1);
      regionsHeight = Math.max(...regionBlocks.map((block) => block.height));
    } else if (regionBlocks.length > 1) {
      regionsHeight += REGION_GAP * (regionBlocks.length - 1);
    }

    const presentation = this.#presentation(node);
    const headerWidth =
      Math.max(
        estimateTextWidth(presentation.primaryText, FONT_SIZE_TITLE, true),
        presentation.secondaryText === undefined
          ? 0
          : estimateTextWidth(presentation.secondaryText, FONT_SIZE_TITLE, false)
      ) + 4 * NODE_BODY_PADDING;

    const bandRows = Math.max(leftPorts.length, rightPorts.length);
    const bandWidth =
      portColumnWidth(leftPorts.map((port) => this.#displayPortLabel(port))) +
      portColumnWidth(rightPorts.map((port) => this.#displayPortLabel(port))) +
      3 * NODE_BODY_PADDING;
    const topPortWidth = portColumnWidth(
      topPorts.map((port) => this.#displayPortLabel(port))
    ) + 2 * NODE_BODY_PADDING;

    const symbolWidth = Math.max(
      NODE_MIN_WIDTH,
      headerWidth,
      bandWidth,
      topPortWidth
    );
    const width = Math.max(symbolWidth, regionsWidth + 2 * NODE_BODY_PADDING);
    const symbolX = Math.round((width - symbolWidth) / 2);

    const bandHeight = bandRows * PORT_ROW_HEIGHT;
    // Readable captions have independent rows below the node title band.
    const labelHeight = presentation.secondaryText === undefined
      ? NODE_HEADER_HEIGHT
      : NODE_HEADER_HEIGHT + GRID;
    const collapsedBody = node.kind === "Lambda" && owned.length > 0 && regionBlocks.length === 0;
    const symbolHeight = Math.max(
      labelHeight,
      NODE_HEADER_HEIGHT + bandHeight + 2 * NODE_BAND_TOP
    ) + (collapsedBody ? 4 * GRID + NODE_BODY_PADDING : 0);
    let cursor = symbolHeight;
    const positioned: RegionBlock[] = [];

    if (regionBlocks.length > 0) {
      cursor += NODE_BODY_PADDING;
      if (branchesSideBySide) {
        let regionX = Math.round((width - regionsWidth) / 2);
        for (const block of regionBlocks) {
          positioned.push({ ...block, x: regionX, y: cursor });
          regionX += block.width + REGION_GAP;
        }
        cursor += regionsHeight;
      } else {
        for (const block of regionBlocks) {
          positioned.push({
            ...block,
            x: Math.round((width - block.width) / 2),
            y: cursor
          });
          cursor += block.height + REGION_GAP;
        }
        cursor -= REGION_GAP;
      }
    }

    return {
      node,
      width,
      height: cursor + NODE_BODY_PADDING,
      symbolX,
      symbolWidth,
      symbolHeight,
      x: 0,
      y: 0,
      topPorts,
      leftPorts,
      rightPorts,
      regions: positioned
    };
  }

  /**
   * Assigns each node in a region to a dataflow layer and stacks the layers
   * left to right. A node's layer is one past the deepest producer feeding it
   * from the *same* region; edges crossing a region frame do not constrain the
   * layer, because the node on the far side is laid out inside its own frame.
   */
  #placeInLayers<T extends { readonly node: GraphNode; readonly width: number; readonly height: number }>(
    regionId: RegionId,
    blocks: readonly T[]
  ): readonly (T & Point)[] {
    const members = new Map(blocks.map((block) => [block.node.id, block]));
    const producers = new Map<NodeId, readonly NodeId[]>();

    for (const block of blocks) {
      const feeding = new Set<NodeId>();

      for (const port of portsOfNode(this.#graph, block.node.id)) {
        if (port.direction !== "input") continue;

        for (const edge of this.#graph.edges) {
          if (edge.target !== port.id) continue;
          const owner = this.#portOwner.get(edge.source);
          if (owner === undefined || owner === block.node.id) continue;
          const producer = members.get(owner);
          if (producer !== undefined && producer.node.region === regionId) {
            feeding.add(owner);
          }
        }
      }

      producers.set(block.node.id, [...feeding]);
    }

    const layers = new Map<NodeId, number>();
    const visiting = new Set<NodeId>();

    const layerOf = (id: NodeId): number => {
      const known = layers.get(id);
      if (known !== undefined) return known;
      // A dataflow cycle inside one region is not well-formed, but the layout
      // must terminate on any input it is handed rather than trust that.
      if (visiting.has(id)) return 0;

      visiting.add(id);
      let layer = 0;
      for (const producer of producers.get(id) ?? []) {
        layer = Math.max(layer, layerOf(producer) + 1);
      }
      visiting.delete(id);
      layers.set(id, layer);
      return layer;
    };

    const columns = new Map<number, T[]>();
    for (const block of blocks) {
      const layer = layerOf(block.node.id);
      const column = columns.get(layer);
      if (column === undefined) columns.set(layer, [block]);
      else column.push(block);
    }

    const indices = [...columns.keys()].sort((a, b) => a - b);
    const heights = new Map<number, number>();

    for (const index of indices) {
      const column = columns.get(index) ?? [];
      const height =
        column.reduce((total, block) => total + block.height, 0) +
        ROW_GAP * Math.max(0, column.length - 1);
      heights.set(index, height);
    }

    const tallest = Math.max(0, ...heights.values());
    const placed: (T & Point)[] = [];
    let x = 0;

    for (const index of indices) {
      const column = columns.get(index) ?? [];
      let y = Math.round((tallest - (heights.get(index) ?? 0)) / 2);
      let widest = 0;

      for (const block of column) {
        placed.push({ ...block, x, y });
        y += block.height + ROW_GAP;
        widest = Math.max(widest, block.width);
      }

      x += widest + LAYER_GAP;
    }

    return placed;
  }

  #ownedRegions(node: NodeId): readonly Region[] {
    return this.#graph.regions
      .filter((region) => region.owner === node)
      .sort((left, right) => {
        const rank = regionRoleRank(left.role) - regionRoleRank(right.role);
        return rank !== 0 ? rank : compareIdentity(left.id, right.id);
      });
  }

  #gutterAssignment(
    nodeKind: string,
    role: NodePortRole
  ): GutterAssignment | undefined {
    return REGION_GUTTER_PORTS.get(`${nodeKind}:${role}`);
  }

  #gutterPorts(
    owner: NodeId,
    regionRole: string
  ): { left: Port[]; right: Port[] } {
    const node = this.#graph.nodes.find((candidate) => candidate.id === owner);
    if (node === undefined) return { left: [], right: [] };

    const left: Port[] = [];
    const right: Port[] = [];

    for (const port of byIdentity(portsOfNode(this.#graph, owner))) {
      const assignment = this.#gutterAssignment(node.kind, port.role);
      if (assignment === undefined || assignment.regionRole !== regionRole) {
        continue;
      }
      if (assignment.side === "left") left.push(port);
      else right.push(port);
    }

    const focused = this.#graph.regions.find((region) => region.id === this.#viewRoot);
    if (focused?.owner === owner && focused.role === regionRole) {
      for (const capture of this.#captures.get(this.#viewRoot) ?? []) {
        const source = this.#graph.ports.find((port) => port.id === capture.source);
        if (source !== undefined && !left.some((port) => port.id === source.id)) left.push(source);
      }
    }

    return { left, right };
  }

  // --- emission ----------------------------------------------------------

  #emitRegion(
    block: RegionBlock,
    x: number,
    y: number,
    depth: number,
    offsetX: number,
    offsetY: number
  ): void {
    this.#regions.push(
      Object.freeze({
        id: block.region.id,
        role: block.region.role,
        label: block.label,
        depth,
        owner: block.region.owner,
        collapsed: block.region.id !== this.#viewRoot && this.#collapsedRegions.has(block.region.id),
        box: box(x + offsetX, y + offsetY, block.width, block.height),
        gutters: Object.freeze({
          left: block.leftGutterWidth,
          right: block.rightGutterWidth
        })
      })
    );

    const gutterTop = y + offsetY + REGION_HEADER_HEIGHT + REGION_PADDING;

    block.leftGutter.forEach((port, index) => {
      this.#emitPort(
        port,
        "region-left",
        block.region.id,
        x + offsetX + block.leftGutterWidth / 2,
        gutterTop + index * GUTTER_ROW_HEIGHT + GUTTER_ROW_HEIGHT / 4
      );
    });

    block.rightGutter.forEach((port, index) => {
      this.#emitPort(
        port,
        "region-right",
        block.region.id,
        x + offsetX + block.width - block.rightGutterWidth / 2,
        gutterTop + index * GUTTER_ROW_HEIGHT + GUTTER_ROW_HEIGHT / 4
      );
    });

    const contentX = x + block.leftGutterWidth + REGION_PADDING;
    const contentY = y + REGION_HEADER_HEIGHT + REGION_PADDING;
    this.#contentAnchors.set(block.region.id,
      Object.freeze({ x: contentX + offsetX, y: contentY + offsetY }));

    for (const child of block.nodes) {
      this.#emitNode(
        child,
        contentX + child.x,
        contentY + child.y,
        depth,
        offsetX,
        offsetY
      );
    }
  }

  /**
   * Places one node and everything nested inside it.
   *
   * A node's own displacement is added to whatever displacement it inherited,
   * and the sum is passed down, so moving a Lambda carries its body region and
   * every node in it along instead of tearing the picture apart.
   */
  #emitNode(
    block: NodeBlock,
    x: number,
    y: number,
    depth: number,
    inheritedX: number,
    inheritedY: number
  ): void {
    const own = this.#offsets.get(block.node.id);
    const offsetX = inheritedX + (own?.dx ?? 0);
    const offsetY = inheritedY + (own?.dy ?? 0);
    const bandRows = Math.max(block.leftPorts.length, block.rightPorts.length);
    const bandHeight = bandRows * PORT_ROW_HEIGHT;
    const bodyTop =
      y + offsetY + NODE_HEADER_HEIGHT + NODE_BAND_TOP;

    block.topPorts.forEach((port) => {
      this.#emitPort(
        port,
        "node-top",
        undefined,
        x + offsetX + block.symbolX + block.symbolWidth / 2,
        y + offsetY
      );
    });

    block.leftPorts.forEach((port, index) => {
      this.#emitPort(
        port,
        "node-left",
        undefined,
        x + offsetX + block.symbolX,
        bodyTop + index * PORT_ROW_HEIGHT + PORT_ROW_HEIGHT / 2
      );
    });

    block.rightPorts.forEach((port, index) => {
      this.#emitPort(
        port,
        block.node.kind === "If" && port.role === "result"
          ? "node-right-external"
          : "node-right",
        undefined,
        x + offsetX + block.symbolX + block.symbolWidth,
        block.node.kind === "If" && port.role === "result"
          ? y + offsetY + block.symbolHeight / 2
          : bodyTop + index * PORT_ROW_HEIGHT + PORT_ROW_HEIGHT / 2
      );
    });

    for (const region of block.regions) {
      this.#emitRegion(
        region,
        x + region.x,
        y + region.y,
        depth + 1,
        offsetX,
        offsetY
      );
    }

    const presentation = this.#presentation(block.node);
    const ports: ScenePort[] = [];

    for (const port of byIdentity(portsOfNode(this.#graph, block.node.id))) {
      const placed = this.#ports.get(port.id);
      if (placed !== undefined) ports.push(placed);
    }
    const ownedRegions = this.#ownedRegions(block.node.id);
    const collapsedBody = block.node.kind === "Lambda"
      ? ownedRegions.find((region) => this.#collapsedRegions.has(region.id))?.id
      : undefined;

    this.#nodes.push(
      Object.freeze({
        id: block.node.id,
        nodeKind: block.node.kind,
        region: block.node.region,
        shape: presentation.shape,
        primaryText: presentation.primaryText,
        secondaryText: presentation.secondaryText,
        box: box(x + offsetX, y + offsetY, block.width, block.height),
        symbolBox: box(
          x + offsetX + block.symbolX,
          y + offsetY,
          block.symbolWidth,
          block.symbolHeight
        ),
        ports: Object.freeze(ports),
        ownedRegions: Object.freeze(
          ownedRegions.map((region) => region.id)
        ),
        ...(collapsedBody === undefined ? {} : { collapsedBody })
      })
    );
  }

  #emitPort(
    port: Port,
    placement: PortPlacement,
    region: RegionId | undefined,
    x: number,
    y: number
  ): void {
    const type = this.#portTypes.get(port.id);
    const socket = socketAppearance(type);
    const typeText = displayType(type);
    const open = port.direction === "input" && !this.#connectedInputs.has(port.id);
    const label = this.#displayPortLabel(port, typeText, open);

    this.#ports.set(
      port.id,
      Object.freeze({
        id: port.id,
        owner: port.owner,
        direction: port.direction,
        role: port.role,
        label,
        labelBox: portLabelBox(label, placement, x, y),
        placement,
        region,
        x,
        y,
        typeClass: socket.typeClass,
        typeText,
        socket,
        open,
        capture: this.#captures.get(this.#viewRoot)?.some((capture) => capture.source === port.id) ?? false
      })
    );
  }

  #buildWires(container: RegionId): { wires: SceneWire[]; junctions: SceneJunction[] } {
    const wires: SceneWire[] = [];
    const junctions: SceneJunction[] = [];
    const counts = new Map<PortId, number>();

    for (const edge of this.#graph.edges) {
      counts.set(edge.source, (counts.get(edge.source) ?? 0) + 1);
    }

    const branchPoints = new Map<PortId, Point>();
    for (const sourceId of [...counts.keys()].sort(compareIdentity)) {
      const count = counts.get(sourceId) ?? 0;
      if (count < 2) continue;
      const source = this.#ports.get(sourceId);
      if (source === undefined) continue;
      const point = Object.freeze({ x: source.x + FAN_OUT_TRUNK, y: source.y });
      branchPoints.set(sourceId, point);
      junctions.push(
        Object.freeze({ source: sourceId, point, typeClass: source.typeClass })
      );
    }

    for (const edge of byIdentity(this.#graph.edges)) {
      const source = this.#ports.get(edge.source);
      const target = this.#ports.get(edge.target);
      if (source === undefined || target === undefined) continue;
      if (this.#wireRegion(edge.source, edge.target) !== container) continue;

      const from: Point = { x: source.x, y: source.y };
      const to: Point = { x: target.x, y: target.y };
      const type = this.#portTypes.get(edge.source);
      // Whether a wire closes a recursion is a question about binding, so the
      // core answers it. The projection only decides how to draw the answer.
      const feedback = this.#recursive.has(identityText(edge.id));
      const branch = branchPoints.get(edge.source);
      const routeStart = branch ?? from;
      const obstacles = this.#wireObstacles(from, to, edge.source, edge.target, container);
      const tail = routeOrthogonally(
        routeStart,
        to,
        obstacles,
        feedback,
        target.placement
      );
      // Keep the junction as an explicit vertex even when the shared trunk and
      // first branch segment are collinear. Geometry tests and renderers can
      // then identify the branch without inventing a semantic element.
      const route = branch === undefined
        ? tail
        : [Object.freeze(from), branch, ...tail.slice(1)];
      const appearance = wireAppearance(type);
      const typeText = displayType(type);
      const midpoint = routedWireMidpoint(route);

      wires.push(
        Object.freeze({
          id: edge.id,
          wireKind: edge.kind === "BinderUse" ? ("binder" as const) : ("value" as const),
          binderName:
            edge.kind === "BinderUse"
              ? this.#binderNames.get(identityText(edge.binder))
              : undefined,
          source: edge.source,
          target: edge.target,
          path: routedWirePath(route),
          route: Object.freeze(route),
          midpoint,
          appearance,
          typeText,
          typeLabel:
            appearance.typeClass === "function"
              ? wireTypeLabel(
                  typeText,
                  route,
                  this.#wireLabelObstacles(container),
                  midpoint
                )
              : undefined,
          backEdge: isBackEdge(from, to),
          feedback,
          captureRegions: Object.freeze(byIdentity(this.#graph.regions)
            .filter((region) => region.role === "lambda-body" &&
              this.#captures.get(region.id)?.some((capture) => capture.edges.includes(edge.id)))
            .map((region) => region.id))
        })
      );
    }

    return { wires, junctions: junctions.filter((junction) =>
      wires.some((wire) => wire.source === junction.source)) };
  }

  #buildVariableUses(wires: readonly SceneWire[]): SceneVariableUse[] {
    const obstacles = [
      ...this.#nodes.map((node) => expandBox(node.symbolBox, WIRE_CLEARANCE / 2)),
      ...this.#regions.map((region) => box(region.box.x, region.box.y,
        region.box.width, REGION_HEADER_HEIGHT)),
      ...[...this.#ports.values()].map((port) => port.labelBox)
    ];
    return wires.flatMap((wire) => {
      if (wire.wireKind !== "binder" || wire.binderName === undefined) return [];

      const width = Math.max(
        5 * GRID,
        estimateTextWidth(wire.binderName, FONT_SIZE_LITERAL, true) +
          2 * NODE_BODY_PADDING
      );
      const height = 4 * GRID;
      // A variable occurrence must not appear to consume an unrelated capture.
      // Keep its glyph off other value routes; shared-source fan-out is one
      // value and may retain its existing overlapping lead.
      const otherRoutes = wires.filter((other) => other.source !== wire.source)
        .flatMap((other) => other.route.slice(1).map((to, index) => {
          const from = other.route[index]!;
          return expandBox(box(Math.min(from.x, to.x), Math.min(from.y, to.y),
            Math.abs(to.x - from.x), Math.abs(to.y - from.y)), GRID / 2);
        }));

      const use = Object.freeze({
          edge: wire.id,
          source: wire.source,
          target: wire.target,
          name: wire.binderName,
          typeText: wire.typeText,
          typeClass: wire.appearance.typeClass,
          box: variableUseBox(wire.route, width, height, [...obstacles, ...otherRoutes]),
          anchor: routedWireMidpoint(wire.route)
        });
      obstacles.push(expandBox(use.box, GRID / 2));
      return [use];
    });
  }

  #presentation(node: GraphNode): ReturnType<typeof nodePresentation> {
    const presentation = nodePresentation(node, this.#nodeTypeText(node));
    if (node.kind !== "Lambda") return presentation;
    const binding = this.#graph.nodes.find((owner) => owner.kind === "LetRec" && owner.definition === node.id);
    const output = portsOfNode(this.#graph, node.id).find((port) => port.role === "out");
    const body = this.#ownedRegions(node.id)[0];
    const captures = body === undefined ? [] : this.#captures.get(body.id) ?? [];
    const captureText = captures.length === 0 ? "" : ` · captures ${captures.slice(0, 2).map((capture) => capture.displayName).join(", ")}${captures.length > 2 ? ` +${captures.length - 2}` : ""}`;
    return { ...presentation,
      primaryText: binding?.kind === "LetRec" ? `${binding.recursive.displayName} · ${presentation.primaryText}` : presentation.primaryText,
      secondaryText: `${displayType(output === undefined ? undefined : this.#portTypes.get(output.id))}${captureText}` };
  }

  #nodeTypeText(node: GraphNode): string {
    const ports = portsOfNode(this.#graph, node.id);
    const preferred =
      node.kind === "Lambda"
        ? ports.find((port) => port.id === node.parameter.parameterPort)
        : node.kind === "LetRec"
          ? ports.find((port) => port.id === node.recursive.valuePort)
          : ports.find((port) => port.direction === "output");
    const type = preferred === undefined ? undefined : this.#portTypes.get(preferred.id);
    return displayType(type);
  }

  #regionLabel(region: Region): string {
    if (region.owner === null) return regionRoleLabel(region.role);
    return regionRoleLabel(region.role);
  }

  #displayPortLabel(
    port: Port,
    knownTypeText?: string,
    knownOpen?: boolean
  ): string {
    const type = this.#portTypes.get(port.id);
    const typeText = knownTypeText ?? displayType(type);
    const open = knownOpen ??
      (port.direction === "input" && !this.#connectedInputs.has(port.id));
    const owner = this.#graph.nodes.find((node) => node.id === port.owner);

    const capture = this.#captures.get(this.#viewRoot)?.find((entry) => entry.source === port.id);
    if (capture !== undefined) return `capture · ${capture.displayName} : ${typeText}`;

    if (owner?.kind === "Lambda" && port.role === "parameter") {
      return `${owner.parameter.displayName} : ${typeText}`;
    }
    if (owner?.kind === "LetRec" && port.role === "recursive") {
      return `${owner.recursive.displayName} : ${typeText}`;
    }

    return `${portRoleLabel(port.role)}${open ? " · ?" : ""} : ${typeText}`;
  }

  #gutterWidth(ports: readonly Port[]): number {
    const labelWidth = Math.max(
      REGION_GUTTER,
      ...ports.map(
        (port) =>
          estimateTextWidth(
            this.#displayPortLabel(port),
            FONT_SIZE_PORT_LABEL,
            true
          ) +
          2 * REGION_PADDING
      )
    );
    const captures = this.#captures.get(this.#viewRoot) ?? [];
    if (!ports.some((port) => captures.some((capture) => capture.source === port.id))) return labelWidth;
    const glyphWidth = Math.max(8 * GRID, ...ports.map((port) => {
      const owner = this.#graph.nodes.find((node) => node.id === port.owner);
      const name = captures.find((capture) => capture.source === port.id)?.displayName ??
        (owner?.kind === "Lambda" ? owner.parameter.displayName : "");
      return Math.max(estimateTextWidth(name, FONT_SIZE_LITERAL, true),
        estimateTextWidth(displayType(this.#portTypes.get(port.id)), FONT_SIZE_WIRE_LABEL, true)) +
        2 * NODE_BODY_PADDING;
    }));
    // With the sources aligned just inside the boundary, reserve enough lead
    // before the route's midpoint turn for a label half-width and one glyph.
    const textWidth = labelWidth - 2 * REGION_PADDING;
    return Math.max(labelWidth, Math.ceil((1.5 * textWidth + 2 * glyphWidth + 4 * GRID) / GRID) * GRID);
  }

  #wireObstacles(
    source: Point,
    target: Point,
    sourcePort: PortId,
    targetPort: PortId,
    container: RegionId
  ): readonly Box[] {
    const obstacles: Box[] = [];

    for (const node of this.#nodes) {
      if (!this.#regionAncestors(node.region).includes(container)) continue;
      if (containsPoint(node.box, source) || containsPoint(node.box, target)) {
        // Captures may enter a nested body, but may not cross its preparation
        // header. The owning frame is permeable here; its symbol is not.
        if (!containsPoint(node.symbolBox, source) && !containsPoint(node.symbolBox, target)) {
          obstacles.push(expandBox(node.symbolBox, WIRE_CLEARANCE));
        }
        continue;
      }
      obstacles.push(expandBox(node.box, WIRE_CLEARANCE));
    }

    for (const region of this.#regions) {
      if (!this.#regionAncestors(region.id).includes(container)) continue;
      if (containsPoint(region.box, source) || containsPoint(region.box, target)) continue;
      obstacles.push(
        expandBox(
          box(region.box.x, region.box.y, region.box.width, REGION_HEADER_HEIGHT),
          WIRE_CLEARANCE / 2
        )
      );
    }

    for (const port of this.#ports.values()) {
      if (!this.#regionAncestors(this.#portRegion(port.id)).includes(container)) continue;
      if (port.id === sourcePort || port.id === targetPort) continue;
      obstacles.push(expandBox(port.labelBox, WIRE_CLEARANCE / 2));
    }

    return obstacles;
  }

  #wireLabelObstacles(container: RegionId): readonly Box[] {
    return [
      ...this.#nodes.filter((node) => this.#regionAncestors(node.region).includes(container))
        .map((node) => expandBox(node.box, WIRE_CLEARANCE / 4)),
      ...this.#regions.filter((region) => this.#regionAncestors(region.id).includes(container)).map((region) =>
        expandBox(
          box(region.box.x, region.box.y, region.box.width, REGION_HEADER_HEIGHT),
          WIRE_CLEARANCE / 2
        )
      ),
      ...[...this.#ports.values()].flatMap((port) => [
        expandBox(portPaintBox(port), WIRE_CLEARANCE / 2),
        expandBox(port.labelBox, WIRE_CLEARANCE / 2)
      ])
    ];
  }

}

function box(x: number, y: number, width: number, height: number): Box {
  return Object.freeze({ x, y, width, height });
}

function unionBoxes(boxes: readonly Box[]): Box {
  const x = Math.min(...boxes.map((entry) => entry.x));
  const y = Math.min(...boxes.map((entry) => entry.y));
  return box(x, y,
    Math.max(...boxes.map((entry) => entry.x + entry.width)) - x,
    Math.max(...boxes.map((entry) => entry.y + entry.height)) - y);
}

function portPaintBox(port: ScenePort): Box {
  return box(port.x - 16, port.y - 8, 36, 16);
}

/**
 * Formats the core's type result for a diagram.
 *
 * Partial typing names node-local variables with source identities so
 * diagnostics remain unambiguous. The canvas keeps the exact type structure
 * and only shortens that presentation name (`node:...A` -> `A`).
 */
function displayType(type: OpenInputExpectedType | undefined): string {
  if (type === undefined) return "?";
  return prettyOpenInputExpectedType(type).replace(
    /\?[A-Za-z0-9_.:-]+\.([A-Z])\b/g,
    "?$1"
  );
}

/** Places an inline variable glyph on the last route segment wide enough. */
function variableUseBox(
  route: readonly Point[],
  width: number,
  height: number,
  obstacles: readonly Box[]
): Box {
  for (let index = route.length - 1; index > 0; index -= 1) {
    const from = route[index - 1];
    const to = route[index];
    if (from === undefined || to === undefined || from.y !== to.y) continue;
    if (Math.abs(to.x - from.x) < width + 2 * GRID) {
      const candidate = box(
        Math.round((from.x + to.x - width) / 2),
        Math.round(from.y - height / 2),
        width,
        height
      );
      if (!obstacles.some((obstacle) => boxesOverlap(candidate, obstacle))) {
        return candidate;
      }
      continue;
    }

    const left = Math.min(from.x, to.x);
    const right = Math.max(from.x, to.x) - width;
    const candidates = [(left + right) / 2, left, right,
      ...obstacles.flatMap((obstacle) => [obstacle.x - width - GRID,
        obstacle.x + obstacle.width + GRID])];
    for (const x of candidates) {
      if (x < left || x > right) continue;
      const candidate = box(Math.round(x), Math.round(from.y - height / 2), width, height);
      if (!obstacles.some((obstacle) => boxesOverlap(candidate, obstacle))) return candidate;
    }
  }

  // A close pair of inputs may leave no horizontal annotation lane. A data
  // glyph can also sit on a vertical segment without covering boundary labels.
  for (let index = route.length - 1; index > 0; index -= 1) {
    const from = route[index - 1]!;
    const to = route[index]!;
    if (from.x !== to.x || from.y === to.y) continue;
    const top = Math.min(from.y, to.y) + GRID;
    const bottom = Math.max(from.y, to.y) - GRID;
    const candidates = [(top + bottom) / 2,
      ...obstacles.flatMap((obstacle) => [obstacle.y + obstacle.height + height / 2,
        obstacle.y - height / 2])];
    for (const y of candidates) {
      if (y < top || y > bottom) continue;
      const candidate = box(Math.round(from.x - width / 2), Math.round(y - height / 2), width, height);
      if (!obstacles.some((obstacle) => boxesOverlap(candidate, obstacle))) return candidate;
    }
  }
  const midpoint = routedWireMidpoint(route);
  const initial = box(
    Math.round(midpoint.x - width / 2),
    Math.round(midpoint.y - height / 2),
    width,
    height
  );
  if (!obstacles.some((obstacle) => boxesOverlap(initial, obstacle))) return initial;

  // No route segment had enough free inline space. Search outward in a fixed
  // grid and keep a clear leader back to the owning BinderUse route instead
  // of silently placing the glyph over another expression.
  for (let ring = 1; ring <= 64; ring += 1) {
    const distance = ring * (height + GRID);
    for (const [dx, dy] of [[0, -distance], [0, distance], [-distance, 0], [distance, 0]] as const) {
      const candidate = box(initial.x + dx, initial.y + dy, width, height);
      const center = {
        x: candidate.x + candidate.width / 2,
        y: candidate.y + candidate.height / 2
      };
      if (!obstacles.some((obstacle) => boxesOverlap(candidate, obstacle)) &&
          routeIsClear([midpoint, center], obstacles)) {
        return candidate;
      }
    }
  }

  // This deterministic search is intentionally generous. Keeping the
  // presentation fallback explicit lets geometry tests catch any future case
  // whose routing channels cannot accommodate a variable glyph.
  return initial;
}

function portLabelBox(
  label: string,
  placement: PortPlacement,
  x: number,
  y: number
): Box {
  if (label.length === 0) return box(x, y, 0, 0);
  const width = estimateTextWidth(label, FONT_SIZE_PORT_LABEL, true);
  const height = FONT_SIZE_PORT_LABEL + 2;

  if (placement === "region-left" || placement === "region-right") {
    return box(
      x - width / 2,
      y + GUTTER_LABEL_OFFSET - FONT_SIZE_PORT_LABEL,
      width,
      height
    );
  }

  if (placement === "node-top") {
    return box(x - width / 2, y + 11, width, height);
  }

  if (placement === "node-right-external") {
    return box(x + 10, y - 10 - FONT_SIZE_PORT_LABEL, width, height);
  }

  return placement === "node-left"
    ? box(x + 10, y + 3 - FONT_SIZE_PORT_LABEL, width, height)
    : box(x - 10 - width, y + 3 - FONT_SIZE_PORT_LABEL, width, height);
}

function containsPoint(bounds: Box, point: Point): boolean {
  return (
    point.x >= bounds.x &&
    point.x <= bounds.x + bounds.width &&
    point.y >= bounds.y &&
    point.y <= bounds.y + bounds.height
  );
}

function expandBox(bounds: Box, amount: number): Box {
  if (bounds.width <= 0 || bounds.height <= 0) return bounds;
  return box(
    bounds.x - amount,
    bounds.y - amount,
    bounds.width + 2 * amount,
    bounds.height + 2 * amount
  );
}

function boxesOverlap(left: Box, right: Box): boolean {
  if (
    left.width <= 0 ||
    left.height <= 0 ||
    right.width <= 0 ||
    right.height <= 0
  ) return false;
  return (
    left.x < right.x + right.width &&
    right.x < left.x + left.width &&
    left.y < right.y + right.height &&
    right.y < left.y + left.height
  );
}

function segmentHitsBox(from: Point, to: Point, obstacle: Box): boolean {
  if (from.x === to.x) {
    return (
      from.x > obstacle.x &&
      from.x < obstacle.x + obstacle.width &&
      Math.max(from.y, to.y) > obstacle.y &&
      Math.min(from.y, to.y) < obstacle.y + obstacle.height
    );
  }

  if (from.y === to.y) {
    return (
      from.y > obstacle.y &&
      from.y < obstacle.y + obstacle.height &&
      Math.max(from.x, to.x) > obstacle.x &&
      Math.min(from.x, to.x) < obstacle.x + obstacle.width
    );
  }

  return true;
}

function routeIsClear(route: readonly Point[], obstacles: readonly Box[]): boolean {
  for (let index = 1; index < route.length; index += 1) {
    const from = route[index - 1]!;
    const to = route[index]!;
    if (obstacles.some((obstacle) => segmentHitsBox(from, to, obstacle))) {
      return false;
    }
  }
  return true;
}

function routeLength(route: readonly Point[]): number {
  return route.slice(1).reduce((total, point, index) => {
    const previous = route[index]!;
    return total + Math.abs(point.x - previous.x) + Math.abs(point.y - previous.y);
  }, 0);
}

/**
 * Route through the channels between boxes. The source lead keeps turns away
 * from its socket; the target lead follows the port placement, so top-entry
 * conditions approach downward while side inputs preserve rightward flow.
 * A detour lane is chosen from obstacle boundaries, keeping the result stable
 * and directly testable.
 */
function routeOrthogonally(
  source: Point,
  target: Point,
  obstacles: readonly Box[],
  feedback: boolean,
  targetPlacement: PortPlacement
): Point[] {
  const sourceLead = Object.freeze({ x: source.x + WIRE_LEAD, y: source.y });
  const targetLead = targetPlacement === "node-top"
    ? Object.freeze({ x: target.x, y: target.y - WIRE_LEAD })
    : Object.freeze({ x: target.x - WIRE_LEAD, y: target.y });
  const middleX = Math.round((sourceLead.x + targetLead.x) / 2);
  const direct = simplifyRoute(targetPlacement === "node-top"
    ? [
        source,
        sourceLead,
        { x: middleX, y: source.y },
        { x: middleX, y: targetLead.y },
        targetLead,
        target
      ]
    : [
        source,
        sourceLead,
        { x: middleX, y: source.y },
        { x: middleX, y: target.y },
        targetLead,
        target
      ]);

  if (!feedback && routeIsClear(direct, obstacles)) return direct;

  const top = Math.min(source.y, target.y, ...obstacles.map((entry) => entry.y));
  const bottom = Math.max(
    source.y,
    target.y,
    ...obstacles.map((entry) => entry.y + entry.height)
  );
  const lanes = new Set<number>([
    top - WIRE_CLEARANCE,
    bottom + WIRE_CLEARANCE,
    Math.min(source.y, target.y) - 2 * WIRE_CLEARANCE,
    Math.max(source.y, target.y) + 2 * WIRE_CLEARANCE
  ]);

  for (const obstacle of obstacles) {
    lanes.add(obstacle.y);
    lanes.add(obstacle.y + obstacle.height);
  }

  const candidates = [...lanes]
    .map((laneY) =>
      simplifyRoute([
        source,
        sourceLead,
        { x: sourceLead.x, y: laneY },
        { x: targetLead.x, y: laneY },
        targetLead,
        target
      ])
    )
    .filter((route) => routeIsClear(route, obstacles))
    .sort((left, right) => {
      if (feedback) {
        const leftAbove = Math.max(...left.map((point) => point.y)) <=
          Math.max(source.y, target.y);
        const rightAbove = Math.max(...right.map((point) => point.y)) <=
          Math.max(source.y, target.y);
        if (leftAbove !== rightAbove) return leftAbove ? -1 : 1;
      }
      return routeLength(left) - routeLength(right);
    });

  return candidates[0] ?? simplifyRoute([
    source,
    sourceLead,
    { x: sourceLead.x, y: top - 2 * WIRE_CLEARANCE },
    { x: targetLead.x, y: top - 2 * WIRE_CLEARANCE },
    targetLead,
    target
  ]);
}

function simplifyRoute(points: readonly Point[]): Point[] {
  const route: Point[] = [];

  for (const point of points) {
    const last = route[route.length - 1];
    if (last !== undefined && last.x === point.x && last.y === point.y) continue;
    route.push(Object.freeze({ x: point.x, y: point.y }));

    while (route.length >= 3) {
      const a = route[route.length - 3]!;
      const b = route[route.length - 2]!;
      const c = route[route.length - 1]!;
      const collinear =
        (a.x === b.x && b.x === c.x) || (a.y === b.y && b.y === c.y);
      if (!collinear) break;
      route.splice(route.length - 2, 1);
    }
  }

  return route;
}

function wireTypeLabel(
  typeText: string,
  route: readonly Point[],
  obstacles: readonly Box[],
  midpoint: Point
): { text: string; box: Box } {
  const text = typeText.replace(/\s*->\s*/g, "→");
  const width = estimateTextWidth(text, FONT_SIZE_WIRE_LABEL, true) + 8;
  const height = 18;
  const horizontal = route
    .slice(1)
    .flatMap((to, index) => {
      const from = route[index]!;
      return from.y === to.y
        ? [{ from, to, length: Math.abs(to.x - from.x) }]
        : [];
    })
    .sort((left, right) => right.length - left.length);

  for (const segment of horizontal) {
    for (const ratio of [0.35, 0.65, 0.5]) {
      const centerX = segment.from.x + (segment.to.x - segment.from.x) * ratio;
      for (const y of [segment.from.y - height - 4, segment.from.y + 4]) {
        const candidate = box(Math.round(centerX - width / 2), y, width, height);
        const masksMarker =
          midpoint.x >= candidate.x - 8 &&
          midpoint.x <= candidate.x + candidate.width + 8 &&
          midpoint.y >= candidate.y - 8 &&
          midpoint.y <= candidate.y + candidate.height + 8;
        if (
          !masksMarker &&
          !obstacles.some((obstacle) => boxesOverlap(candidate, obstacle))
        ) {
          return Object.freeze({ text, box: candidate });
        }
      }
    }
  }

  const vertical = route.slice(1).flatMap((to, index) => {
    const from = route[index]!;
    return from.x === to.x
      ? [{ from, to, length: Math.abs(to.y - from.y) }]
      : [];
  }).sort((left, right) => right.length - left.length);

  for (const segment of vertical) {
    for (const ratio of [0.35, 0.65, 0.5]) {
      const centerY = segment.from.y + (segment.to.y - segment.from.y) * ratio;
      const candidate = box(
        Math.round(segment.from.x - width / 2),
        Math.round(centerY - height / 2),
        width,
        height
      );
      if (!obstacles.some((obstacle) => boxesOverlap(candidate, obstacle))) {
        return Object.freeze({ text, box: candidate });
      }
    }
  }

  const fallback = horizontal[0];
  const centerX = fallback === undefined
    ? midpoint.x
    : Math.round((fallback.from.x + fallback.to.x) / 2);
  return Object.freeze({
    text,
    box: box(centerX - width / 2, midpoint.y - height - 4, width, height)
  });
}

function portColumnWidth(labels: readonly string[]): number {
  return labels.reduce(
    (widest, label) =>
      Math.max(widest, estimateTextWidth(label, FONT_SIZE_PORT_LABEL, false) + 12),
    0
  );
}

/**
 * Reads the port types the core type checker assigns.
 *
 * A graph that does not type-check still projects: the checker's partial
 * results are used, and any port it could not resolve renders as `unknown`.
 * The projection never infers a type of its own.
 */
function collectPortTypes(
  graph: Graph
): ReadonlyMap<PortId, OpenInputExpectedType> {
  const types = new Map<PortId, OpenInputExpectedType>();
  const result = typeGraph(graph);

  const closed = result.ok
    ? result.typedGraph.portTypes
    : result.partialPortTypes;
  const holes = result.ok
    ? result.typedGraph.openInputs
    : result.partialOpenInputs;

  for (const hole of holes) types.set(hole.port, hole.expected);
  for (const entry of closed) types.set(entry.port, entry.type);

  return types;
}

/** Display names for binders, so a variable occurrence can be labelled. */
function collectBinderNames(graph: Graph): ReadonlyMap<string, string> {
  const names = new Map<string, string>();

  for (const node of graph.nodes) {
    if (node.kind === "Lambda") {
      names.set(
        identityText(node.parameter.id),
        node.parameter.displayName
      );
    } else if (node.kind === "LetRec") {
      names.set(
        identityText(node.recursive.id),
        node.recursive.displayName
      );
    }
  }

  return names;
}
