import { intType } from "../calculus/index.js";
import { createBinderUse, createEdge } from "../graph/index.js";
import { typeGraph } from "../typing/index.js";
import { applyGraphEdit, finalizeGraphCandidate } from "./apply.js";
import { applyGraphEdits } from "./authoring.js";
import { editDiagnostic } from "./diagnostics.js";
function remap(graph, maps) {
    const n = (id) => maps.nodes.get(id) ?? id;
    const p = (id) => maps.ports.get(id) ?? id;
    const r = (id) => maps.regions.get(id) ?? id;
    const b = (id) => maps.binders.get(id) ?? id;
    return Object.freeze({ kind: "Graph", rootRegion: r(graph.rootRegion),
        nodes: Object.freeze(graph.nodes.map((node) => Object.freeze({ ...node, id: n(node.id), region: r(node.region),
            ...(node.kind === "Lambda" ? { parameter: Object.freeze({ ...node.parameter, id: b(node.parameter.id), parameterPort: p(node.parameter.parameterPort) }) } : {}),
            ...(node.kind === "LetRec" ? { definition: n(node.definition), recursive: Object.freeze({ ...node.recursive, id: b(node.recursive.id), valuePort: p(node.recursive.valuePort) }) } : {}) }))),
        ports: Object.freeze(graph.ports.map((port) => Object.freeze({ ...port, id: p(port.id), owner: n(port.owner) }))),
        regions: Object.freeze(graph.regions.map((region) => region.parent === null
            ? Object.freeze({ ...region, id: r(region.id), parent: null, owner: null })
            : Object.freeze({ ...region, id: r(region.id), parent: r(region.parent), owner: n(region.owner) }))),
        edges: Object.freeze(graph.edges.map((edge) => Object.freeze({ ...edge, id: maps.edges.get(edge.id) ?? edge.id,
            source: p(edge.source), target: p(edge.target), ...(edge.kind === "BinderUse" ? { binder: b(edge.binder) } : {}) }))) });
}
function closure(graph, selected) {
    const nodes = new Set(selected.filter((id) => graph.nodes.some((node) => node.id === id)));
    const regions = new Set();
    let changed = true;
    while (changed) {
        changed = false;
        for (const region of graph.regions)
            if (region.owner !== null && nodes.has(region.owner) && !regions.has(region.id)) {
                regions.add(region.id);
                changed = true;
            }
        for (const node of graph.nodes)
            if (regions.has(node.region) && !nodes.has(node.id)) {
                nodes.add(node.id);
                changed = true;
            }
    }
    return { nodes, regions };
}
function refused(graph, message) {
    return { ok: false, diagnostics: [editDiagnostic("INVALID_PROPERTY", "edit", graph.rootRegion, message)] };
}
/** Clone owned regions and internal binders; incoming captures retain their identity. */
export function duplicateSubgraph(graph, selected, context) {
    const inside = closure(graph, selected);
    if (inside.nodes.size === 0)
        return refused(graph, "Select one or more expression nodes.");
    if (graph.nodes.some((node) => inside.nodes.has(node.id) && node.kind === "Output"))
        return refused(graph, "Output is the program boundary. Select its producing expression to duplicate.");
    const nodes = new Map([...inside.nodes].map((id) => [id, context.identities.nextNodeId()]));
    const regions = new Map([...inside.regions].map((id) => [id, context.identities.nextRegionId()]));
    const ports = new Map(graph.ports.filter((port) => inside.nodes.has(port.owner)).map((port) => [port.id, context.identities.nextPortId()]));
    const binders = new Map();
    for (const node of graph.nodes)
        if (inside.nodes.has(node.id)) {
            if (node.kind === "Lambda")
                binders.set(node.parameter.id, context.identities.nextBinderId());
            if (node.kind === "LetRec")
                binders.set(node.recursive.id, context.identities.nextBinderId());
        }
    const incoming = graph.edges.filter((edge) => ports.has(edge.target));
    const edges = new Map(incoming.map((edge) => [edge.id, context.identities.nextEdgeId()]));
    const copy = remap({ ...graph, nodes: graph.nodes.filter((node) => inside.nodes.has(node.id)),
        ports: graph.ports.filter((port) => ports.has(port.id)), regions: graph.regions.filter((region) => regions.has(region.id)), edges: incoming }, { nodes, regions, ports, binders, edges });
    const candidate = Object.freeze({ ...graph, nodes: Object.freeze([...graph.nodes, ...copy.nodes]),
        ports: Object.freeze([...graph.ports, ...copy.ports]), regions: Object.freeze([...graph.regions, ...copy.regions]), edges: Object.freeze([...graph.edges, ...copy.edges]) });
    const checked = finalizeGraphCandidate(graph, candidate, [...nodes.values(), ...ports.values(), ...regions.values(), ...binders.values(), ...edges.values()]);
    return checked.ok ? { ...checked, nodeMap: nodes } : checked;
}
/** Insert a new expression without exposing a disconnected intermediate graph. */
export function insertNodeOnEdge(graph, edgeId, action, inputRole, context) {
    const edge = graph.edges.find((entry) => entry.id === edgeId);
    if (!edge)
        return refused(graph, "Select an existing connection.");
    const created = applyGraphEdit(graph, action, context);
    if (!created.ok)
        return created;
    const node = created.graph.nodes.find((entry) => created.created.includes(entry.id));
    const input = created.graph.ports.find((port) => port.owner === node?.id && port.direction === "input" && port.role === inputRole);
    const output = created.graph.ports.find((port) => port.owner === node?.id && port.direction === "output" && port.role !== "parameter" && port.role !== "recursive");
    if (!input || !output)
        return refused(graph, "Choose an expression with an input and a result, such as Add or Application.");
    const result = applyGraphEdits(created.graph, [{ kind: "Disconnect", edge: edge.id },
        { kind: "Connect", source: edge.source, target: input.id }, { kind: "Connect", source: output.id, target: edge.target }], context);
    return result.ok ? { ...result, created: [...created.created, ...result.created] } : result;
}
/** Preserve stable identities along matching expression paths after a text edit. */
export function reconcileGraphIdentities(before, next) {
    const nodes = new Map();
    const ports = new Map();
    const regions = new Map([[next.rootRegion, before.rootRegion]]);
    const binders = new Map();
    const used = new Set();
    const visited = new Set();
    function walk(a, b) {
        const key = `${a}|${b}`;
        if (visited.has(key))
            return;
        visited.add(key);
        const old = before.nodes.find((node) => node.id === a);
        const fresh = next.nodes.find((node) => node.id === b);
        if (!old || !fresh)
            return;
        if (old.kind === fresh.kind && !used.has(old.id) && !nodes.has(fresh.id)) {
            nodes.set(fresh.id, old.id);
            used.add(old.id);
            for (const port of next.ports.filter((port) => port.owner === fresh.id)) {
                const original = before.ports.find((candidate) => candidate.owner === old.id && candidate.role === port.role);
                if (original)
                    ports.set(port.id, original.id);
            }
            for (const region of next.regions.filter((region) => region.owner === fresh.id)) {
                const original = before.regions.find((candidate) => candidate.owner === old.id && candidate.role === region.role);
                if (original)
                    regions.set(region.id, original.id);
            }
            if (old.kind === "Lambda" && fresh.kind === "Lambda")
                binders.set(fresh.parameter.id, old.parameter.id);
            if (old.kind === "LetRec" && fresh.kind === "LetRec")
                binders.set(fresh.recursive.id, old.recursive.id);
        }
        for (const port of next.ports.filter((port) => port.owner === b && port.direction === "input")) {
            const original = before.ports.find((candidate) => candidate.owner === a && candidate.role === port.role);
            const left = before.edges.find((edge) => edge.target === original?.id);
            const right = next.edges.find((edge) => edge.target === port.id);
            const producerA = before.ports.find((candidate) => candidate.id === left?.source);
            const producerB = next.ports.find((candidate) => candidate.id === right?.source);
            if (producerA && producerB)
                walk(producerA.owner, producerB.owner);
        }
    }
    const oldOutput = before.nodes.find((node) => node.kind === "Output" && node.region === before.rootRegion);
    const newOutput = next.nodes.find((node) => node.kind === "Output" && node.region === next.rootRegion);
    if (oldOutput && newOutput)
        walk(oldOutput.id, newOutput.id);
    const candidate = remap(next, { nodes, ports, regions, binders, edges: new Map() });
    const edges = new Map();
    for (const edge of candidate.edges) {
        const old = before.edges.find((original) => original.source === edge.source && original.target === edge.target && original.kind === edge.kind);
        if (old)
            edges.set(edge.id, old.id);
    }
    // Fresh graph validity is already established by compilation; keep that
    // snapshot if any ambiguous correspondence would introduce a scope error.
    const stable = remap(candidate, { nodes: new Map(), ports: new Map(), regions: new Map(), binders: new Map(), edges });
    return finalizeGraphCandidate(next, stable, []).ok ? stable : next;
}
/** Extract one-result selections into curried functions with explicit parameters. */
export function extractFunction(graph, selected, context) {
    const roots = graph.nodes.filter((node) => selected.includes(node.id));
    if (roots.length === 0 || roots.some((node) => node.kind === "Output" || node.region !== roots[0].region))
        return refused(graph, "Select expressions from one region, without Output.");
    const inside = closure(graph, selected);
    const selectedPorts = new Set(graph.ports.filter((port) => inside.nodes.has(port.owner)).map((port) => port.id));
    const incoming = graph.edges.filter((edge) => !selectedPorts.has(edge.source) && selectedPorts.has(edge.target));
    const outgoing = graph.edges.filter((edge) => selectedPorts.has(edge.source) && !selectedPorts.has(edge.target));
    const outputs = new Set(outgoing.map((edge) => edge.source));
    if (outputs.size !== 1)
        return refused(graph, "Extract a selection with exactly one result connected to the surrounding program.");
    const sources = [...new Set(incoming.map((edge) => edge.source))];
    const typing = typeGraph(graph);
    const types = typing.ok ? typing.typedGraph.portTypes : typing.partialPortTypes;
    const parameters = sources.map((source) => types.find((entry) => entry.port === source)?.type);
    if (parameters.some((type) => type === undefined))
        return refused(graph, "Complete the selection's input types before extracting a function.");
    const region = roots[0].region;
    let candidate = graph;
    const created = [];
    const lambdas = [];
    function create(action) {
        const result = applyGraphEdit(candidate, action, context);
        if (!result.ok)
            return undefined;
        candidate = result.graph;
        created.push(...result.created);
        return candidate.nodes.find((node) => result.created.includes(node.id))?.id;
    }
    for (let index = 0; index < Math.max(1, sources.length); index++) {
        const id = create({ kind: "CreateNode", nodeKind: "Lambda", region: lambdas.at(-1)?.region ?? region,
            binderName: sources.length === 0 ? "unused" : `arg${index + 1}`, parameterType: parameters[index] ?? intType() });
        const node = candidate.nodes.find((node) => node.id === id);
        if (node?.kind !== "Lambda")
            return refused(graph, "Could not create the extracted function.");
        const ports = candidate.ports.filter((port) => port.owner === id);
        lambdas.push({ parameter: node.parameter.parameterPort, binder: node.parameter.id,
            body: ports.find((port) => port.role === "body").id, output: ports.find((port) => port.role === "out").id,
            region: candidate.regions.find((entry) => entry.owner === id).id });
    }
    const applies = [];
    for (const _lambda of lambdas) {
        const id = create({ kind: "CreateNode", nodeKind: "Apply", region });
        if (!id)
            return refused(graph, "Could not create the extracted call.");
        const ports = candidate.ports.filter((port) => port.owner === id);
        applies.push({ argument: ports.find((port) => port.role === "argument").id,
            fn: ports.find((port) => port.role === "function").id, result: ports.find((port) => port.role === "result").id });
    }
    let dummy;
    if (sources.length === 0) {
        const id = create({ kind: "CreateNode", nodeKind: "IntLiteral", value: 0, region });
        dummy = candidate.ports.find((port) => port.owner === id)?.id;
    }
    const edge = (source, target) => {
        const id = context.identities.nextEdgeId();
        created.push(id);
        const declaration = graph.nodes.find((node) => node.kind === "Lambda" ? node.parameter.parameterPort === source : node.kind === "LetRec" && node.recursive.valuePort === source);
        return declaration?.kind === "Lambda" ? createBinderUse({ id, source, target, binder: declaration.parameter.id })
            : declaration?.kind === "LetRec" ? createBinderUse({ id, source, target, binder: declaration.recursive.id }) : createEdge({ id, source, target });
    };
    const extra = lambdas.flatMap((lambda, index) => [
        edge(index === 0 ? lambda.output : applies[index - 1].result, applies[index].fn),
        edge(sources[index] ?? dummy, applies[index].argument),
        edge(index === lambdas.length - 1 ? [...outputs][0] : lambdas[index + 1].output, lambda.body)
    ]);
    const result = applies.at(-1).result;
    const innermost = lambdas.at(-1).region;
    const nodes = candidate.nodes.map((node) => selected.includes(node.id) ? Object.freeze({ ...node, region: innermost }) : node);
    const regions = candidate.regions.map((entry) => entry.owner !== null && selected.includes(entry.owner) && entry.parent === region
        ? Object.freeze({ ...entry, parent: innermost }) : entry);
    const edges = candidate.edges.map((original) => {
        if (incoming.some((entry) => entry.id === original.id)) {
            const lambda = lambdas[sources.indexOf(original.source)];
            return createBinderUse({ id: original.id, source: lambda.parameter, target: original.target, binder: lambda.binder });
        }
        return outgoing.some((entry) => entry.id === original.id) ? createEdge({ id: original.id, source: result, target: original.target }) : original;
    });
    return finalizeGraphCandidate(graph, Object.freeze({ ...candidate, nodes: Object.freeze(nodes), regions: Object.freeze(regions), edges: Object.freeze([...edges, ...extra]) }), created);
}
