import { useRef, useState, type JSX, type ReactNode } from "react";

import { identityText, type SourceId, type NodeId } from "@graphlambda/core";

import { DebuggerTools, type DebugWatch } from "./DebuggerTools.js";
import { completedStepSummary } from "./step-summary.js";
import type { DebugSession } from "./debug-session.js";
import {
  sessionMachine,
  sessionObservation,
  sessionPreviousMachine,
  sessionRule
} from "./debug-session.js";
import {
  closureInspection,
  describeSource,
  machineView,
  machineViewContext,
  type ControlCard,
  type MachineComponent,
  type MachineRow
} from "./machine-view.js";
import { effectLineText, observationView } from "./observation-view.js";
import { provenanceOf } from "./provenance-view.js";

export interface DebuggerPanelProps {
  readonly session: DebugSession;
  readonly breakpoints?: ReadonlySet<NodeId>;
  readonly onToggleBreakpoint?: (node: NodeId) => void;
  readonly watches?: readonly DebugWatch[];
  readonly onWatchesChange?: (watches: readonly DebugWatch[]) => void;
  readonly initialView?: "focus" | "machine";
  /** The state path whose provenance is shown, e.g. `sigma[0]`. */
  readonly selectedPath: string | null;
  readonly onSelectPath: (path: string | null) => void;
  /** Navigate to one source identity already supplied by core provenance. */
  readonly onNavigateSource?: ((source: SourceId) => void) | undefined;
}

/**
 * The debugger.
 *
 * It shows the five components of `m`, the three fields of the derived
 * observation, and — for a selected runtime value — the persistent source
 * elements that anchor it. Every semantic fact on this panel came out of the
 * core: the panel formats, and does not evaluate.
 *
 * There is no summary column for `Sigma = <G,m,omega>` itself. Every field
 * such a column could carry is already drawn by one of the register columns
 * or by the transport, and a second copy of the same fact is a place for the
 * two to disagree. `savamConfigurationView` still projects it for callers
 * that want the whole configuration as text.
 */
export function DebuggerPanel({
  session,
  breakpoints = new Set(), onToggleBreakpoint, watches = [], onWatchesChange,
  initialView = "machine",
  selectedPath,
  onSelectPath,
  onNavigateSource
}: DebuggerPanelProps): JSX.Element {
  const [detailView, setDetailView] = useState(initialView);
  const [toolsOpen, setToolsOpen] = useState(false);
  const toolsToggle = useRef<HTMLButtonElement>(null);
  const machine = sessionMachine(session);
  const observed = observationView(sessionObservation(session));
  const rule = sessionRule(session);

  if (machine === undefined) {
    return (
      <div className="gl-debugger-view">
        <Section title="Evaluation Session">
          <p className="gl-empty">
            {session.error ?? "This graph has no initial machine state."}
          </p>
        </Section>
      </div>
    );
  }

  const view = machineView(
    session.graph,
    machine,
    machineViewContext(
      sessionPreviousMachine(session),
      sessionObservation(session),
      rule
    )
  );
  const provenance =
    selectedPath === null
      ? []
      : provenanceOf(session.graph, machine, selectedPath);
  const closure =
    selectedPath === null
      ? undefined
      : closureInspection(session.graph, machine, selectedPath);

  return (
    <div className="gl-debugger-layout">
    <div className="gl-debugger-contextbar">
      <div className="gl-step-summary" aria-label="Program step summary">
        <div title={completedStepSummary(session)}><strong>Just completed</strong><span>{completedStepSummary(session)}</span></div>
        <div title={`${view.card.label} · ${view.card.text}`}><strong>{view.card.kind === "Done" ? "Result" : "Next"}</strong><span>{view.card.label} · {view.card.text}</span></div>
      </div>
      <div className="gl-debugger-modebar" role="group" aria-label="Debugger detail">
        <button type="button" className="gl-button" aria-pressed={detailView === "focus"} onClick={() => setDetailView("focus")}>Focus view</button>
        <button type="button" className="gl-button" aria-pressed={detailView === "machine"} onClick={() => setDetailView("machine")}>Full machine</button>
      </div>
      {onToggleBreakpoint === undefined || onWatchesChange === undefined ? null : (
        <button ref={toolsToggle} type="button" className="gl-button gl-debugger-tools-toggle" aria-expanded={toolsOpen}
          onClick={() => setToolsOpen((current) => !current)}>Breakpoints and watches <span className="gl-debugger-count">{breakpoints.size} / {watches.length}</span></button>
      )}
    </div>
    <div className="gl-debugger-workarea">
    <div className="gl-debugger-main" tabIndex={0} aria-label="Machine registers and observations">
    <div className={`gl-debugger-view${detailView === "focus" ? " gl-debugger-view--focus" : ""}`} data-debugger-view={detailView}>
      <Section title="Control" badge="c">
        <ControlCardView
          card={view.card}
          row={view.control}
          selectedPath={selectedPath}
          onSelectPath={onSelectPath}
          onNavigateSource={onNavigateSource}
        />
      </Section>

      <Section title="Environment" badge="E" hidden={detailView === "focus"}>
        <RowList
          rows={view.environment}
          component="environment"
          selectedPath={selectedPath}
          onSelectPath={onSelectPath}
          empty="The environment is empty (E = ∅)."
        />
      </Section>

      <Section title={detailView === "focus" ? "Values changed this step" : "Store"} badge="S">
        <RowList
          rows={detailView === "focus" ? view.store.filter((row) => row.delta !== undefined) : view.store}
          component="store"
          selectedPath={selectedPath}
          onSelectPath={onSelectPath}
          empty={detailView === "focus" ? "No stored values changed in this transition. Use Full machine to inspect every value." : "The store is empty (S = ∅)."}
        />
      </Section>

      <Section title="Kontinuation" badge="κ" hidden={detailView === "focus"}>
        <RowList
          rows={view.continuation}
          component="continuation"
          selectedPath={selectedPath}
          onSelectPath={onSelectPath}
          empty="The continuation stack is empty (κ = ε)."
        />
      </Section>

      <Section title="Ready Frontier" badge="Q" hidden={detailView === "focus"}>
        <RowList
          rows={view.ready}
          component="ready"
          selectedPath={selectedPath}
          onSelectPath={onSelectPath}
          empty="The ready frontier is empty (Q = ∅)."
        />
      </Section>

      <Section title="Derived Observation (ω = ⟨F, R, Δ⟩)" badge="ω" hidden={detailView === "focus"}>
        <dl className="gl-facts">
          <Fact label="Base Transition Rule (R)" value={observed.rule ?? rule ?? "—"} mono />
          <dt>Source Focus (F)</dt>
          <dd className="gl-mono gl-truncate">
            {observed.focus === undefined ? "⊥" : (
              <SourceLink
                source={observed.focus}
                label={describeSource(session.graph, observed.focus)}
                onNavigate={onNavigateSource}
              />
            )}
          </dd>
        </dl>
        {observed.effects.length === 0 ? (
          <p className="gl-empty">No visualization effect (Δ = ∅).</p>
        ) : (
          <ul className="gl-effects" aria-label="Visualization Effects (Delta)">
            {observed.effects.map((effect) => (
              <li key={effect.effect} className="gl-mono">
                <span>{effectLineText({ ...effect, subjects: [] })}</span>
                {effect.subjects.map((source) => (
                  <SourceLink
                    key={identityText(source)}
                    source={source}
                    label={describeSource(session.graph, source)}
                    onNavigate={onNavigateSource}
                  />
                ))}
              </li>
            ))}
          </ul>
        )}
      </Section>

      <Section title={detailView === "focus" ? "Source and provenance" : "Source Anchoring and Provenance"} badge="⌖">
        {detailView !== "focus" ? null : <div className="gl-debugger-source-focus">
          <span className="gl-dim">Source focus</span>
          {observed.focus === undefined ? <p className="gl-empty">No transition yet.</p> : <SourceLink source={observed.focus} label={describeSource(session.graph, observed.focus)} onNavigate={onNavigateSource} />}
        </div>}
        {closure === undefined ? null : (
          <div className="gl-closure-detail" data-runtime-kind="closure">
            <h3>Closure Value</h3>
            <dl className="gl-facts">
              <dt>Lambda Abstraction</dt>
              <dd>
                <SourceLink
                  source={closure.value.lambda}
                  label={closure.lambdaLabel}
                  onNavigate={onNavigateSource}
                />
              </dd>
              <dt>Body Region</dt>
              <dd>
                <SourceLink
                  source={closure.value.body}
                  label={closure.bodyLabel}
                  onNavigate={onNavigateSource}
                />
              </dd>
              <dt>Formal Parameter</dt>
              <dd className="gl-mono">{closure.parameterLabel}</dd>
              <dt>Captured Bindings</dt>
              <dd>{closure.captures.length}</dd>
            </dl>
            {closure.captures.length === 0 ? (
              <p className="gl-empty">No captured bindings.</p>
            ) : (
              <ul className="gl-capture-list" aria-label="Closure Environment">
                {closure.captures.map((capture, index) => (
                  <li key={`${capture.kind}:${capture.label}:${index}`}>
                    <span className="gl-machine-label">{capture.label}</span>
                    <span className="gl-mono">{capture.value}</span>
                    {capture.source === undefined ? null : (
                      <SourceLink
                        source={capture.source}
                        label="Reveal Source"
                        onNavigate={onNavigateSource}
                      />
                    )}
                  </li>
                ))}
              </ul>
            )}
          </div>
        )}
        {selectedPath === null ? (
          <p className="gl-empty">
            Select a value or source link to inspect where it came from.
          </p>
        ) : provenance.length === 0 ? (
          <p className="gl-empty">
            {selectedPath} contains no source reference.
          </p>
        ) : (
          <table className="gl-ports" aria-label="Source Provenance">
            <thead>
              <tr>
                <th scope="col">State Path</th>
                <th scope="col">Source Entity</th>
                <th scope="col">Identifier</th>
              </tr>
            </thead>
            <tbody>
              {provenance.map((row) => (
                <tr
                  key={row.path}
                  data-domain={row.resolved ?? "unresolved"}
                  className={row.valid ? undefined : "gl-provenance--invalid"}
                >
                  <td className="gl-mono">{row.path}</td>
                  <td>
                    <SourceLink
                      source={row.id}
                      label={row.description}
                      onNavigate={row.valid ? onNavigateSource : undefined}
                    />
                  </td>
                  <td className="gl-mono gl-truncate">{identityText(row.id)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </Section>
      {/*
        G is the one register with no column of its own. It is not a component
        of `m` at all — it is the fixed external parameter of the relation
        `m ->_G m'` — so there is nothing here for a column to tabulate that
        changes. Saying so is the point: a reader looking for the source graph
        among the machine components should be told why it is not there. The
        note spans the grid rather than occupying a column, because a column
        would imply it is a component.
      */}
      <p className="gl-machine-gloss gl-machine-gloss--banner" hidden={detailView === "focus"}>
        <strong>G</strong> · the persistent source graph is the relation&apos;s
        fixed parameter, not a machine component; it is the canvas itself, and
        no transition writes to it
      </p>

    </div>
    </div>
    {toolsOpen && onToggleBreakpoint !== undefined && onWatchesChange !== undefined ? (
      <DebuggerTools session={session} breakpoints={breakpoints} onToggleBreakpoint={onToggleBreakpoint}
        watches={watches} onWatchesChange={onWatchesChange} onNavigate={onNavigateSource} onClose={() => { setToolsOpen(false); toolsToggle.current?.focus(); }} />
    ) : null}
    </div>
    </div>
  );
}

function SourceLink({
  source,
  label,
  onNavigate
}: {
  readonly source: SourceId;
  readonly label: string;
  readonly onNavigate: ((source: SourceId) => void) | undefined;
}): JSX.Element {
  if (onNavigate === undefined) return <span>{label}</span>;
  return (
    <button
      type="button"
      className="gl-source-link"
      data-source-reference={identityText(source)}
      aria-label={`Go to source: ${label}`}
      title={label}
      onClick={() => onNavigate(source)}
    >
      {label}
    </button>
  );
}

/**
 * `c`, as a card.
 *
 * The card carries three things the control row could not: the *mode* of the
 * control as a pill, so a machine holding a value is distinguishable from one
 * still selecting source at a glance; the control text itself at full width
 * rather than in a third of a row; and the rule that produced it, under a
 * divider, where it does not compete with the step count for space.
 */
function ControlCardView({
  card,
  row,
  selectedPath,
  onSelectPath,
  onNavigateSource
}: {
  readonly card: ControlCard;
  readonly row: MachineRow;
  readonly selectedPath: string | null;
  readonly onSelectPath: (path: string | null) => void;
  readonly onNavigateSource: ((source: SourceId) => void) | undefined;
}): JSX.Element {
  const selected = row.path === selectedPath;

  return (
    <div
      className={
        selected
          ? "gl-control-card gl-control-card--selected"
          : "gl-control-card"
      }
      data-control-kind={card.kind}
    >
      <button
        type="button"
        className="gl-control-kind"
        data-mode={card.mode}
        aria-pressed={selected}
        data-path={row.path}
        title={`Inspect the source anchors of ${row.path}`}
        onClick={() => onSelectPath(selected ? null : row.path)}
      >
        {card.mode}
      </button>
      <div className="gl-control-text gl-mono">
        <span className="gl-control-op">{card.label}</span>{" "}
        {card.anchor === undefined ? (
          <span>{card.text}</span>
        ) : (
          <SourceLink
            source={card.anchor}
            label={card.text}
            onNavigate={onNavigateSource}
          />
        )}
      </div>
      {card.rule === undefined ? null : (
        <div className="gl-control-rule gl-mono">last transition rule · {card.rule}</div>
      )}
    </div>
  );
}

interface RowListProps {
  readonly rows: readonly MachineRow[];
  readonly component: MachineComponent;
  readonly selectedPath: string | null;
  readonly onSelectPath: (path: string | null) => void;
  readonly empty: string;
}

function RowList({
  rows,
  component,
  selectedPath,
  onSelectPath,
  empty
}: RowListProps): JSX.Element {
  if (rows.length === 0) return <p className="gl-empty">{empty}</p>;

  return (
    <ul className="gl-machine-rows" data-component={component}>
      {rows.map((row) => (
        <li key={row.path}>
          <button
            type="button"
            className={rowClassName(row, row.path === selectedPath)}
            aria-pressed={row.path === selectedPath}
            data-path={row.path}
            data-delta={row.delta}
            data-top={row.top ? "true" : undefined}
            onClick={() => {
              onSelectPath(row.path === selectedPath ? null : row.path);
            }}
          >
            <span className="gl-machine-label">
              {row.label}
              {row.nameCollision ? (
                <span
                  className="gl-machine-chip"
                  title="Another live binding is spelled the same way. They are different binders, and lookup follows the identity rather than the name."
                >
                  same name
                </span>
              ) : null}
            </span>
            <span className="gl-mono gl-machine-detail">{row.detail}</span>
            <span className="gl-mono gl-machine-slot">{row.path}</span>
          </button>
        </li>
      ))}
    </ul>
  );
}

function rowClassName(row: MachineRow, selected: boolean): string {
  const names = ["gl-machine-row", `gl-machine-row--${row.form}`];
  if (selected) names.push("gl-machine-row--selected");
  if (row.delta !== undefined) names.push("gl-machine-row--delta");
  if (row.top) names.push("gl-machine-row--top");
  return names.join(" ");
}

interface SectionProps {
  readonly hidden?: boolean;
  readonly title: string;
  /**
   * The register this section shows, drawn as a badge in front of the title.
   *
   * It is `aria-hidden`: the badge is a compact register marker and does not
   * need to be announced in addition to the human-readable heading.
   */
  readonly badge?: string;
  readonly children: ReactNode;
}

function Section({ title, badge, children, hidden = false }: SectionProps): JSX.Element {
  return (
    <section className="gl-section" data-register={badge} hidden={hidden}>
      <h2 className="gl-section-title">
        {badge === undefined ? null : (
          <span className="gl-section-badge" aria-hidden="true">
            {badge}
          </span>
        )}
        {title}
      </h2>
      {children}
    </section>
  );
}

interface FactProps {
  readonly label: string;
  readonly value: string;
  readonly mono?: boolean;
}

function Fact({ label, value, mono = false }: FactProps): JSX.Element {
  return (
    <>
      <dt>{label}</dt>
      <dd className={mono ? "gl-mono gl-truncate" : undefined}>{value}</dd>
    </>
  );
}
