import type {
  EdgeId,
  NodeId,
  NodeKind,
  NodePortRole,
  PortDirection,
  PortId,
  RegionId
} from "@graphlambda/core";

import type { SocketAppearance, TypeClass } from "../ports/port-appearance.js";
import type { FlowchartShapeKind } from "../nodes/FlowchartShape.js";
import type { Point, WireAppearance } from "../wires/wire-appearance.js";

export type { Point };

/**
 * The Scene is the editor's own presentation state.
 *
 * It is derived from a Graph and holds every coordinate in the projection.
 * A Graph never gains an `x`, a `y`, or a size: laying out a graph twice, or
 * laying out a graph whose element arrays are stored in a different order,
 * leaves the graph byte-identical under the core's canonical serializer.
 */
export interface Scene {
  readonly kind: "Scene";
  /** Top-left corner of the painted area. Layout offsets can push it negative. */
  readonly origin: Point;
  readonly width: number;
  readonly height: number;
  /** The region this scene is a view of; the graph root unless one was focused. */
  readonly root: RegionId;
  readonly regions: readonly SceneRegion[];
  readonly nodes: readonly SceneNode[];
  /**
   * Every placed port, including the gutter ports of a focused region whose
   * owning node is outside the view.
   */
  readonly ports: readonly ScenePort[];
  readonly wires: readonly SceneWire[];
  /** BinderUse edges shown as inline data-expression parallelograms. */
  readonly variableUses: readonly SceneVariableUse[];
  /** Presentation-only branch points for outputs with more than one consumer. */
  readonly junctions: readonly SceneJunction[];
}

export interface Box {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

export interface SceneRegion {
  readonly id: RegionId;
  readonly role: string;
  readonly label: string;
  /** Nesting depth, with the root region at 0. */
  readonly depth: number;
  readonly owner: NodeId | null;
  /** Presentation-only disclosure state; semantic contents remain in G. */
  readonly collapsed: boolean;
  readonly box: Box;
  /** Widths reserved for boundary-port labels on each side. */
  readonly gutters: {
    readonly left: number;
    readonly right: number;
  };
}

export interface SceneNode {
  readonly id: NodeId;
  readonly nodeKind: NodeKind;
  readonly region: RegionId;
  readonly shape: FlowchartShapeKind;
  readonly primaryText: string;
  readonly secondaryText: string | undefined;
  readonly box: Box;
  /** The flowchart symbol; owned regions, when present, follow below it. */
  readonly symbolBox: Box;
  readonly ports: readonly ScenePort[];
  /** Regions this node owns, drawn inside its body. */
  readonly ownedRegions: readonly RegionId[];
  /** A fully hidden lambda body, disclosed by a button inside its symbol. */
  readonly collapsedBody?: RegionId;
}

/**
 * A visual variable occurrence anchored to a semantic BinderUse edge.
 *
 * GraphLambda deliberately has no VariableUse source node: lexical uses are
 * BinderUse edges. This glyph therefore carries the EdgeId and uses that
 * edge's existing source/target ports rather than inventing a NodeId or ports.
 */
export interface SceneVariableUse {
  readonly edge: EdgeId;
  readonly source: PortId;
  readonly target: PortId;
  readonly name: string;
  readonly typeText: string;
  readonly typeClass: TypeClass;
  readonly box: Box;
  /** Point on the BinderUse edge that owns a displaced presentation glyph. */
  readonly anchor: Point;
}

/**
 * A port's paint position.
 *
 * `placement` records whether the port sits on the node's own frame or on the
 * frame of a region the node owns. A Lambda's `parameter` is an output that
 * feeds the body, so it belongs on the body region's left gutter; the Lambda's
 * `body` input is fed from inside, so it belongs on that region's right
 * gutter. Drawing them anywhere else would make every lambda's wires cross
 * their own frame.
 */
export type PortPlacement =
  | "node-top"
  | "node-left"
  | "node-right"
  | "node-right-external"
  | "region-left"
  | "region-right";

export interface ScenePort {
  readonly id: PortId;
  readonly owner: NodeId;
  readonly direction: PortDirection;
  readonly role: NodePortRole;
  /** Visible role/type caption or a binder/capture label. */
  readonly label: string;
  /** Bounds of the label as painted, used by the router as an obstacle. */
  readonly labelBox: Box;
  readonly placement: PortPlacement;
  /** The region gutter this port sits on, when it is not on the node frame. */
  readonly region: RegionId | undefined;
  readonly x: number;
  readonly y: number;
  readonly typeClass: TypeClass;
  /** Rendered type, for tooltips and the inspector. Never source text. */
  readonly typeText: string;
  readonly socket: SocketAppearance;
  /**
   * An input port with no incoming edge: a typed hole. `typeText` is the type
   * the hole expects.
   */
  readonly open: boolean;
  /** Same external PortId projected on the focused region, not a new port. */
  readonly capture?: boolean;
}

export interface SceneWire {
  readonly id: EdgeId;
  /** `binder` wires are variable occurrences; `value` wires are plain edges. */
  readonly wireKind: "value" | "binder";
  /** The binder's display name, for a variable occurrence. */
  readonly binderName: string | undefined;
  readonly source: PortId;
  readonly target: PortId;
  readonly path: string;
  /** Orthogonal route vertices, including the exact source and target. */
  readonly route: readonly Point[];
  /** The point halfway along the path, where a value or loop marker sits. */
  readonly midpoint: Point;
  readonly appearance: WireAppearance;
  readonly typeText: string;
  /** A compact Arrow type painted on the wire; scalar types need no badge. */
  readonly typeLabel: SceneWireLabel | undefined;
  /** True when the wire runs right-to-left against the dataflow direction. */
  readonly backEdge: boolean;
  /**
   * True for a recursive occurrence: a variable use of a `LetRec` binder whose
   * consumer lies inside the definition the same `LetRec` declares. Only a
   * `letrec` can authorise one, so only a `letrec` ever draws loop notation.
   */
  readonly feedback: boolean;
  /** Lambda boundaries crossed, reported by core's capture query. */
  readonly captureRegions?: readonly RegionId[];
}

export interface SceneWireLabel {
  readonly text: string;
  readonly box: Box;
}

/**
 * A fan-out junction is notation, not a semantic graph node. Its identity is
 * the source port whose single value is shared by multiple outgoing edges.
 */
export interface SceneJunction {
  readonly source: PortId;
  readonly point: Point;
  readonly typeClass: TypeClass;
}

/** A read-only index from port identity to its placed position. */
export type ScenePortIndex = ReadonlyMap<PortId, ScenePort>;

/** Builds the port index for a scene. */
export function scenePortIndex(scene: Scene): ScenePortIndex {
  return new Map(scene.ports.map((port) => [port.id, port]));
}

/**
 * A per-node layout displacement.
 *
 * This is the whole of what `MoveVisualNode` produces. It lives in editor
 * state, is consumed only by `projectGraph`, and has no semantic meaning: two
 * graphs that differ only in their displacements are the same program, and a
 * displacement can never reach a `Graph`.
 */
export interface LayoutOffset {
  readonly dx: number;
  readonly dy: number;
}

export type LayoutOffsets = ReadonlyMap<NodeId, LayoutOffset>;

/** How to project a graph. Both options are presentation-only. */
export interface ProjectionOptions {
  /** Project this region as the view root instead of the graph's root. */
  readonly root?: RegionId;
  /** Displacements applied to nodes and everything nested inside them. */
  readonly offsets?: LayoutOffsets;
  /** Nested region bodies hidden from this projection. */
  readonly collapsedRegions?: ReadonlySet<RegionId>;
}

/**
 * What the debugger paints over a scene.
 *
 * Every field is read out of a SAVAM configuration and nothing in it is
 * computed here: `focus` and the three effect sets come from the observation
 * `omega`, `anchored` is `srcs(m)`, and `values` is the port store `sigma`
 * rendered as text. The overlay is keyed by identity string because the four
 * source domains are branded strings and a highlight set spans all of them.
 *
 * A scene knows nothing about it — `NO_OVERLAY` is what the editor paints when
 * no run is in progress — so the projection stays a pure function of the graph.
 */
export interface SceneOverlay {
  /** `omega.F`: the source element the last transition acted at. */
  readonly focus: string | undefined;
  /** `srcs(m)`: every source element the machine state currently references. */
  readonly anchored: ReadonlySet<string>;
  /** `omega.Delta.writtenPorts`. */
  readonly written: ReadonlySet<string>;
  /** `omega.Delta.clearedPorts`. */
  readonly cleared: ReadonlySet<string>;
  /** `omega.Delta.enteredRegion`. */
  readonly entered: string | undefined;
  /** Runtime values at source ports, rendered as text. */
  readonly values: ReadonlyMap<string, string>;
}

const NO_STRINGS: ReadonlySet<string> = new Set();

/** The overlay of a scene with no run in progress. */
export const NO_OVERLAY: SceneOverlay = Object.freeze({
  focus: undefined,
  anchored: NO_STRINGS,
  written: NO_STRINGS,
  cleared: NO_STRINGS,
  entered: undefined,
  values: new Map<string, string>()
});
