import type { JSX } from "react";

import type { Box } from "../canvas/scene.js";

/** The standard flowchart silhouettes used by the GraphLambda projection. */
export type FlowchartShapeKind =
  | "data"
  | "process"
  | "preparation"
  | "decision"
  | "terminator";

export interface FlowchartShapeProps {
  readonly box: Box;
  readonly className?: string;
}

/** Data/input-output symbol: a parallelogram. */
export function DataShape({
  box,
  className = "gl-node-symbol"
}: FlowchartShapeProps): JSX.Element {
  const inset = Math.min(16, box.width / 5);
  return (
    <polygon
      className={className}
      points={`${box.x + inset},${box.y} ${box.x + box.width},${box.y} ${
        box.x + box.width - inset
      },${box.y + box.height} ${box.x},${box.y + box.height}`}
    />
  );
}

/** Process symbol: a plain rectangle. */
export function ProcessShape({
  box,
  className = "gl-node-symbol"
}: FlowchartShapeProps): JSX.Element {
  return (
    <rect
      className={className}
      x={box.x}
      y={box.y}
      width={box.width}
      height={box.height}
    />
  );
}

/** Preparation symbol: a hexagon with clipped left and right shoulders. */
export function PreparationShape({
  box,
  className = "gl-node-symbol"
}: FlowchartShapeProps): JSX.Element {
  const inset = Math.min(16, box.width / 5);
  const shoulder = box.height / 2;
  return (
    <polygon
      className={className}
      points={`${box.x + inset},${box.y} ${box.x + box.width - inset},${box.y} ${
        box.x + box.width
      },${box.y + shoulder} ${box.x + box.width - inset},${box.y + box.height} ${
        box.x + inset
      },${box.y + box.height} ${box.x},${box.y + shoulder}`}
    />
  );
}

/** Decision symbol: reserved for If. */
export function DecisionShape({
  box,
  className = "gl-node-symbol"
}: FlowchartShapeProps): JSX.Element {
  return (
    <polygon
      className={className}
      points={`${box.x + box.width / 2},${box.y} ${box.x + box.width},${
        box.y + box.height / 2
      } ${box.x + box.width / 2},${box.y + box.height} ${box.x},${
        box.y + box.height / 2
      }`}
    />
  );
}

/** Terminator symbol: a flat-sided capsule without SVG corner radii. */
export function TerminatorShape({
  box,
  className = "gl-node-symbol"
}: FlowchartShapeProps): JSX.Element {
  const cap = Math.min(box.height / 2, box.width / 4);
  const right = box.x + box.width;
  const bottom = box.y + box.height;
  return (
    <path
      className={className}
      d={`M ${box.x + cap} ${box.y} H ${right - cap} C ${right} ${box.y} ${right} ${bottom} ${
        right - cap
      } ${bottom} H ${box.x + cap} C ${box.x} ${bottom} ${box.x} ${box.y} ${
        box.x + cap
      } ${box.y} Z`}
    />
  );
}

export interface FlowchartShapeComponentProps extends FlowchartShapeProps {
  readonly shape: FlowchartShapeKind;
}

/** Dispatches to one reusable SVG flowchart silhouette. */
export function FlowchartShape({
  shape,
  box,
  className
}: FlowchartShapeComponentProps): JSX.Element {
  const props = { box, ...(className === undefined ? {} : { className }) };

  switch (shape) {
    case "data":
      return <DataShape {...props} />;
    case "process":
      return <ProcessShape {...props} />;
    case "preparation":
      return <PreparationShape {...props} />;
    case "decision":
      return <DecisionShape {...props} />;
    case "terminator":
      return <TerminatorShape {...props} />;
  }
}
