    const ports = byId(graph.ports);
    const regions = byId(graph.regions);
    validateNodes(graph.nodes, regions);
    validatePorts(graph.ports, nodes);
    validateRegionHierarchy(graph, nodes, regions);
    validateLambdaRegions(graph, nodes);
    validateEdges(graph.edges, ports);
