import { immutableMachineValue } from "./value.js";
export function fireControl(node) {
    return Object.freeze({ kind: "Fire", node });
}
export function enterControl(region) {
    return Object.freeze({ kind: "Enter", region });
}
export function returnControl(value) {
    return Object.freeze({
        kind: "Return",
        value: immutableMachineValue(value)
    });
}
export function doneControl(value) {
    return Object.freeze({
        kind: "Done",
        value: immutableMachineValue(value)
    });
}
export function immutableMachineControl(control) {
    switch (control.kind) {
        case "Fire":
            return fireControl(control.node);
        case "Enter":
            return enterControl(control.region);
        case "Return":
            return returnControl(control.value);
        case "Done":
            return doneControl(control.value);
    }
}
