function requireDisplayName(displayName) {
    if (displayName.trim().length === 0) {
        throw new RangeError("Binder display name must not be empty.");
    }
    return displayName;
}
/** Constructs an immutable declaration without conflating its two IDs. */
export function createBinderDeclaration(spec) {
    return Object.freeze({
        kind: "BinderDeclaration",
        id: spec.id,
        displayName: requireDisplayName(spec.displayName),
        parameterPort: spec.parameterPort
    });
}
/** Constructs an immutable letrec declaration without conflating its IDs. */
export function createRecursiveBinderDeclaration(spec) {
    return Object.freeze({
        kind: "RecursiveBinderDeclaration",
        id: spec.id,
        displayName: requireDisplayName(spec.displayName),
        valuePort: spec.valuePort
    });
}
/**
 * Changes presentation-facing spelling while preserving lexical and port
 * identity. Binder uses need no rewrite because they never store names.
 */
export function renameBinderDisplayName(declaration, displayName) {
    return createBinderDeclaration({
        id: declaration.id,
        displayName,
        parameterPort: declaration.parameterPort
    });
}
/** Rename a recursive declaration while retaining binding and source identity. */
export function renameRecursiveBinderDisplayName(declaration, displayName) {
    return createRecursiveBinderDeclaration({
        id: declaration.id,
        displayName,
        valuePort: declaration.valuePort
    });
}
/** Constructs an immutable variable occurrence that explicitly names a binder. */
export function createBinderUse(spec) {
    return Object.freeze({
        kind: "BinderUse",
        id: spec.id,
        binder: spec.binder,
        source: spec.source,
        target: spec.target
    });
}
export function immutableBinderDeclaration(declaration) {
    return createBinderDeclaration(declaration);
}
export function immutableRecursiveBinderDeclaration(declaration) {
    return createRecursiveBinderDeclaration(declaration);
}
export function immutableBinderUse(use) {
    return createBinderUse(use);
}
