import {
  identityText,
  type Observation,
  type SourceId
} from "@graphlambda/core";

/**
 * The presentation of `omega = <F, R, Delta>`.
 *
 * An observation is the only part of a configuration a renderer reads
 * directly, and this module reads it and nothing else. It derives no focus of
 * its own and invents no effect: an observation with no effect renders as an
 * observation with no effect, because a transition that redrew nothing is a
 * fact about the run, not a gap to fill in.
 */
export interface EffectLine {
  /** `write`, `clear`, `enter`, `push`, `pop`, or `done`. */
  readonly effect: string;
  /** The exact field of `Delta` projected by this line. */
  readonly field?: string;
  readonly subjects: readonly SourceId[];
}

export interface ObservationView {
  /** `F`, or `undefined` for the framework's bottom focus. */
  readonly focus: SourceId | undefined;
  /** `R`, the base machine's own rule label. */
  readonly rule: string | undefined;
  /** `Delta`, one line per effect the transition produced. */
  readonly effects: readonly EffectLine[];
  readonly terminated: boolean;
}

/** Projects one observation into panel rows. */
export function observationView(
  subject: Observation | undefined
): ObservationView {
  if (subject === undefined) {
    return Object.freeze({
      focus: undefined,
      rule: undefined,
      effects: Object.freeze([]),
      terminated: false
    });
  }

  const effect = subject.effect;
  const effects: EffectLine[] = [];

  if (effect !== undefined) {
    if (effect.writtenPorts.length > 0) {
      effects.push(line("write", "Δ.writtenPorts", effect.writtenPorts));
    }
    if (effect.clearedPorts.length > 0) {
      effects.push(line("clear", "Δ.clearedPorts", effect.clearedPorts));
    }
    if (effect.enteredRegion !== undefined) {
      effects.push(line("enter", "Δ.enteredRegion", [effect.enteredRegion]));
    }
    if (effect.pushedFrameSite !== undefined) {
      effects.push(line("push", "Δ.pushedFrameSite", [effect.pushedFrameSite]));
    }
    if (effect.poppedFrameSite !== undefined) {
      effects.push(line("pop", "Δ.poppedFrameSite", [effect.poppedFrameSite]));
    }
    if (effect.terminated) effects.push(line("done", "Δ.terminated", []));
  }

  return Object.freeze({
    focus: subject.focus,
    rule: subject.rule,
    effects: Object.freeze(effects),
    terminated: effect?.terminated === true
  });
}

/** Renders one effect line as text, for a compact single-line summary. */
export function effectLineText(subject: EffectLine): string {
  const label = EFFECT_LABELS[subject.effect] ?? subject.effect;
  const field = subject.field ?? EFFECT_FIELDS[subject.effect];
  const heading = field === undefined ? label : `${label} (${field})`;
  return subject.subjects.length === 0
    ? heading
    : `${heading}: ${subject.subjects.map(identityText).join(", ")}`;
}

const EFFECT_LABELS: Readonly<Record<string, string>> = Object.freeze({
  write: "Written ports",
  clear: "Cleared ports",
  enter: "Entered region",
  push: "Pushed continuation site",
  pop: "Popped continuation site",
  done: "Terminal successor"
});

const EFFECT_FIELDS: Readonly<Record<string, string>> = Object.freeze({
  write: "Δ.writtenPorts",
  clear: "Δ.clearedPorts",
  enter: "Δ.enteredRegion",
  push: "Δ.pushedFrameSite",
  pop: "Δ.poppedFrameSite",
  done: "Δ.terminated"
});

function line(
  effect: string,
  field: string,
  subjects: readonly SourceId[]
): EffectLine {
  return Object.freeze({ effect, field, subjects: Object.freeze([...subjects]) });
}
