import type { JSX, PointerEvent as ReactPointerEvent } from "react";

import { NODE_BODY_PADDING, NODE_HEADER_HEIGHT } from "../canvas/metrics.js";
import type { SceneNode } from "../canvas/scene.js";
import { FlowchartShape } from "./FlowchartShape.js";

export interface NodeViewProps {
  readonly node: SceneNode;
  readonly selected: boolean;
  readonly breakpoint?: boolean;
  /** True when the current transition is focused at this node. */
  readonly focused?: boolean;
  /** True when the machine state still holds a reference to this node. */
  readonly anchored?: boolean;
  /** The source identity selected in the provenance inspector. */
  readonly provenance?: boolean;
  readonly onSelect: (node: SceneNode, additive?: boolean) => void;
  readonly onEdit?: ((node: SceneNode) => void) | undefined;
  /** Double-click opens one role-specific default region, when supplied. */
  readonly onEnter?: ((node: SceneNode) => void) | undefined;
  readonly onExpandBody?: (() => void) | undefined;
  readonly onDragStart: (node: SceneNode, event: ReactPointerEvent) => void;
  readonly onDragMove: (event: ReactPointerEvent) => void;
  readonly onDragEnd: (event: ReactPointerEvent) => void;
  /** Pointer cancellation abandons the preview and must not commit a move. */
  readonly onDragCancel: (event: ReactPointerEvent) => void;
}

/**
 * One semantic node's body.
 *
 * Ports are painted in a separate layer above the wires. This component draws
 * the reusable standard flowchart silhouette and its compact two-line label.
 * Owned regions are separate frames below the preparation/decision symbol.
 *
 * Dragging it emits `MoveVisualNode`, which moves the picture and nothing
 * else. A node's position is not part of the program.
 *
 * During a run the node can carry two further states, both source-anchored:
 * the transition's focus `omega.F`, and membership of `srcs(m)`. Selection
 * keeps the accent colour to itself; the run states are drawn as borders, so a
 * node the debugger points at is never confused with a node the user picked.
 */
export function NodeView({
  node,
  selected,
  breakpoint = false,
  focused = false,
  anchored = false,
  provenance = false,
  onSelect,
  onEdit,
  onEnter,
  onExpandBody,
  onDragStart,
  onDragMove,
  onDragEnd,
  onDragCancel
}: NodeViewProps): JSX.Element {
  const { symbolBox } = node;
  const openable = onEnter !== undefined && node.ownedRegions.length > 0;
  const twoLines = node.secondaryText !== undefined;
  const primaryY = twoLines
    ? symbolBox.y + 19
    : symbolBox.y + 26;
  const secondaryY = symbolBox.y + 35;

  return (
    <g
      className={`gl-node gl-node--${node.nodeKind}${selected ? " gl-node--selected" : ""}${
        openable ? " gl-node--openable" : ""
      }${focused ? " gl-node--focus" : ""}${anchored ? " gl-node--anchored" : ""}${
        provenance ? " gl-node--provenance" : ""
      }`}
      data-node-id={node.id}
      data-breakpoint={breakpoint || undefined}
      role="button"
      tabIndex={0}
      onKeyDown={(event) => {
        if (event.key === "F2" && onEdit) { event.preventDefault(); event.stopPropagation(); onEdit(node); return; }
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault(); event.stopPropagation(); onSelect(node, event.ctrlKey || event.metaKey || event.shiftKey);
          if (event.altKey && openable) onEnter?.(node);
        }
      }}
      data-provenance-anchor={provenance || undefined}
      data-node-kind={node.nodeKind}
      data-flowchart-shape={node.shape}
      aria-label={`${node.nodeKind}: ${node.primaryText}`}
      onClick={(event) => {
        event.stopPropagation();
        onSelect(node, event.ctrlKey || event.metaKey || event.shiftKey);
      }}
      onDoubleClick={(event) => {
        event.stopPropagation();
        if (node.nodeKind === "IntLiteral" || node.nodeKind === "BoolLiteral") onEdit?.(node);
        else if (openable && onEnter !== undefined) onEnter(node);
      }}
      onPointerDown={(event) => {
        // The top label band is the drag handle. The regions below a Lambda,
        // If, or LetRec remain independently usable.
        if (event.button !== 0) return;
        if (!onTitleBar(event, symbolBox.height)) return;
        event.stopPropagation();
        onDragStart(node, event);
      }}
      onPointerMove={onDragMove}
      onPointerUp={onDragEnd}
      onPointerCancel={onDragCancel}
    >
      <rect
        className="gl-node-hit"
        x={symbolBox.x}
        y={symbolBox.y}
        width={symbolBox.width}
        height={symbolBox.height}
      />
      <FlowchartShape shape={node.shape} box={symbolBox} />
      {breakpoint ? <circle className="gl-breakpoint-marker" cx={symbolBox.x + 8} cy={symbolBox.y + 8} r={5}><title>Breakpoint before this node</title></circle> : null}
      {selected ? (
        <rect
          className="gl-user-selection-marker"
          x={symbolBox.x + symbolBox.width - 7}
          y={symbolBox.y + symbolBox.height - 7}
          width={6}
          height={6}
        />
      ) : null}
      {provenance ? (
        <path
          className="gl-provenance-corners"
          d={cornerMarkerPath(symbolBox.x, symbolBox.y, symbolBox.width, symbolBox.height)}
        />
      ) : null}
      <text
        className="gl-node-primary"
        x={symbolBox.x + symbolBox.width / 2}
        y={primaryY}
        textAnchor="middle"
      >
        {node.primaryText}
      </text>
      {node.secondaryText === undefined ? null : (
        <text
          className="gl-node-secondary"
          x={symbolBox.x + symbolBox.width / 2}
          y={secondaryY}
          textAnchor="middle"
        >
          {node.secondaryText}
        </text>
      )}
      {node.collapsedBody === undefined || onExpandBody === undefined ? null : (
        <g
          className="gl-region-toggle gl-function-expand"
          role="button"
          tabIndex={0}
          aria-label="Expand Body region"
          aria-expanded={false}
          transform={`translate(${symbolBox.x + (symbolBox.width - 80) / 2} ${symbolBox.y + symbolBox.height - 32 - NODE_BODY_PADDING})`}
          onPointerDown={(event) => event.stopPropagation()}
          onDoubleClick={(event) => event.stopPropagation()}
          onClick={(event) => {
            event.stopPropagation();
            event.currentTarget.parentElement?.focus();
            onExpandBody();
          }}
          onKeyDown={(event) => {
            if (event.key !== "Enter" && event.key !== " ") return;
            event.preventDefault();
            event.stopPropagation();
            event.currentTarget.parentElement?.focus();
            onExpandBody();
          }}
        >
          <rect width={80} height={32} />
          <text x={40} y={21} textAnchor="middle">Expand</text>
        </g>
      )}
    </g>
  );
}

function cornerMarkerPath(x: number, y: number, width: number, height: number): string {
  const right = x + width;
  const bottom = y + height;
  return [
    `M ${x + 9} ${y - 4} H ${x - 4} V ${y + 9}`,
    `M ${right - 9} ${y - 4} H ${right + 4} V ${y + 9}`,
    `M ${x - 4} ${bottom - 9} V ${bottom + 4} H ${x + 9}`,
    `M ${right + 4} ${bottom - 9} V ${bottom + 4} H ${right - 9}`
  ].join(" ");
}

/**
 * Whether the pointer is over the node's title bar.
 *
 * The canvas scales its viewBox to fit, so the header's height on screen is
 * not `NODE_HEADER_HEIGHT` pixels. The node's own painted height gives the
 * conversion without having to reach for the SVG's transform matrix.
 */
function onTitleBar(event: ReactPointerEvent, nodeHeight: number): boolean {
  const rect = event.currentTarget.getBoundingClientRect();
  if (rect.height === 0 || nodeHeight === 0) return true;

  const scale = rect.height / nodeHeight;
  return event.clientY - rect.top <= NODE_HEADER_HEIGHT * scale;
}
