import { useEffect, useRef, useState, type JSX } from "react";
import { getNodePortRoleSpecifications, inputRegion, insertNodeOnEdge, previewIdentities, type EdgeId, type Graph } from "@graphlambda/core";
import type { CreateNodeRequest } from "../state/editor-state.js";
import { Palette } from "./Palette.js";

export function InsertNodeDialog({ graph, edge, onClose, onInsert }: {
  readonly graph: Graph; readonly edge: EdgeId; readonly onClose: () => void;
  readonly onInsert: (request: CreateNodeRequest, role: string) => void;
}): JSX.Element {
  const dialog = useRef<HTMLDialogElement>(null);
  const [request, setRequest] = useState<CreateNodeRequest | null>(null);
  const target = graph.edges.find((entry) => entry.id === edge)?.target;
  const region = target === undefined ? graph.rootRegion : inputRegion(graph, target);
  const roles = (request: CreateNodeRequest): string[] => getNodePortRoleSpecifications(request.nodeKind)
    .filter((port) => port.direction === "input").map((port) => port.role)
    .filter((role) => insertNodeOnEdge(graph, edge, { ...request, region }, role, { identities: previewIdentities(graph) }).ok);
  useEffect(() => { const previous = document.activeElement; dialog.current?.showModal();
    dialog.current?.querySelector<HTMLInputElement>('input[type="search"]')?.focus();
    return () => { if (previous instanceof HTMLElement || previous instanceof SVGElement) previous.focus(); }; }, []);
  return <dialog ref={dialog} className="gl-node-picker" aria-label="Insert node on connection" onCancel={(event) => { event.preventDefault(); onClose(); }}>
    <div className="gl-picker-heading"><h2>Insert on connection</h2><button className="gl-button" onClick={onClose}>Cancel</button></div>
    {request === null ? <><p>Choose an expression, then the input receiving the original value. Other inputs remain available to fill.</p>
      <Palette definition={null} autoFocusSearch onCreate={setRequest}
        unavailableReason={(candidate) => roles(candidate).length === 0 ? "This expression cannot be inserted on the selected connection." : undefined} /></>
      : <><p>Send the original value to {request.nodeKind}:</p>{roles(request).map((role) => <button className="gl-button" key={role} onClick={() => onInsert(request, role)}>Use {role} input</button>)}
        <button className="gl-button" onClick={() => setRequest(null)}>Choose another node</button></>}
  </dialog>;
}
