import type { JSX } from "react";

import type { SceneVariableUse, SceneWire } from "../canvas/scene.js";
import { DataShape } from "./FlowchartShape.js";

export interface VariableUseViewProps {
  readonly use: SceneVariableUse;
  readonly wire: SceneWire;
  readonly selected: boolean;
  readonly provenance?: boolean;
  readonly related?: boolean;
  readonly onSelect: (wire: SceneWire) => void;
}

/**
 * The flowchart data symbol for one lexical variable occurrence.
 *
 * Its semantic identity is the existing BinderUse EdgeId. It intentionally
 * does not claim a NodeId or manufacture ports: the edge's declaration source
 * and consumer target remain the two visible semantic endpoints.
 */
export function VariableUseView({
  use,
  wire,
  selected,
  provenance = false,
  related = false,
  onSelect
}: VariableUseViewProps): JSX.Element {
  const { box } = use;
  const center = { x: box.x + box.width / 2, y: box.y + box.height / 2 };
  const displaced =
    use.anchor.x < box.x || use.anchor.x > box.x + box.width ||
    use.anchor.y < box.y || use.anchor.y > box.y + box.height;
  return (
    <>
      {displaced ? (
        <path
          className="gl-variable-use-leader"
          d={`M ${use.anchor.x} ${use.anchor.y} L ${center.x} ${center.y}`}
        />
      ) : null}
    <g
      className={`gl-variable-use gl-type--${use.typeClass}${
        selected ? " gl-variable-use--selected" : ""
      }${provenance ? " gl-variable-use--provenance" : ""
      }`}
      data-variable-edge-id={use.edge}
      data-related={related || undefined}
      data-provenance-anchor={provenance || undefined}
      data-source-port={use.source}
      data-target-port={use.target}
      onClick={(event) => {
        event.stopPropagation();
        onSelect(wire);
      }}
    >
      <title>{`${use.name} : ${use.typeText}`}</title>
      <DataShape box={box} className="gl-variable-use-symbol" />
      <text
        className="gl-variable-use-name"
        x={box.x + box.width / 2}
        y={box.y + box.height / 2 + 4}
        textAnchor="middle"
      >
        {use.name}
      </text>
    </g>
    </>
  );
}
