import {
  erase,
  initialConfiguration,
  machineSourceReferences,
  observationSourceReferences,
  stepVisual,
  type Graph,
  type MachineState,
  type Observation,
  type PortId,
  type NodeId,
  type SavamConfiguration,
  type SavamRuleLabel,
  type SourceId
} from "@graphlambda/core";

import { NO_OVERLAY, type SceneOverlay } from "../canvas/scene.js";
import { binderNames, describeValue } from "./machine-view.js";

/**
 * A debugging session.
 *
 * The session is a *projection* of the SAVAM relation and holds no evaluator.
 * Advancing it is one call to the core's `stepVisual`, which computes the base
 * step from `erase(Sigma)` and then instruments it; the session installs
 * whatever configuration comes back. There is no rule table here, no
 * arithmetic, and no way for the editor to reach a state the headless driver
 * would not reach — which is what `tests/editor/debugger.test.mjs` checks by
 * running the core's five obligations over the session's own transitions.
 *
 * Stepping backwards is history, not reverse execution: every configuration
 * the session has visited is retained, and stepping back re-installs one. No
 * transition is inverted, because the base relation has no inverse.
 */
export interface DebugStepRecord {
  readonly index: number;
  readonly rule: SavamRuleLabel;
  readonly before: SavamConfiguration;
  readonly after: SavamConfiguration;
}

export type DebugStatus = "ready" | "terminated" | "stuck" | "exhausted";

export interface DebugSession {
  readonly graph: Graph;
  /**
   * The current `Sigma = <G, m, omega>`, or `undefined` for a session that
   * could not start — a graph with no ready node in its root region has no
   * initial state, and the session says so rather than inventing one.
   */
  readonly configuration: SavamConfiguration | undefined;
  /** Every configuration visited, oldest first, the current one last. */
  readonly history: readonly SavamConfiguration[];
  /** Every transition taken, in order. */
  readonly trace: readonly DebugStepRecord[];
  /** How far into `history` the view currently is. */
  readonly cursor: number;
  readonly status: DebugStatus;
  /** Why the session cannot advance, when it cannot. Always the core's text. */
  readonly error: string | undefined;
}

/** The largest number of transitions `runDebugSession` will take at once. */
export const DEBUG_RUN_BUDGET = 2000;

/** A small browser-friendly group of calls to the core step relation. */
export const DEBUG_RUN_BATCH_SIZE = 8;

/**
 * Starts a session on `G`.
 *
 * `initialConfiguration` is the core's; a graph the machine cannot start on
 * throws there, and the session reports that as a stuck run rather than
 * inventing an initial state of its own.
 */
export function createDebugSession(graph: Graph): DebugSession {
  try {
    const configuration = initialConfiguration(graph);
    return session(graph, [configuration], [], 0, terminalStatus(configuration), undefined);
  } catch (cause) {
    return session(
      graph,
      [],
      [],
      -1,
      "stuck",
      cause instanceof Error ? cause.message : String(cause)
    );
  }
}

/** Takes one transition, or reports why none applies. */
export function stepDebugSession(subject: DebugSession): DebugSession {
  const current = subject.configuration;
  if (current === undefined || subject.status === "stuck") return subject;

  // Stepping after stepping back replays the transition already recorded
  // rather than re-deriving it, so history stays a single line.
  const replayed = subject.trace[subject.cursor];
  if (replayed !== undefined) {
    return session(
      subject.graph,
      subject.history,
      subject.trace,
      subject.cursor + 1,
      terminalStatus(replayed.after),
      undefined
    );
  }

  if (erase(current).c.kind === "Done") return subject;

  const step = stepVisual(current);
  if (step === undefined) {
    return session(
      subject.graph,
      subject.history,
      subject.trace,
      subject.cursor,
      "stuck",
      "No base transition applies at the current machine state."
    );
  }

  const record: DebugStepRecord = Object.freeze({
    index: subject.trace.length,
    rule: step.rule,
    before: current,
    after: step.configuration
  });

  return session(
    subject.graph,
    [...subject.history, step.configuration],
    [...subject.trace, record],
    subject.cursor + 1,
    terminalStatus(step.configuration),
    undefined
  );
}

/** Re-installs the previous configuration. Nothing is recomputed. */
export function stepBackDebugSession(subject: DebugSession): DebugSession {
  if (subject.cursor <= 0) return subject;

  return session(
    subject.graph,
    subject.history,
    subject.trace,
    subject.cursor - 1,
    "ready",
    undefined
  );
}

/** Returns to the initial configuration, keeping nothing but the graph. */
export function resetDebugSession(subject: DebugSession): DebugSession {
  return createDebugSession(subject.graph);
}

/** Steps until the control is terminal, the run is stuck, or the budget ends. */
export function runDebugSession(
  subject: DebugSession,
  budget: number = DEBUG_RUN_BUDGET
): DebugSession {
  const current = runDebugSessionBatch(subject, budget);

  return current.status === "ready"
    ? exhaustDebugSession(current, budget)
    : current;
}

/**
 * Advances at most `budget` transitions without declaring exhaustion.
 *
 * The browser uses this wrapper to yield between batches. Each item is still
 * exactly `stepDebugSession` -> core `stepVisual`; there is no evaluator or
 * rule dispatch in the editor.
 */
export function runDebugSessionBatch(
  subject: DebugSession,
  budget: number = DEBUG_RUN_BATCH_SIZE
): DebugSession {
  let current = subject;
  for (let taken = 0; taken < budget; taken += 1) {
    if (current.status !== "ready") return current;
    const next = stepDebugSession(current);
    if (next === current) return current;
    current = next;
  }
  return current;
}

/** Breakpoints and step-over only stop calls to the existing core stepper. */
export function advanceDebugSessionBatch(subject: DebugSession, options: {
  readonly budget: number;
  readonly breakpoints?: ReadonlySet<NodeId>;
  readonly ignoreBreakpointAt?: number;
  readonly over?: { readonly depth: number; readonly fromCursor: number } | undefined;
}): { readonly session: DebugSession; readonly reason: "breakpoint" | "step-over" | undefined } {
  let current = subject;
  for (let taken = 0; taken <= options.budget; taken++) {
    if (current.status !== "ready") break;
    const machine = sessionMachine(current);
    if (machine === undefined) break;
    if (machine.c.kind === "Fire" && options.breakpoints?.has(machine.c.node) && current.cursor !== options.ignoreBreakpointAt) {
      return { session: current, reason: "breakpoint" };
    }
    if (options.over && current.cursor > options.over.fromCursor && machine.kappa.length <= options.over.depth) {
      return { session: current, reason: "step-over" };
    }
    if (taken === options.budget) break;
    const next = stepDebugSession(current);
    if (next === current) break;
    current = next;
  }
  return { session: current, reason: undefined };
}

/** Marks a still-ready session when the UI run budget has actually elapsed. */
export function exhaustDebugSession(
  subject: DebugSession,
  budget: number = DEBUG_RUN_BUDGET
): DebugSession {
  if (subject.status !== "ready") return subject;
  return session(
    subject.graph,
    subject.history,
    subject.trace,
    subject.cursor,
    "exhausted",
    `The run did not terminate within ${budget} transitions.`
  );
}

/** Continue an exhausted configuration without changing or recomputing it. */
export function resumeDebugSession(subject: DebugSession): DebugSession {
  if (subject.status !== "exhausted") return subject;
  return session(
    subject.graph,
    subject.history,
    subject.trace,
    subject.cursor,
    "ready",
    undefined
  );
}

/** The sigma row carrying a value at `port`, for canvas-to-debugger selection. */
export function sessionValuePath(
  subject: DebugSession,
  port: PortId
): string | undefined {
  const machine = sessionMachine(subject);
  if (machine === undefined) return undefined;
  const index = machine.sigma.findIndex((entry) => entry.port === port);
  return index < 0 ? undefined : `sigma[${index}]`;
}

/** The base-machine state the session is showing. */
export function sessionMachine(subject: DebugSession): MachineState | undefined {
  const configuration = subject.configuration;
  return configuration === undefined ? undefined : erase(configuration);
}

/**
 * The base-machine state the session was showing one transition ago.
 *
 * `undefined` at the initial configuration, which no transition produced. It
 * is read out of the retained history rather than recomputed, so stepping back
 * moves the comparison back with it instead of leaving the panel marking the
 * deltas of a step that has been undone.
 */
export function sessionPreviousMachine(
  subject: DebugSession
): MachineState | undefined {
  if (subject.cursor <= 0) return undefined;
  const configuration = subject.history[subject.cursor - 1];
  return configuration === undefined ? undefined : erase(configuration);
}

/** The observation the session is showing. */
export function sessionObservation(
  subject: DebugSession
): Observation | undefined {
  return subject.configuration?.observation;
}

/** The rule that produced the current configuration, if a step produced it. */
export function sessionRule(subject: DebugSession): SavamRuleLabel | undefined {
  return subject.cursor <= 0 ? undefined : subject.trace[subject.cursor - 1]?.rule;
}

/**
 * What the canvas paints over the scene.
 *
 * Everything here is read out of `Sigma`: `focus` and the effect sets from
 * `omega`, `anchored` from `srcs(m)`, and `values` from `sigma`. Rendering a
 * value as text is the only transformation, and it is a string operation on a
 * value the machine already produced.
 */
export function sessionOverlay(subject: DebugSession): SceneOverlay {
  const configuration = subject.configuration;
  if (configuration === undefined) return NO_OVERLAY;

  const machine = erase(configuration);
  const { observation } = configuration;
  const effect = observation.effect;
  const name = binderNames(subject.graph);

  const values = new Map<string, string>();
  for (const entry of machine.sigma) {
    values.set(entry.port, describeValue(entry.value, name));
  }

  return Object.freeze({
    focus: observation.focus,
    anchored: new Set<string>(machineSourceReferences(machine)),
    written: new Set<string>(effect?.writtenPorts ?? []),
    cleared: new Set<string>(effect?.clearedPorts ?? []),
    entered: effect?.enteredRegion,
    values
  });
}

/** Every source identity the current observation mentions. */
export function sessionObservedReferences(
  subject: DebugSession
): readonly SourceId[] {
  const configuration = subject.configuration;
  return configuration === undefined
    ? Object.freeze([])
    : observationSourceReferences(configuration.observation);
}

function terminalStatus(configuration: SavamConfiguration): DebugStatus {
  return erase(configuration).c.kind === "Done" ? "terminated" : "ready";
}

function session(
  graph: Graph,
  history: readonly SavamConfiguration[],
  trace: readonly DebugStepRecord[],
  cursor: number,
  status: DebugStatus,
  error: string | undefined
): DebugSession {
  const configuration = history[cursor];

  return Object.freeze({
    graph,
    configuration,
    history: Object.freeze([...history]),
    trace: Object.freeze([...trace]),
    cursor,
    status: configuration === undefined ? "stuck" : status,
    error
  });
}
