import {
  getDeclaringLambda,
  getDeclaringLetRec,
  identityText,
  type BinderId,
  type ClosureValue,
  type Graph,
  type MachineState,
  type MachineValue,
  type Observation,
  type PortId,
  type SourceId
} from "@graphlambda/core";

/**
 * The presentation of a base-machine state.
 *
 * This module reads `m = <c, rho, sigma, kappa, Q>` and turns it into rows of
 * text. It computes no value, takes no transition, and constructs nothing the
 * machine could consume: every number, every boolean, and every closure it
 * shows was already in the state the core handed over.
 *
 * Each row carries the state path that reaches it — `sigma[2]`, `kappa[0]` —
 * and those paths are the same ones `machineProvenanceReferences` uses, which
 * is what lets a selected row be resolved back to the source elements that
 * anchor it.
 */
export type MachineComponent =
  | "control"
  | "environment"
  | "store"
  | "continuation"
  | "ready";

/**
 * How a row is drawn.
 *
 * `binding` is a finite-function row — one key and one value. That
 * is `rho` and `sigma`. `frame` is a two-line row that names the rule waiting
 * at this position and, underneath, the source element it waits on; that is
 * `kappa` and `Q`, where two entries of the same kind are otherwise
 * indistinguishable in a deep stack.
 */
export type MachineRowForm = "binding" | "frame";

/** Whether the transition that produced this state touched a row. */
export type MachineRowDelta = "added" | "changed";

export interface MachineRow {
  readonly component: MachineComponent;
  readonly form: MachineRowForm;
  /** The state path, e.g. `sigma[2]`. Matches the provenance vocabulary. */
  readonly path: string;
  /** The left-hand label: a binder name, a port role, a frame kind. */
  readonly label: string;
  /** The right-hand text: a rendered value or a source identity. */
  readonly detail: string;
  /**
   * The single source element this row is drawn at, when it has one. The
   * canvas highlights it; rows with no anchor of their own still contribute
   * references through provenance.
   */
  readonly anchor: SourceId | undefined;
  /**
   * Marked when the transition that reached this state introduced or
   * overwrote this row, so a reader is not left to diff two screens by eye to
   * find the one row the rule actually changed. `undefined` on every row of a
   * view built without a context, and on the initial configuration, which no
   * transition produced.
   */
  readonly delta: MachineRowDelta | undefined;
  /**
   * Set on a `rho` row whose display name is carried by another, *different*
   * binder that is live in the same environment.
   *
   * This is deliberately not called shadowing. `rho` is a finite function on
   * `BinderId` and the core refuses a duplicate key, so neither binding hides
   * the other and both remain reachable — lookup follows the identity, never
   * the spelling. The mark says the two rows read alike, which is exactly the
   * moment a reader would otherwise mistake one for the other.
   */
  readonly nameCollision: boolean;
  /**
   * The frame that resumes next, or the node that fires next. A stack whose
   * top is not marked is a list of frames rather than a stack.
   */
  readonly top: boolean;
}

/**
 * `c`, drawn as a card rather than as another row in a list.
 *
 * The control is the one component that is a single fact rather than a
 * collection, and it is the fact the whole panel is arranged around; the
 * remaining four say what is available *to* it.
 */
export interface ControlCard {
  readonly kind: MachineState["c"]["kind"];
  /**
   * `expression` while the control still names source to evaluate, `value`
   * once it carries a computed one. The distinction is the machine's own —
   * `Fire`/`Enter` hold a `SourceId`, `Return`/`Done` hold a `MachineValue`.
   */
  readonly mode: "expression" | "value";
  readonly label: string;
  readonly text: string;
  readonly anchor: SourceId | undefined;
  /**
   * The rule that produced this control. It is the reason to step a machine
   * rather than read its answer, and it is otherwise only in the transport's
   * status line, behind the step count, where it truncates first.
   */
  readonly rule: string | undefined;
}

export interface MachineView {
  /** `c`, always present. */
  readonly control: MachineRow;
  /** `c` again, as the card the panel actually draws. */
  readonly card: ControlCard;
  /** `rho`, in binding order. */
  readonly environment: readonly MachineRow[];
  /** `sigma`, in store order. */
  readonly store: readonly MachineRow[];
  /** `kappa`, top frame first. */
  readonly continuation: readonly MachineRow[];
  /** `Q`, in scheduling order. */
  readonly ready: readonly MachineRow[];
  readonly terminated: boolean;
}

/**
 * What the view needs beyond the state itself in order to mark a delta.
 *
 * Two different sources, on purpose. `writtenPorts`, `clearedPorts` and
 * `pushedFrameSite` are read straight off `omega.Delta` — the core's own
 * account of what a renderer would have to redraw, so `sigma` and `kappa`
 * marks are not the editor's opinion. `rho` has no counterpart in `Delta`, so
 * its marks come from comparing this state's environment against the previous
 * one. That comparison invents no semantics: both states were produced by the
 * core, and the diff is over `BinderId` keys the core assigned.
 */
export interface MachineViewContext {
  readonly previous?: MachineState | undefined;
  readonly writtenPorts?: readonly PortId[] | undefined;
  readonly clearedPorts?: readonly PortId[] | undefined;
  readonly pushedFrameSite?: SourceId | undefined;
  readonly rule?: string | undefined;
}

export interface ClosureCaptureRow {
  readonly kind: "lexical" | "port";
  readonly label: string;
  readonly value: string;
  /** A core-resolved declaration node or captured source port. */
  readonly source: SourceId | undefined;
}

export interface ClosureInspection {
  readonly value: ClosureValue;
  readonly lambdaLabel: string;
  readonly bodyLabel: string;
  readonly parameterLabel: string;
  readonly captures: readonly ClosureCaptureRow[];
}

/** Renders one runtime value. A closure shows the binder it abstracts. */
export function describeValue(
  value: MachineValue,
  binderName: (binder: BinderId) => string
): string {
  switch (value.kind) {
    case "Int":
      return String(value.value);
    case "Bool":
      return value.value ? "true" : "false";
    case "Closure": {
      const recursive =
        value.recursiveBinder === undefined
          ? ""
          : ` [rec ${binderName(value.recursiveBinder)}]`;
      return `closure \\${binderName(value.parameter)}${recursive}`;
    }
  }
}

/** Renders `c` for the control row. */
function describeControl(
  graph: Graph,
  control: MachineState["c"],
  binderName: (binder: BinderId) => string
): { readonly label: string; readonly detail: string; readonly anchor: SourceId | undefined } {
  switch (control.kind) {
    case "Fire":
      return {
        label: "Fire node",
        detail: describeSource(graph, control.node),
        anchor: control.node
      };
    case "Enter":
      return {
        label: "Enter region",
        detail: describeSource(graph, control.region),
        anchor: control.region
      };
    case "Return":
      return {
        label: "Return value",
        detail: describeValue(control.value, binderName),
        anchor: undefined
      };
    case "Done":
      return {
        label: "Final value",
        detail: describeValue(control.value, binderName),
        anchor: undefined
      };
  }
}

/** The frame kinds, and the persistent site each one suspends. */
function frameSite(frame: MachineState["kappa"][number]): SourceId {
  switch (frame.kind) {
    case "ApplyContinuation":
      return frame.application;
    case "IfContinuation":
      return frame.conditional;
    case "LetRecContinuation":
      return frame.letrec;
  }
}

function frameLabel(frame: MachineState["kappa"][number]): string {
  switch (frame.kind) {
    case "ApplyContinuation":
      return "ApplyContinuation";
    case "IfContinuation":
      return "IfContinuation";
    case "LetRecContinuation":
      return "LetRecContinuation";
  }
}

/** A source-aware summary of a suspended evaluation context. */
function frameDetail(
  graph: Graph,
  frame: MachineState["kappa"][number],
  portRole: (port: SourceId) => string
): string {
  const saved = `restore ρ[${frame.callerEnvironment.length}], σ[${frame.callerStore.length}]`;

  switch (frame.kind) {
    case "ApplyContinuation":
      return `${describeSource(graph, frame.body)} · ${portRole(frame.resultPort)} · ${saved}`;
    case "IfContinuation":
      return `${describeSource(graph, frame.branch)} · ${portRole(frame.resultPort)} · ${saved}`;
    case "LetRecContinuation":
      return `${describeSource(graph, frame.scope)} · ${describeSource(graph, frame.definition)} · ${saved}`;
  }
}

/**
 * Gives a persistent source identity a block-lambda-calculus description.
 * Raw identities remain available in provenance; primary machine rows name
 * the calculus construct the identity denotes.
 */
export function describeSource(graph: Graph, source: SourceId): string {
  const node = graph.nodes.find((candidate) => candidate.id === source);
  if (node !== undefined) {
    switch (node.kind) {
      case "IntLiteral":
        return `Integer literal ${node.value}`;
      case "BoolLiteral":
        return `Boolean literal ${node.value ? "true" : "false"}`;
      case "Add":
        return "Integer addition";
      case "Sub":
        return "Integer subtraction";
      case "Mul":
        return "Integer multiplication";
      case "Less":
        return "Integer less-than comparison";
      case "Lambda":
        return `Lambda abstraction \\${node.parameter.displayName}`;
      case "LetRec":
        return `Recursive binding ${node.recursive.displayName}`;
      case "Apply":
        return "Function application";
      case "If":
        return "Conditional expression";
      case "Output":
        return "Program output";
    }
  }

  const region = graph.regions.find((candidate) => candidate.id === source);
  if (region !== undefined) return regionRoleLabel(region.role);

  const port = graph.ports.find((candidate) => candidate.id === source);
  if (port !== undefined) {
    const owner = graph.nodes.find((candidate) => candidate.id === port.owner);
    return `${owner?.kind ?? "Node"}.${port.role} port`;
  }

  const edge = graph.edges.find((candidate) => candidate.id === source);
  if (edge !== undefined) {
    return edge.kind === "BinderUse" ? "Lexical binder use" : "Value-flow edge";
  }

  return identityText(source);
}

function regionRoleLabel(role: string): string {
  switch (role) {
    case "program-root":
    case "root":
      return "Program root region";
    case "lambda-body":
      return "Lambda body region";
    case "letrec-scope":
      return "LetRec scope region";
    case "if-then":
      return "Then-branch region";
    case "if-else":
      return "Else-branch region";
    default:
      return `${role} region`;
  }
}

/**
 * Binder display names, read off the source graph.
 *
 * The environment is keyed by `BinderId`, which is deliberately not a source
 * identity a renderer can resolve, so the name has to come from the declaring
 * node. A binder the graph does not declare falls back to its identity rather
 * than to an invented name.
 */
export function binderNames(graph: Graph): (binder: BinderId) => string {
  const names = new Map<BinderId, string>();

  for (const node of graph.nodes) {
    if (node.kind === "Lambda") {
      names.set(node.parameter.id, node.parameter.displayName);
    } else if (node.kind === "LetRec") {
      names.set(node.recursive.id, node.recursive.displayName);
    }
  }

  return (binder) => names.get(binder) ?? identityText(binder);
}

/**
 * Expands a selected machine row when that row contains a closure.
 *
 * The value and all code anchors are read from the core machine state. Binder
 * identities are resolved to their declaring source node through core's
 * identity-based binder APIs; display names are never used for lookup.
 */
export function closureInspection(
  graph: Graph,
  state: MachineState,
  path: string
): ClosureInspection | undefined {
  const value = machineValueAtRow(state, path);
  if (value?.kind !== "Closure") return undefined;

  const names = binderNames(graph);
  const roles = portRoles(graph);
  const lambda = graph.nodes.find((node) => node.id === value.lambda);
  const body = graph.regions.find((region) => region.id === value.body);

  const lexical = value.environment.map((binding) => {
    const declaration =
      getDeclaringLambda(graph, binding.binder) ??
      getDeclaringLetRec(graph, binding.binder);
    return Object.freeze({
      kind: "lexical" as const,
      label: names(binding.binder),
      value: describeValue(binding.value, names),
      source: declaration?.id as SourceId | undefined
    });
  });
  const capturedPorts = value.capturedPorts.map((capture) =>
    Object.freeze({
      kind: "port" as const,
      label: roles(capture.port),
      value: describeValue(capture.value, names),
      source: capture.port as SourceId
    })
  );

  return Object.freeze({
    value,
    lambdaLabel:
      lambda?.kind === "Lambda"
        ? `\\${lambda.parameter.displayName}`
        : "Lambda",
    bodyLabel:
      body === undefined ? "Lambda body region" : regionRoleLabel(body.role),
    parameterLabel: names(value.parameter),
    captures: Object.freeze([...lexical, ...capturedPorts])
  });
}

/** The value held directly by one selectable machine row. */
function machineValueAtRow(
  state: MachineState,
  path: string
): MachineValue | undefined {
  if (path === "c") {
    return state.c.kind === "Return" || state.c.kind === "Done"
      ? state.c.value
      : undefined;
  }

  const environment = /^rho\[(\d+)\]$/.exec(path);
  if (environment !== null) {
    return state.rho[Number(environment[1])]?.value;
  }

  const store = /^sigma\[(\d+)\]$/.exec(path);
  return store === null ? undefined : state.sigma[Number(store[1])]?.value;
}

/** Port role labels, read off the source graph, for store rows. */
function portRoles(graph: Graph): (port: SourceId) => string {
  const roles = new Map<string, string>();
  const owners = new Map<string, string>();

  for (const node of graph.nodes) owners.set(node.id, node.kind);
  for (const port of graph.ports) {
    roles.set(port.id, `${owners.get(port.owner) ?? "?"}.${port.role}`);
  }

  return (port) => roles.get(port) ?? identityText(port);
}

/**
 * Display names carried by more than one live binder in `rho`.
 *
 * Keyed by name, not by binder: the question a reader has is "do two rows on
 * this screen read the same?", and the answer is a property of the name.
 */
function collidingNames(
  state: MachineState,
  name: (binder: BinderId) => string
): ReadonlySet<string> {
  const binders = new Map<string, BinderId>();
  const collisions = new Set<string>();

  for (const binding of state.rho) {
    const spelled = name(binding.binder);
    const first = binders.get(spelled);
    if (first === undefined) binders.set(spelled, binding.binder);
    else if (first !== binding.binder) collisions.add(spelled);
  }

  return collisions;
}

/** Projects one machine state into the five component views. */
export function machineView(
  graph: Graph,
  state: MachineState,
  context: MachineViewContext = {}
): MachineView {
  const name = binderNames(graph);
  const role = portRoles(graph);
  const control = describeControl(graph, state.c, name);
  const previous = context.previous;
  const collisions = collidingNames(state, name);
  const written = new Set<string>(context.writtenPorts ?? []);
  const cleared = new Set<string>(context.clearedPorts ?? []);

  return Object.freeze({
    control: Object.freeze({
      component: "control" as const,
      form: "frame" as const,
      path: "c",
      label: control.label,
      detail: control.detail,
      anchor: control.anchor,
      delta: undefined,
      nameCollision: false,
      top: true
    }),
    card: Object.freeze({
      kind: state.c.kind,
      mode:
        state.c.kind === "Fire" || state.c.kind === "Enter"
          ? ("expression" as const)
          : ("value" as const),
      label: control.label,
      text: control.detail,
      anchor: control.anchor,
      rule: context.rule
    }),
    environment: Object.freeze(
      state.rho.map((binding, index) => {
        const spelled = name(binding.binder);
        const value = describeValue(binding.value, name);
        const before = previous?.rho.find(
          (candidate) => candidate.binder === binding.binder
        );

        return Object.freeze({
          component: "environment" as const,
          form: "binding" as const,
          path: `rho[${index}]`,
          label: `${spelled} ↦`,
          detail: value,
          anchor: undefined,
          delta:
            previous === undefined
              ? undefined
              : before === undefined
                ? ("added" as const)
                : describeValue(before.value, name) === value
                  ? undefined
                  : ("changed" as const),
          nameCollision: collisions.has(spelled),
          top: false
        });
      })
    ),
    store: Object.freeze(
      state.sigma.map((entry, index) =>
        Object.freeze({
          component: "store" as const,
          form: "binding" as const,
          path: `sigma[${index}]`,
          label: `${role(entry.port)} ↦`,
          detail: describeValue(entry.value, name),
          anchor: entry.port as SourceId,
          // A written port that the previous store did not carry is new; one
          // it did carry was overwritten. A cleared port names an entry the
          // step removed, so it cannot appear as a row here at all — it is
          // listed under the observation instead.
          delta: !written.has(entry.port)
            ? undefined
            : previous?.sigma.some((candidate) => candidate.port === entry.port)
              ? ("changed" as const)
              : ("added" as const),
          nameCollision: false,
          top: false
        })
      )
    ),
    continuation: Object.freeze(
      state.kappa
        .map((frame, index) =>
          Object.freeze({
            component: "continuation" as const,
            form: "frame" as const,
            path: `kappa[${index}]`,
            label: frameLabel(frame),
            detail: frameDetail(graph, frame, role),
            anchor: frameSite(frame),
            delta:
              context.pushedFrameSite !== undefined &&
              context.pushedFrameSite === frameSite(frame) &&
              index === state.kappa.length - 1
                ? ("added" as const)
                : undefined,
            nameCollision: false,
            // The top frame is the last element of a bottom-to-top stack.
            top: index === state.kappa.length - 1
          })
        )
        // The stack is stored bottom-to-top; the top frame is the one that will
        // resume next, so it is shown first.
        .reverse()
    ),
    ready: Object.freeze(
      state.Q.map((node, index) =>
        Object.freeze({
          component: "ready" as const,
          form: "frame" as const,
          path: `Q[${index}]`,
          label: index === 0 ? "fires next" : `ready ${index + 1}`,
          detail: describeSource(graph, node),
          anchor: node as SourceId,
          delta:
            previous === undefined
              ? undefined
              : previous.Q.includes(node)
                ? undefined
                : ("added" as const),
          nameCollision: false,
          top: index === 0
        })
      )
    ),
    terminated: state.c.kind === "Done"
  });
}

/** Reads the marking context out of one session position. */
export function machineViewContext(
  previous: MachineState | undefined,
  observation: Observation | undefined,
  rule: string | undefined
): MachineViewContext {
  // The initial configuration carries an observation with a bottom focus and
  // no effect, because no transition produced it. Marking its rows as deltas
  // would say a step had introduced them, so `previous === undefined` keeps
  // every mark off until the session has actually moved.
  const effect = previous === undefined ? undefined : observation?.effect;

  return Object.freeze({
    previous,
    writtenPorts: effect?.writtenPorts,
    clearedPorts: effect?.clearedPorts,
    pushedFrameSite: effect?.pushedFrameSite,
    rule
  });
}

/** Every row of a view, in panel order. */
export function machineRows(view: MachineView): readonly MachineRow[] {
  return Object.freeze([
    view.control,
    ...view.environment,
    ...view.store,
    ...view.continuation,
    ...view.ready
  ]);
}
