import { useEffect, useRef, type JSX } from "react";
import { createNodeForInput, previewIdentities, checkConnection, inputRegion, typeGraph, prettyOpenInputExpectedType, type Graph, type PortId } from "@graphlambda/core";
import type { CreateNodeRequest } from "../state/editor-state.js";
import { ScopeVariables } from "./ScopeVariables.js";
import { Palette } from "./Palette.js";

export function HolePicker({ graph, target, onCreate, onConnect, onClose }: {
  readonly graph: Graph; readonly target: PortId;
  readonly onCreate: (request: CreateNodeRequest) => void;
  readonly onConnect: (source: PortId) => void;
  readonly onClose: () => void;
}): JSX.Element {
  const dialog = useRef<HTMLDialogElement>(null);
  const port = graph.ports.find((entry) => entry.id === target);
  const owner = graph.nodes.find((entry) => entry.id === port?.owner);
  const typing = typeGraph(graph);
  const holes = typing.ok ? typing.typedGraph.openInputs : typing.partialOpenInputs;
  const expected = holes.find((entry) => entry.port === target)?.expected ?? port?.staticType;
  useEffect(() => {
    const previous = document.activeElement;
    dialog.current?.showModal();
    dialog.current?.querySelector<HTMLInputElement>('input[type="search"]')?.focus();
    return () => { if (previous instanceof HTMLElement || previous instanceof SVGElement) previous.focus(); };
  }, []);
  return <dialog ref={dialog} className="gl-node-picker" aria-label="Fill input"
    onCancel={(event) => { event.preventDefault(); onClose(); }}>
    <div className="gl-picker-heading"><h2>Fill {owner?.kind}.{port?.role}{expected === undefined ? "" : ` : ${prettyOpenInputExpectedType(expected)}`}</h2>
      <button className="gl-button" type="button" onClick={onClose} aria-label="Close input picker">×</button></div>
    <p>Choose an expression. It will be created and connected in one undoable step.</p>
    <ScopeVariables graph={graph} region={inputRegion(graph, target)} target={target} onUse={onConnect} />
    <Palette definition={null} autoFocusSearch onCreate={onCreate} unavailableReason={(request) => {
      const { position: _position, ...action } = request;
      const result = createNodeForInput(graph, { ...action, region: owner?.region ?? graph.rootRegion }, target, { identities: previewIdentities(graph) });
      return result.ok ? undefined : result.diagnostics[0]?.message ?? "Unavailable";
    }} />
    <section aria-label="Existing values"><h3>Use an existing value</h3>
      {graph.ports.filter((entry) => entry.direction === "output" && entry.role !== "parameter" && entry.role !== "recursive" && checkConnection(graph, entry.id, target).ok).map((entry) => {
        const node = graph.nodes.find((candidate) => candidate.id === entry.owner);
        const name = node?.kind === "IntLiteral" || node?.kind === "BoolLiteral" ? `${node.kind} ${node.value}`
          : node?.kind === "Lambda" ? `λ ${node.parameter.displayName}` : node?.kind;
        return <button className="gl-button" type="button" key={entry.id} onClick={() => onConnect(entry.id)}>{name}.{entry.role}</button>;
      })}
    </section>
  </dialog>;
}
