import { useState, type DragEvent, type JSX, type ReactNode } from "react";

import {
  arrowType,
  boolType,
  intType,
  type NodeId,
  type Type
} from "@graphlambda/core";

import { TypePicker } from "../components/TypePicker.js";
import { FlowchartShape, type FlowchartShapeKind } from "./FlowchartShape.js";
import type { CreateNodeRequest } from "../state/editor-state.js";

export interface PaletteProps {
  /** The Lambda a new LetRec would close over, when one is selected. */
  readonly definition: NodeId | null;
  readonly autoFocusSearch?: boolean;
  readonly unavailableReason?: ((request: CreateNodeRequest) => string | undefined) | undefined;
  readonly disabled?: boolean;
  readonly onCreate: (request: CreateNodeRequest) => void;
  /** Keeps the drag payload in React state; no semantic entity exists yet. */
  readonly onDragRequest?: (request: CreateNodeRequest | null) => void;
}

const TYPE_CHOICES: readonly { readonly id: string; readonly label: string; readonly type: Type }[] = [
  { id: "int", label: "Int", type: intType() },
  { id: "bool", label: "Bool", type: boolType() },
  { id: "int-int", label: "Int -> Int", type: arrowType(intType(), intType()) }
];

interface PaletteAction {
  readonly label: string;
  readonly ariaLabel?: string;
  readonly detail: string;
  readonly glyph: string;
  readonly shape: FlowchartShapeKind;
  readonly request: CreateNodeRequest;
  readonly disabled?: boolean;
  readonly title?: string | undefined;
}

/**
 * Compact authoring palette. Each sample uses the same reusable flowchart
 * silhouette as the canvas and dispatches exactly one core-owned CreateNode
 * action, whether it is clicked or dropped.
 */
export function Palette({
  definition,
  autoFocusSearch = false,
  unavailableReason,
  disabled = false,
  onCreate,
  onDragRequest
}: PaletteProps): JSX.Element {
  const [query, setQuery] = useState("");
  const [literal, setLiteral] = useState("0");
  const [binderName, setBinderName] = useState("x");
  const [chosenType, setChosenType] = useState<Type>(intType);

  const literalValue = Number(literal);

  const beginDrag = (
    event: DragEvent<HTMLButtonElement>,
    request: CreateNodeRequest
  ): void => {
    event.dataTransfer.effectAllowed = "copy";
    event.dataTransfer.setData("application/x-graphlambda-node", request.nodeKind);
    onDragRequest?.(request);
  };

  const item = (action: PaletteAction): JSX.Element | null => !`${action.label} ${action.ariaLabel ?? ""} ${action.detail}`.toLowerCase().includes(query.toLowerCase().trim()) ? null : (
    <PaletteItem
      key={action.label}
      {...action}
      disabled={disabled || action.disabled === true || unavailableReason?.(action.request) !== undefined}
      title={unavailableReason?.(action.request) ?? action.title}
      onCreate={onCreate}
      onDragStart={beginDrag}
      onDragEnd={() => onDragRequest?.(null)}
    />
  );

  return (
    <div className="gl-palette" data-searching={query.trim().length > 0 || undefined}>
      <input className="gl-input gl-palette-search" type="search" aria-label="Search nodes"
        placeholder="Search nodes…" value={query} autoFocus={autoFocusSearch}
        onChange={(event) => setQuery(event.currentTarget.value)} />
      <p className="gl-palette-help">Click to add, or drag onto the canvas.</p>
      <PaletteSection title="Core Lambda">
        {item({
          label: "Lambda",
          detail: "function",
          glyph: "\\",
          shape: "preparation",
          request: {
            kind: "CreateNode",
            nodeKind: "Lambda",
            binderName,
            parameterType: chosenType
          }
        })}
        {item({
          label: "Application",
          ariaLabel: "Apply",
          detail: "f()",
          glyph: "f()",
          shape: "process",
          request: { kind: "CreateNode", nodeKind: "Apply" }
        })}
      </PaletteSection>

      <div className="gl-palette-fields">
        <input
          className="gl-mono gl-input"
          type="text"
          aria-label="Binder name"
          value={binderName}
          disabled={disabled}
          onChange={(event) => setBinderName(event.target.value)}
        />
        <TypePicker label="Binder type" value={chosenType} choices={TYPE_CHOICES}
          disabled={disabled} onChange={setChosenType} />
      </div>

      <PaletteSection title="Data">
        {item({
          label: "Integer",
          ariaLabel: "Int",
          detail: Number.isFinite(literalValue) ? literal : "invalid",
          glyph: Number.isFinite(literalValue) ? literal : "?",
          shape: "data",
          request: { kind: "CreateNode", nodeKind: "IntLiteral", value: literalValue },
          disabled: !Number.isFinite(literalValue)
        })}
        {item({
          label: "True",
          ariaLabel: "Bool true",
          detail: "Bool",
          glyph: "T",
          shape: "data",
          request: { kind: "CreateNode", nodeKind: "BoolLiteral", value: true }
        })}
        {item({
          label: "False",
          ariaLabel: "Bool false",
          detail: "Bool",
          glyph: "F",
          shape: "data",
          request: { kind: "CreateNode", nodeKind: "BoolLiteral", value: false }
        })}
      </PaletteSection>
      <input
        className="gl-mono gl-input gl-palette-literal"
        type="text"
        inputMode="numeric"
        aria-label="Integer literal value"
        value={literal}
        disabled={disabled}
        onChange={(event) => setLiteral(event.target.value)}
      />

      <PaletteSection title="Processes">
        {item({ label: "Add", detail: "Int", glyph: "+", shape: "process", request: { kind: "CreateNode", nodeKind: "Add" } })}
        {item({ label: "Subtract", ariaLabel: "Sub", detail: "Int", glyph: "−", shape: "process", request: { kind: "CreateNode", nodeKind: "Sub" } })}
        {item({ label: "Multiply", ariaLabel: "Mul", detail: "Int", glyph: "×", shape: "process", request: { kind: "CreateNode", nodeKind: "Mul" } })}
        {item({ label: "Less", detail: "Bool", glyph: "<", shape: "process", request: { kind: "CreateNode", nodeKind: "Less" } })}
      </PaletteSection>

      <PaletteSection title="Control">
        {item({ label: "If", detail: "branches", glyph: "IF", shape: "decision", request: { kind: "CreateNode", nodeKind: "If" } })}
        {item({
          label: "LetRec",
          detail: "recursive scope",
          glyph: "μ",
          shape: "preparation",
          request: {
            kind: "CreateNode",
            nodeKind: "LetRec",
            binderName,
            recursiveType: chosenType,
            ...(definition === null ? {} : { definition })
          },
          disabled: definition === null,
          ...(definition === null
            ? { title: "Select the Lambda the LetRec should close over" }
            : {})
        })}
      </PaletteSection>

      <p className="gl-palette-no-results">No matching nodes. Try “Add”, “Lambda”, or “Output”.</p>
      <PaletteSection title="Output">
        {item({ label: "Output", detail: "program result", glyph: "Out", shape: "terminator", request: { kind: "CreateNode", nodeKind: "Output" } })}
      </PaletteSection>
    </div>
  );
}

function PaletteSection({ title, children }: {
  readonly title: string;
  readonly children: ReactNode;
}): JSX.Element {
  return (
    <section className="gl-palette-section">
      <h3 className="gl-palette-heading">{title}</h3>
      <div className="gl-palette-grid">{children}</div>
    </section>
  );
}

interface PaletteItemProps extends PaletteAction {
  readonly disabled: boolean;
  readonly onCreate: (request: CreateNodeRequest) => void;
  readonly onDragStart: (event: DragEvent<HTMLButtonElement>, request: CreateNodeRequest) => void;
  readonly onDragEnd: () => void;
}

function PaletteItem({
  label,
  ariaLabel,
  detail,
  glyph,
  shape,
  request,
  disabled,
  title,
  onCreate,
  onDragStart,
  onDragEnd
}: PaletteItemProps): JSX.Element {
  return (
    <button
      type="button"
      className="gl-palette-item"
      aria-label={ariaLabel ?? label}
      draggable={!disabled}
      disabled={disabled}
      title={title ?? `Drag ${label} to the canvas or click to add`}
      data-palette-kind={request.nodeKind}
      onClick={() => onCreate(request)}
      onDragStart={(event) => onDragStart(event, request)}
      onDragEnd={onDragEnd}
    >
      <svg className="gl-palette-sample" viewBox="0 0 52 30" aria-hidden="true">
        <FlowchartShape
          shape={shape}
          box={{ x: 4, y: 4, width: 44, height: 22 }}
          className="gl-palette-sample-shape"
        />
        <text x="26" y="17.5" className="gl-palette-sample-glyph">{glyph}</text>
      </svg>
      <span className="gl-palette-item-copy">
        <span className="gl-palette-item-label">{label}</span>
        <span className="gl-palette-item-detail">{detail}</span>
      </span>
    </button>
  );
}
