import type { JSX, PointerEvent as ReactPointerEvent } from "react";

import { GUTTER_LABEL_OFFSET } from "../canvas/metrics.js";
import type { ScenePort } from "../canvas/scene.js";
import {
  inputArrowPoints,
  outputArrowPoints,
  socketPoints
} from "./port-appearance.js";

export interface PortViewProps {
  readonly port: ScenePort;
  /** Transparent interaction radius in scene units, derived from CSS scale. */
  readonly hitRadius?: number;
  readonly showGuide?: boolean;
  /** True when this port is the output a connection is being drawn from. */
  readonly connectionCheck?: { readonly ok: boolean; readonly diagnostics: readonly { readonly message: string }[] } | undefined;
  readonly pending: boolean;
  /** True when a drag preview is currently over this input socket. */
  readonly candidate?: boolean;
  /** True when the current transition is focused at this port. */
  readonly focused?: boolean;
  /** True when the current transition wrote this port in sigma. */
  readonly written?: boolean;
  /** True when the current transition discarded this port's sigma entry. */
  readonly cleared?: boolean;
  /** The exact source port selected in the provenance inspector. */
  readonly provenance?: boolean;
  readonly related?: boolean;
  /**
   * The runtime value standing at this port, rendered as text. Present only
   * when no drawn wire is already carrying it.
   */
  readonly value?: string | undefined;
  /** Inverse fitted scale used to retain a 28 CSS-pixel interaction target. */
  readonly detailScale?: number;
  readonly onSelect: (port: ScenePort, point?: { readonly x: number; readonly y: number }) => void;
  /** Starts a presentation-only drag preview from an output port. */
  readonly onConnectionStart: (port: ScenePort, event: ReactPointerEvent) => void;
}

/**
 * One connection point.
 *
 * An input port is a socket whose silhouette is the type it expects; a socket
 * with no incoming edge is a typed hole and is drawn hollow, with the expected
 * type spelled out beside it. An output port is the arrow the wires leave
 * from.
 *
 * Clicking an output starts a connection and clicking an input completes it.
 * Whether the completed connection is legal is not decided here — the core
 * decides, and the editor shows what it said.
 *
 * During a run a port can be written, cleared, or focused, and can carry a
 * value from the store. The value is text the debugger rendered from `sigma`;
 * nothing here computes one.
 */
export function PortView({
  port,
  hitRadius = 16,
  showGuide = true,
  pending,
  connectionCheck,
  candidate = false,
  focused = false,
  written = false,
  cleared = false,
  provenance = false,
  related = false,
  value,
  detailScale = 1,
  onSelect,
  onConnectionStart
}: PortViewProps): JSX.Element {
  const label = port.label;
  const onGutter =
    port.placement === "region-left" || port.placement === "region-right";
  const onTop = port.placement === "node-top";
  const outsideRight = port.placement === "node-right-external";
  // A gutter label is centred under its socket; the gutter is sized for it.
  // A label beside a gutter socket would run into the nodes inside the frame.
  const textAnchor = onGutter || onTop
    ? "middle"
    : port.placement === "node-left" || outsideRight ? "start" : "end";
  const labelX = onGutter || onTop
    ? 0
    : port.placement === "node-left" ? 10 : outsideRight ? 10 : -10;
  const labelY = onGutter ? GUTTER_LABEL_OFFSET : onTop ? 22 : outsideRight ? -10 : 3;

  return (
    <g
      className={`gl-port gl-port--${port.direction} gl-type--${port.typeClass}${
        port.open ? " gl-port--open" : ""
      }${pending ? " gl-port--pending" : ""}${focused ? " gl-port--focus" : ""}${
        candidate ? " gl-port--candidate" : ""
      }${written ? " gl-port--written" : ""}${cleared ? " gl-port--cleared" : ""}`}
      data-port-id={port.id}
      data-related={related || undefined}
      data-connection-status={connectionCheck === undefined ? undefined : connectionCheck.ok ? "compatible" : "unavailable"}
      role="button"
      tabIndex={0}
      aria-label={`${port.direction} ${port.role} : ${port.typeText}`}
      onKeyDown={(event) => {
        if (event.key === "Enter" || event.key === " ") { event.preventDefault(); event.stopPropagation(); onSelect(port); }
      }}
      data-provenance-anchor={provenance || undefined}
      data-owner-id={port.owner}
      data-role={port.role}
      data-placement={port.placement}
      data-projected-capture={port.capture || undefined}
      transform={`translate(${port.x} ${port.y})`}
      onClick={(event) => {
        event.stopPropagation();
        onSelect(port, { x: event.clientX, y: event.clientY });
      }}
      onPointerDown={(event) => {
        if (port.direction !== "output" || event.button !== 0) return;
        event.stopPropagation();
        onConnectionStart(port, event);
      }}
    >
      <title>{connectionCheck?.ok === false ? connectionCheck.diagnostics[0]?.message : port.capture ? `${port.label} · source ${port.id}` : `${port.role} : ${port.typeText}`}</title>
      <g className="gl-port-hit">
        {showGuide ? <rect
          className="gl-port-target-guide"
          x={-hitRadius}
          y={-hitRadius}
          width={hitRadius * 2}
          height={hitRadius * 2}
        /> : null}
        <circle className="gl-port-target-core" cx={0} cy={0} r={7} />
      </g>
      <g className="gl-port-detail" transform={`scale(${detailScale})`}>
        {provenance ? <circle className="gl-port-provenance-ring" cx={0} cy={0} r={9} /> : null}
        {port.direction === "input" ? (
          <>
            <path
              className="gl-input-flow-stem"
              d={onTop ? "M 0 -16 V -12" : "M -16 0 H -12"}
              fill="none"
            />
            <polygon
              className="gl-input-flow-tip"
              points={onTop ? "-3,-12 0,-5 3,-12" : inputArrowPoints()}
            />
            <polygon className="gl-socket" points={socketPoints(port.socket)} />
          </>
        ) : (
          <>
            {port.capture ? <polygon className="gl-socket" points={socketPoints(port.socket)} /> : null}
            <path className="gl-output-flow-stem" d="M 0 0 H 12" fill="none" />
            <polygon className="gl-emitter" points={outputArrowPoints()} />
          </>
        )}
        {label.length === 0 ? null : (
          <text className="gl-port-label" x={labelX} y={labelY} textAnchor={textAnchor}>
            {label}
          </text>
        )}
        {value === undefined ? null : (
          <text className="gl-runtime-value" x={0} y={-10} textAnchor="middle">
            {value}
          </text>
        )}
      </g>
    </g>
  );
}

/** Enlarged targets sit below node bodies so they cannot steal title clicks. */
export function PortTarget({ port, radius, onSelect, onConnectionStart }: {
  readonly port: ScenePort;
  readonly radius: number;
  readonly onSelect: PortViewProps["onSelect"];
  readonly onConnectionStart: PortViewProps["onConnectionStart"];
}): JSX.Element {
  return <g className="gl-port-target-zone" transform={`translate(${port.x} ${port.y})`}
    onClick={(event) => { event.stopPropagation(); onSelect(port, { x: event.clientX, y: event.clientY }); }}
    onPointerDown={(event) => {
      if (port.direction !== "output" || event.button !== 0) return;
      event.stopPropagation(); onConnectionStart(port, event);
    }}>
    <rect className="gl-port-target-guide" x={-radius} y={-radius} width={radius * 2} height={radius * 2} />
  </g>;
}
