/**
 * Creates a deterministic factory. Supplying the same namespace and allocating
 * identities in the same order produces exactly the same identity strings.
 * This is intended for tests and reproducible fixture construction.
 */
export function createDeterministicIdentityFactory(namespace) {
    const validatedNamespace = requireNamespace(namespace);
    let nextSequence = 0;
    const allocate = (domain) => {
        nextSequence += 1;
        return mint(domain, `${validatedNamespace}:${nextSequence}`);
    };
    return Object.freeze({
        namespace: validatedNamespace,
        nextNodeId: () => allocate("node"),
        nextPortId: () => allocate("port"),
        nextEdgeId: () => allocate("edge"),
        nextRegionId: () => allocate("region"),
        nextBinderId: () => allocate("binder")
    });
}
let nextFreshFactorySequence = 0;
function freshNamespace() {
    nextFreshFactorySequence += 1;
    const timestamp = Date.now().toString(36);
    const localSequence = nextFreshFactorySequence.toString(36);
    const entropy = Math.random().toString(36).slice(2);
    return `fresh-${timestamp}-${localSequence}-${entropy}`;
}
