/** Structural type equality. Arrow types are compared recursively. */
export function typeEquals(left, right) {
    if (left === right)
        return true;
    switch (left.kind) {
        case "Int":
            return right.kind === "Int";
        case "Bool":
            return right.kind === "Bool";
        case "Arrow":
            return (right.kind === "Arrow" &&
                typeEquals(left.parameter, right.parameter) &&
                typeEquals(left.result, right.result));
    }
}
/**
 * Structural expression equality.
 *
 * This deliberately compares binder names and therefore is not
 * alpha-equivalence.
 */
export function expressionEquals(left, right) {
    if (left === right)
        return true;
    switch (left.kind) {
        case "Variable":
            return right.kind === "Variable" && left.name === right.name;
        case "IntLiteral":
            return right.kind === "IntLiteral" && left.value === right.value;
        case "BoolLiteral":
            return right.kind === "BoolLiteral" && left.value === right.value;
        case "Lambda":
            return (right.kind === "Lambda" &&
                left.parameter === right.parameter &&
                typeEquals(left.parameterType, right.parameterType) &&
                expressionEquals(left.body, right.body));
        case "Apply":
            return (right.kind === "Apply" &&
                expressionEquals(left.callee, right.callee) &&
                expressionEquals(left.argument, right.argument));
        case "Let":
            return (right.kind === "Let" &&
                left.binder === right.binder &&
                expressionEquals(left.initializer, right.initializer) &&
                expressionEquals(left.body, right.body));
        case "LetRec":
            return (right.kind === "LetRec" &&
                left.binder === right.binder &&
                typeEquals(left.binderType, right.binderType) &&
                expressionEquals(left.initializer, right.initializer) &&
                expressionEquals(left.body, right.body));
        case "If":
            return (right.kind === "If" &&
                expressionEquals(left.condition, right.condition) &&
                expressionEquals(left.thenBranch, right.thenBranch) &&
                expressionEquals(left.elseBranch, right.elseBranch));
        case "Add":
            return (right.kind === "Add" &&
                expressionEquals(left.left, right.left) &&
                expressionEquals(left.right, right.right));
        case "Sub":
            return (right.kind === "Sub" &&
                expressionEquals(left.left, right.left) &&
                expressionEquals(left.right, right.right));
        case "Mul":
            return (right.kind === "Mul" &&
                expressionEquals(left.left, right.left) &&
                expressionEquals(left.right, right.right));
        case "Less":
            return (right.kind === "Less" &&
                expressionEquals(left.left, right.left) &&
                expressionEquals(left.right, right.right));
    }
}
/** Structural equality specialized to call-by-value values. */
export function valueEquals(left, right) {
    return expressionEquals(left, right);
}
