import { useState, type JSX } from "react";
import type { GraphNode, NodePropertyUpdate } from "@graphlambda/core";
import type { SceneNode } from "../canvas/scene.js";

export function InlineNodeEditor({ node, semantic, onCommit, onClose }: {
  readonly node: SceneNode; readonly semantic: GraphNode;
  readonly onCommit: (update: NodePropertyUpdate) => void; readonly onClose: () => void;
}): JSX.Element {
  const initial = semantic.kind === "IntLiteral" || semantic.kind === "BoolLiteral" ? String(semantic.value)
    : semantic.kind === "Lambda" ? semantic.parameter.displayName : semantic.kind === "LetRec" ? semantic.recursive.displayName : "";
  const [text, setText] = useState(initial);
  const valid = semantic.kind === "IntLiteral" ? text.trim() !== "" && Number.isSafeInteger(Number(text)) : text.trim() !== "";
  const commit = (): void => {
    if (!valid) return;
    if (semantic.kind === "IntLiteral") onCommit({ kind: "IntLiteralValue", value: Number(text) });
    else if (semantic.kind === "BoolLiteral") onCommit({ kind: "BoolLiteralValue", value: text === "true" });
    else if (semantic.kind === "Lambda") onCommit({ kind: "LambdaParameterName", name: text.trim() });
    else if (semantic.kind === "LetRec") onCommit({ kind: "LetRecBinderName", name: text.trim() });
  };
  return <foreignObject x={node.symbolBox.x + 8} y={node.symbolBox.y + 4} width={Math.max(180, node.symbolBox.width - 16)} height={114}>
    <form className="gl-inline-editor" aria-label="Edit node directly" onSubmit={(event) => { event.preventDefault(); commit(); }}
      onPointerDown={(event) => event.stopPropagation()} onClick={(event) => event.stopPropagation()}
      onDoubleClick={(event) => event.stopPropagation()} onKeyDown={(event) => { event.stopPropagation(); if (event.key === "Escape") { event.preventDefault(); onClose(); } }}>
      <label>{semantic.kind === "IntLiteral" || semantic.kind === "BoolLiteral" ? "Value" : "Binder name"}
        {semantic.kind === "BoolLiteral" ? <select autoFocus value={text} onChange={(event) => setText(event.currentTarget.value)}><option>true</option><option>false</option></select>
          : <input autoFocus className="gl-input" value={text} onFocus={(event) => event.currentTarget.select()} onChange={(event) => setText(event.currentTarget.value)} />}</label>
      <div><button type="submit" className="gl-button" disabled={!valid}>Apply</button><button type="button" className="gl-button" onClick={onClose}>Cancel</button></div>
    </form>
  </foreignObject>;
}
