const LOWEST_PRECEDENCE = 0;
const COMPARISON_PRECEDENCE = 1;
const ADDITIVE_PRECEDENCE = 2;
const MULTIPLICATIVE_PRECEDENCE = 3;
const APPLICATION_PRECEDENCE = 4;
const ATOM_PRECEDENCE = 5;
/** Render a type in canonical textual λG syntax. */
export function prettyType(type) {
    switch (type.kind) {
        case "Int":
            return "Int";
        case "Bool":
            return "Bool";
        case "Arrow": {
            const parameter = type.parameter.kind === "Arrow"
                ? `(${prettyType(type.parameter)})`
                : prettyType(type.parameter);
            return `${parameter} -> ${prettyType(type.result)}`;
        }
    }
}
/** Render an expression in canonical textual λG syntax. */
export function prettyExpression(expression) {
    return renderExpression(expression, LOWEST_PRECEDENCE);
}
function renderExpression(expression, minimumPrecedence) {
    let precedence;
    let rendered;
    switch (expression.kind) {
        case "Variable":
            precedence = ATOM_PRECEDENCE;
            rendered = expression.name;
            break;
        case "IntLiteral":
            precedence = ATOM_PRECEDENCE;
            rendered = String(expression.value);
            break;
        case "BoolLiteral":
            precedence = ATOM_PRECEDENCE;
            rendered = expression.value ? "true" : "false";
            break;
        case "Lambda":
            precedence = LOWEST_PRECEDENCE;
            rendered = `\\${expression.parameter}:${prettyType(expression.parameterType)}. ${renderExpression(expression.body, LOWEST_PRECEDENCE)}`;
            break;
        case "Apply":
            precedence = APPLICATION_PRECEDENCE;
            rendered = `${renderExpression(expression.callee, APPLICATION_PRECEDENCE)} ${renderApplicationArgument(expression.argument)}`;
            break;
        case "Let":
            precedence = LOWEST_PRECEDENCE;
            rendered = `let ${expression.binder} = ${renderExpression(expression.initializer, LOWEST_PRECEDENCE)} in ${renderExpression(expression.body, LOWEST_PRECEDENCE)}`;
            break;
        case "LetRec":
            precedence = LOWEST_PRECEDENCE;
            rendered = `letrec ${expression.binder} : ${prettyType(expression.binderType)} = ${renderExpression(expression.initializer, LOWEST_PRECEDENCE)} in ${renderExpression(expression.body, LOWEST_PRECEDENCE)}`;
            break;
        case "If":
            precedence = LOWEST_PRECEDENCE;
            rendered = `if ${renderExpression(expression.condition, LOWEST_PRECEDENCE)} then ${renderExpression(expression.thenBranch, LOWEST_PRECEDENCE)} else ${renderExpression(expression.elseBranch, LOWEST_PRECEDENCE)}`;
            break;
        case "Add":
            precedence = ADDITIVE_PRECEDENCE;
            rendered = renderBinary(expression.left, "+", expression.right, ADDITIVE_PRECEDENCE, false);
            break;
        case "Sub":
            precedence = ADDITIVE_PRECEDENCE;
            rendered = renderBinary(expression.left, "-", expression.right, ADDITIVE_PRECEDENCE, false);
            break;
        case "Mul":
            precedence = MULTIPLICATIVE_PRECEDENCE;
            rendered = renderBinary(expression.left, "*", expression.right, MULTIPLICATIVE_PRECEDENCE, false);
            break;
        case "Less":
            precedence = COMPARISON_PRECEDENCE;
            rendered = renderBinary(expression.left, "<", expression.right, COMPARISON_PRECEDENCE, true);
            break;
    }
    return precedence < minimumPrecedence ? `(${rendered})` : rendered;
}
function renderApplicationArgument(argument) {
    // `f -1` is otherwise parsed as subtraction. Parentheses keep a negative
    // literal unambiguously in the application-argument position.
    if (argument.kind === "IntLiteral" && argument.value < 0) {
        return `(${renderExpression(argument, LOWEST_PRECEDENCE)})`;
    }
    return renderExpression(argument, ATOM_PRECEDENCE);
}
function renderBinary(left, operator, right, precedence, parenthesizeLeftPeer) {
    const leftMinimum = parenthesizeLeftPeer ? precedence + 1 : precedence;
    return `${renderExpression(left, leftMinimum)} ${operator} ${renderExpression(right, precedence + 1)}`;
}
