export function editDiagnostic(code, origin, subject, message, checkerCode) {
    return Object.freeze({
        code,
        origin,
        subject,
        message,
        checkerCode
    });
}
/**
 * A stable key for one diagnostic occurrence.
 *
 * Edits are validated differentially: a graph under construction is routinely
 * not well formed — a Lambda whose body is still empty is rejected by
 * `validateLexicalScope`, and that is correct — so an action is refused only
 * for the diagnostics it *introduces*. Comparing occurrences by this key, as a
 * multiset, is what makes "introduces" precise.
 */
export function diagnosticKey(diagnostic) {
    return [
        diagnostic.origin,
        diagnostic.code,
        diagnostic.checkerCode ?? "",
        diagnostic.subject,
        diagnostic.message
    ].join("�");
}
