import { identityText } from "./identities.js";
export function getNode(graph, id) {
    return graph.nodes.find((node) => node.id === id);
}
export function getPort(graph, id) {
    return graph.ports.find((port) => port.id === id);
}
export function getEdge(graph, id) {
    return graph.edges.find((edge) => edge.id === id);
}
export function getRegion(graph, id) {
    return graph.regions.find((region) => region.id === id);
}
export function resolveSourceId(graph, id) {
    const text = identityText(id);
    return (graph.nodes.find((node) => identityText(node.id) === text) ??
        graph.ports.find((port) => identityText(port.id) === text) ??
        graph.edges.find((edge) => identityText(edge.id) === text) ??
        graph.regions.find((region) => identityText(region.id) === text));
}
export function nodesInRegion(graph, regionId) {
    return Object.freeze(graph.nodes.filter((node) => node.region === regionId));
}
export function childRegions(graph, regionId) {
    return Object.freeze(graph.regions.filter((region) => region.parent === regionId));
}
export function portsOfNode(graph, nodeId) {
    return Object.freeze(graph.ports.filter((port) => port.owner === nodeId));
}
