import {
  getIfBranchRegion,
  getLambdaBodyRegion,
  getLetRecScopeRegion,
  getNode,
  getRegion,
  type Graph,
  type GraphNode,
  type NodeId,
  type RegionId
} from "@graphlambda/core";

export type RegionPurpose = "body" | "then" | "else" | "scope";

/** One exact semantic region offered as an editor navigation destination. */
export interface RegionNavigationItem {
  readonly id: RegionId;
  readonly purpose: RegionPurpose;
  readonly label: string;
}

/** One visible breadcrumb token. Owner tokens describe context; region tokens navigate. */
export interface RegionBreadcrumbItem {
  readonly key: string;
  readonly label: string;
  readonly region: RegionId | undefined;
}

/**
 * Returns the regions a selected owner can open, using the core's role-specific
 * queries rather than array position or SVG containment.
 */
export function nodeRegionNavigation(
  graph: Graph,
  owner: NodeId | null
): readonly RegionNavigationItem[] {
  if (owner === null) return Object.freeze([]);
  const node = getNode(graph, owner);
  if (node === undefined) return Object.freeze([]);

  switch (node.kind) {
    case "Lambda":
      return compact([
        navigation(getLambdaBodyRegion(graph, node.id)?.id, "body", "Body")
      ]);
    case "If":
      return compact([
        navigation(getIfBranchRegion(graph, node.id, "then")?.id, "then", "Then"),
        navigation(getIfBranchRegion(graph, node.id, "else")?.id, "else", "Else")
      ]);
    case "LetRec":
      return compact([
        navigation(getLetRecScopeRegion(graph, node.id)?.id, "scope", "Scope")
      ]);
    default:
      return Object.freeze([]);
  }
}

/** Builds `root / owner / role` labels for the currently focused region. */
export function regionBreadcrumb(
  graph: Graph,
  focused: RegionId
): readonly RegionBreadcrumbItem[] {
  const regions = [];
  const visited = new Set<string>();
  let current = getRegion(graph, focused);

  while (current !== undefined && !visited.has(current.id)) {
    regions.unshift(current);
    visited.add(current.id);
    current = current.parent === null ? undefined : getRegion(graph, current.parent);
  }

  const items: RegionBreadcrumbItem[] = [];
  for (const [index, region] of regions.entries()) {
    if (index === 0) {
      items.push(Object.freeze({ key: region.id, label: "root", region: region.id }));
      continue;
    }

    const owner = region.owner === null ? undefined : getNode(graph, region.owner);
    if (owner !== undefined) {
      items.push(Object.freeze({
        key: `${region.id}:owner`,
        label: ownerBreadcrumbLabel(owner),
        region: undefined
      }));
    }
    items.push(Object.freeze({
      key: region.id,
      label: regionPurpose(region.role),
      region: region.id
    }));
  }

  return Object.freeze(items);
}

function navigation(
  id: RegionId | undefined,
  purpose: RegionPurpose,
  label: string
): RegionNavigationItem | undefined {
  return id === undefined ? undefined : Object.freeze({ id, purpose, label });
}

function compact(
  items: readonly (RegionNavigationItem | undefined)[]
): readonly RegionNavigationItem[] {
  return Object.freeze(
    items.filter((item): item is RegionNavigationItem => item !== undefined)
  );
}

function ownerBreadcrumbLabel(node: GraphNode): string {
  switch (node.kind) {
    case "Lambda":
      return `\\${node.parameter.displayName}`;
    case "If":
      return "if";
    case "LetRec":
      return `letrec ${node.recursive.displayName}`;
    default:
      return node.kind.toLowerCase();
  }
}

function regionPurpose(role: string): string {
  switch (role) {
    case "lambda-body":
      return "body";
    case "if-then":
      return "then";
    case "if-else":
      return "else";
    case "letrec-scope":
      return "scope";
    default:
      return role;
  }
}
