import { useState, type JSX } from "react";
import type { NodeId, PortId, SourceId } from "@graphlambda/core";
import { sessionMachine, type DebugSession } from "./debug-session.js";
import { binderNames, describeSource, describeValue } from "./machine-view.js";

export interface DebugWatch { readonly port: PortId; readonly name: string }

export function DebuggerTools({ session, breakpoints, onToggleBreakpoint, watches, onWatchesChange, onNavigate, onClose }: {
  readonly session: DebugSession; readonly breakpoints: ReadonlySet<NodeId>;
  readonly onToggleBreakpoint: (node: NodeId) => void;
  readonly watches: readonly DebugWatch[]; readonly onWatchesChange: (watches: readonly DebugWatch[]) => void;
  readonly onNavigate: ((source: SourceId) => void) | undefined;
  readonly onClose: () => void;
}): JSX.Element {
  const [port, setPort] = useState("");
  const [name, setName] = useState("");
  const machine = sessionMachine(session);
  return <aside className="gl-debugger-tools" aria-label="Breakpoints and watches">
    <div className="gl-debugger-tools-heading"><h2>Breakpoints and watches</h2>
      <button type="button" className="gl-button" aria-label="Close breakpoints and watches" onClick={onClose}>×</button>
    </div>
    <div className="gl-debugger-tools-grid">
      <section aria-label="Breakpoints"><h3>Pause before a node runs</h3>
        <select className="gl-input" aria-label="Add breakpoint" value="" onChange={(event) => {
          const node = session.graph.nodes.find((entry) => entry.id === event.currentTarget.value);
          if (node && !breakpoints.has(node.id)) onToggleBreakpoint(node.id);
        }}><option value="">Choose a node…</option>{session.graph.nodes.map((node, index) =>
          <option key={node.id} value={node.id}>{describeSource(session.graph, node.id)} · {index + 1}</option>)}</select>
        {[...breakpoints].map((id) => <label key={id}><input type="checkbox" checked onChange={() => onToggleBreakpoint(id)} />{describeSource(session.graph, id)}</label>)}
      </section>
      <section aria-label="Watches"><h3>Watch a named value</h3>
        <form onSubmit={(event) => { event.preventDefault();
          const source = session.graph.ports.find((entry) => entry.id === port);
          if (source && !watches.some((watch) => watch.port === source.id)) {
            onWatchesChange([...watches, { port: source.id, name: name.trim() || describeSource(session.graph, source.id) }]); setName("");
          }
        }}>
          <select className="gl-input" aria-label="Watch port" value={port} onChange={(event) => setPort(event.currentTarget.value)}>
            <option value="">Choose a port…</option>{session.graph.ports.map((entry, index) => <option key={entry.id} value={entry.id}>{describeSource(session.graph, entry.id)} · {index + 1}</option>)}
          </select>
          <input className="gl-input" aria-label="Watch label" placeholder="Name this watch" value={name} onChange={(event) => setName(event.currentTarget.value)} />
          <button className="gl-button" type="submit" disabled={port === "" || watches.some((watch) => watch.port === port)}>Add watch</button>
        </form>
        <ul>{watches.map((watch) => {
          const watchedPort = session.graph.ports.find((entry) => entry.id === watch.port);
          const source = watchedPort?.direction === "input"
            ? session.graph.edges.find((entry) => entry.target === watch.port)?.source : watch.port;
          const declaration = session.graph.nodes.find((node) => node.kind === "Lambda" ? node.parameter.parameterPort === source
            : node.kind === "LetRec" && node.recursive.valuePort === source);
          const binder = declaration?.kind === "Lambda" ? declaration.parameter.id
            : declaration?.kind === "LetRec" ? declaration.recursive.id : undefined;
          const value = machine?.sigma.find((entry) => entry.port === source)?.value
            ?? machine?.rho.find((entry) => entry.binder === binder)?.value;
          return <li key={watch.port}>
            <input className="gl-input" aria-label={`Rename watch ${watch.name}`} value={watch.name}
              onChange={(event) => onWatchesChange(watches.map((entry) => entry.port === watch.port ? { ...entry, name: event.currentTarget.value } : entry))} />
            <output aria-label={`Watch ${watch.name}`} className="gl-mono">{value === undefined ? "Not written in the current state" : describeValue(value, binderNames(session.graph))}</output>
            <button className="gl-button" type="button" onClick={() => onNavigate?.(watch.port)}>Reveal source</button>
            <button className="gl-button" type="button" aria-label={`Remove watch ${watch.name}`} onClick={() => onWatchesChange(watches.filter((entry) => entry.port !== watch.port))}>Remove</button>
          </li>;
        })}</ul>
      </section>
    </div>
  </aside>;
}
