import { identityText } from "../graph/index.js";
import { canonicalText } from "./canonical-text.js";
/**
 * The canonical form of a persistent source graph.
 *
 * Two properties make this the basis of the SAVAM source-stability obligation:
 *
 * - It is *deterministic*: the same graph always produces the same text, so a
 *   snapshot taken before a run can be compared against one taken after.
 * - It is *order-independent*: `G.nodes`, `G.ports`, `G.edges`, and `G.regions`
 *   are sorted by identity, so a graph that merely stores its elements in a
 *   different array order has the same canonical form. Array order is a storage
 *   detail, not source content, and stability must not depend on it.
 *
 * `deserializeGraph` is the inverse at the persistence boundary. It accepts
 * only this exact canonical representation and validates graph invariants.
 */
export const CANONICAL_GRAPH_FORMAT = 1;
/**
 * Fields excluded from the canonical form because they are non-semantic caches
 * rather than source content.
 *
 * The list is empty, so source stability is exact equality. The one
 * non-semantic overlay in this codebase — the λG correspondence metadata
 * returned by `getTermGraphMetadata` — is held in an external `WeakMap` keyed
 * by the graph, so it is not part of the graph value and needs no exclusion.
 * Anything added here must first be shown unobservable to `WF(G)`, to typing,
 * and to `->_G`.
 */
export const NON_SEMANTIC_GRAPH_FIELDS = Object.freeze([]);
function canonicalType(type) {
    switch (type.kind) {
        case "Int":
        case "Bool":
            return { kind: type.kind };
        case "Arrow":
            return {
                kind: "Arrow",
                parameter: canonicalType(type.parameter),
                result: canonicalType(type.result)
            };
    }
}
function canonicalNode(node) {
    const base = {
        kind: node.kind,
        id: identityText(node.id),
        region: identityText(node.region)
    };
    switch (node.kind) {
        case "IntLiteral":
        case "BoolLiteral":
            return { ...base, value: node.value };
        case "Lambda":
            return {
                ...base,
                parameter: {
                    id: identityText(node.parameter.id),
                    displayName: node.parameter.displayName,
                    parameterPort: identityText(node.parameter.parameterPort)
                }
            };
        case "LetRec":
            return {
                ...base,
                definition: identityText(node.definition),
                recursive: {
                    id: identityText(node.recursive.id),
                    displayName: node.recursive.displayName,
                    valuePort: identityText(node.recursive.valuePort)
                }
            };
        default:
            return base;
    }
}
function canonicalPort(port) {
    return {
        kind: "Port",
        id: identityText(port.id),
        owner: identityText(port.owner),
        direction: port.direction,
        role: port.role,
        // Always present, so an absent annotation is encoded rather than omitted.
        staticType: port.staticType === undefined ? null : canonicalType(port.staticType)
    };
}
function canonicalEdge(edge) {
    const base = {
        kind: edge.kind,
        id: identityText(edge.id),
        source: identityText(edge.source),
        target: identityText(edge.target)
    };
    // A binder use additionally names the lexical binding it resolves to. That
    // BinderId is source content even though it is not a SourceId anchor.
    return edge.kind === "BinderUse"
        ? { ...base, binder: identityText(edge.binder) }
        : base;
}
function canonicalRegion(region) {
    return {
        kind: "Region",
        id: identityText(region.id),
        role: region.role,
        parent: region.parent === null ? null : identityText(region.parent),
        owner: region.owner === null ? null : identityText(region.owner)
    };
}
/** Orders canonical records by their identity text, never by storage order. */
function sortedById(records) {
    return Object.freeze([...records].sort((left, right) => {
        const leftId = left["id"];
        const rightId = right["id"];
        if (leftId === rightId)
            return 0;
        return leftId < rightId ? -1 : 1;
    }));
}
/** Projects `G` onto its canonical form without reading anything else. */
export function canonicalizeGraph(graph) {
    return Object.freeze({
        kind: "CanonicalGraph",
        format: CANONICAL_GRAPH_FORMAT,
        rootRegion: identityText(graph.rootRegion),
        nodes: sortedById(graph.nodes.map(canonicalNode)),
        ports: sortedById(graph.ports.map(canonicalPort)),
        edges: sortedById(graph.edges.map(canonicalEdge)),
        regions: sortedById(graph.regions.map(canonicalRegion))
    });
}
/**
 * The deterministic, order-independent serialization of `G`.
 *
 * Equality of two such strings is the source-stability judgment: if execution
 * changed any node, port, edge, region, or the root, the strings differ.
 */
export function serializeGraph(graph) {
    return canonicalText(canonicalizeGraph(graph));
}
/** Whether two graphs have the same source content, ignoring storage order. */
export function graphsAreCanonicallyEqual(left, right) {
    return serializeGraph(left) === serializeGraph(right);
}
