import { useEffect, useRef, useState, type JSX } from "react";
import { arrowType, intType, prettyType, type Type } from "@graphlambda/core";
import { TypePicker } from "../components/TypePicker.js";

export function RecursiveFunctionDialog({ onClose, onCreate }: {
  readonly onClose: () => void; readonly onCreate: (name: string, type: Type) => void;
}): JSX.Element {
  const dialog = useRef<HTMLDialogElement>(null);
  const [step, setStep] = useState(0);
  const [name, setName] = useState("recur");
  const [type, setType] = useState<Type>(() => arrowType(intType(), intType()));
  useEffect(() => { const previous = document.activeElement; dialog.current?.showModal();
    dialog.current?.querySelector<HTMLInputElement>("input")?.focus();
    return () => { if (previous instanceof HTMLElement || previous instanceof SVGElement) previous.focus(); }; }, []);
  return <dialog ref={dialog} className="gl-node-picker" aria-label="Create recursive function" onCancel={(event) => { event.preventDefault(); onClose(); }}>
    <div className="gl-picker-heading"><h2>Create recursive function</h2><button className="gl-button" onClick={onClose}>Cancel</button></div>
    <p>Step {step + 1} of 3 · {step === 0 ? "Name" : step === 1 ? "Signature" : "Definition"}</p>
    {step === 0 ? <label>Function name<input className="gl-input" autoFocus value={name} onChange={(event) => setName(event.currentTarget.value)} /></label>
      : step === 1 ? <TypePicker label="Recursive function type" value={type} choices={[{ id: "Int -> Int", type: arrowType(intType(), intType()) }]} arrowsOnly onChange={setType} />
      : <p>A definition body for <strong>{name} : {prettyType(type)}</strong> will open. Its parameter and recursive binding will be listed under Variables in scope.</p>}
    <div className="gl-dialog-actions">{step > 0 ? <button className="gl-button" onClick={() => setStep(step - 1)}>Back</button> : null}
      {step < 2 ? <button className="gl-button" disabled={name.trim().length === 0} onClick={() => setStep(step + 1)}>Next</button>
        : <button className="gl-button" onClick={() => onCreate(name.trim(), type)}>Create and edit body</button>}</div>
  </dialog>;
}
