import type { SavamRuleLabel } from "@graphlambda/core";
import { sessionObservation, sessionRule, type DebugSession } from "./debug-session.js";
import { describeSource } from "./machine-view.js";

/** Wording for observed rules; this table cannot select or take a transition. */
const RULE_TEXT: Readonly<Record<SavamRuleLabel, string>> = {
  FIRE_INT_LITERAL: "Integer value produced", FIRE_BOOL_LITERAL: "Boolean value produced",
  FIRE_ADD: "Addition completed", FIRE_SUB: "Subtraction completed", FIRE_MUL: "Multiplication completed", FIRE_LESS: "Comparison completed",
  FIRE_IF_TRUE: "Then branch selected", FIRE_IF_FALSE: "Else branch selected", FIRE_OUTPUT: "Program result produced",
  FIRE_LAMBDA: "Function value created", FIRE_APPLY: "Function call prepared", ENTER_LAMBDA_REGION: "Function body entered",
  RETURN_APPLY: "Function call returned", ENTER_IF_BRANCH: "Selected branch entered", RETURN_IF: "Selected branch returned",
  FIRE_LETREC: "Recursive scope prepared", ENTER_LETREC_SCOPE: "Recursive scope entered", RETURN_LETREC: "Recursive scope returned"
};

export function completedStepSummary(session: DebugSession): string {
  const rule = sessionRule(session);
  const focus = sessionObservation(session)?.focus;
  return rule === undefined ? "No transition yet."
    : `${RULE_TEXT[rule]}${focus === undefined ? "" : ` · ${describeSource(session.graph, focus)}`}`;
}
