import {
  getLambdaBodyRegion,
  getNode,
  getPort,
  getRegionCaptures,
  portsOfNode,
  prettyOpenInputExpectedType,
  typeGraph,
  validateGraph,
  type Graph,
  type GraphIdentity,
  type GraphNode,
  type EdgeId,
  type NodeId,
  type PortId,
  type RegionCapture
} from "@graphlambda/core";

/**
 * The read-only facts the inspector shows about a graph.
 *
 * Every one of them is computed by the core: well-formedness by
 * `validateGraph`, types by `typeGraph`. The editor reports what the core
 * decided and adds no judgement of its own.
 */
export interface GraphReport {
  readonly nodes: number;
  readonly ports: number;
  readonly edges: number;
  readonly regions: number;
  /** Variable occurrences, i.e. edges that name a binder. */
  readonly binderUses: number;
  readonly wellFormed: boolean;
  readonly typeChecked: boolean;
  /** Input ports with no incoming edge. */
  readonly openInputs: number;
  readonly diagnostics: readonly ReportDiagnostic[];
}

export interface LambdaBoundaryReport {
  readonly parameter: string;
  readonly bodyResult: string;
  readonly functionType: string;
  readonly captures: readonly (RegionCapture & { readonly typeText: string })[];
}

export type ApplicationPortRole = "function" | "argument" | "result";

export interface ApplicationConnectionReport {
  readonly role: ApplicationPortRole;
  readonly direction: "incoming" | "outgoing";
  /** Human-readable source/consumer labels. Source IDs remain debug details. */
  readonly peers: readonly string[];
}

export interface ApplicationReport {
  readonly functionType: string;
  readonly argumentType: string;
  readonly resultType: string;
  readonly connections: readonly ApplicationConnectionReport[];
}

export interface WireReport {
  readonly source: string;
  readonly target: string;
  readonly typeText: string;
  readonly status: "Connected";
}

/** Formats core source/type/capture facts; it performs no scope analysis. */
export function lambdaBoundaryReport(graph: Graph, id: NodeId | null): LambdaBoundaryReport | null {
  if (id === null) return null;
  const node = getNode(graph, id);
  const body = getLambdaBodyRegion(graph, id);
  if (node?.kind !== "Lambda" || body === undefined) return null;
  const typing = typeGraph(graph);
  const types = typing.ok ? typing.typedGraph.portTypes : typing.partialPortTypes;
  const holes = typing.ok ? typing.typedGraph.openInputs : typing.partialOpenInputs;
  const typeText = (port: PortId | undefined): string => {
    const type = types.find((entry) => entry.port === port)?.type ?? holes.find((hole) => hole.port === port)?.expected;
    return type === undefined ? "?" : prettyOpenInputExpectedType(type);
  };
  const ports = portsOfNode(graph, id);
  return Object.freeze({
    parameter: `${node.parameter.displayName} : ${typeText(node.parameter.parameterPort)}`,
    bodyResult: typeText(ports.find((port) => port.role === "body")?.id),
    functionType: typeText(ports.find((port) => port.role === "out")?.id),
    captures: Object.freeze(getRegionCaptures(graph, body.id).map((capture) =>
      Object.freeze({ ...capture, typeText: typeText(capture.source) })))
  });
}

/**
 * Formats one Apply node from core graph/type facts. This is a property view,
 * not a type judgement: all three type strings come from `typeGraph`, and all
 * connection descriptions follow the source graph's existing PortIds/edges.
 */
export function applicationReport(graph: Graph, id: NodeId | null): ApplicationReport | null {
  if (id === null) return null;
  const node = getNode(graph, id);
  if (node?.kind !== "Apply") return null;
  const ports = portsOfNode(graph, id);
  const typeText = portTypeText(graph);
  const roles: readonly ApplicationPortRole[] = ["function", "argument", "result"];
  const connection = (role: ApplicationPortRole): ApplicationConnectionReport => {
    const port = ports.find((candidate) => candidate.role === role);
    const direction = role === "result" ? "outgoing" as const : "incoming" as const;
    const edges = graph.edges.filter((edge) => port !== undefined &&
      (direction === "incoming" ? edge.target === port.id : edge.source === port.id));
    const peers = edges.map((edge) => getPort(graph,
      direction === "incoming" ? edge.source : edge.target))
      .map((peer) => peer === undefined ? undefined : getNode(graph, peer.owner))
      .filter((peer): peer is GraphNode => peer !== undefined)
      .map(graphNodeLabel);
    return Object.freeze({ role, direction, peers: Object.freeze(peers) });
  };
  return Object.freeze({
    functionType: typeText(ports.find((port) => port.role === "function")?.id),
    argumentType: typeText(ports.find((port) => port.role === "argument")?.id),
    resultType: typeText(ports.find((port) => port.role === "result")?.id),
    connections: Object.freeze(roles.map(connection))
  });
}

/** Human-facing endpoint facts for a selected semantic edge. */
export function wireReport(graph: Graph, id: EdgeId | null): WireReport | null {
  if (id === null) return null;
  const edge = graph.edges.find((candidate) => candidate.id === id);
  if (edge === undefined) return null;
  const source = getPort(graph, edge.source);
  const target = getPort(graph, edge.target);
  if (source === undefined || target === undefined) return null;
  const sourceNode = getNode(graph, source.owner);
  const targetNode = getNode(graph, target.owner);
  if (sourceNode === undefined || targetNode === undefined) return null;
  return Object.freeze({
    source: `${graphNodeLabel(sourceNode)} · ${source.role}`,
    target: `${graphNodeLabel(targetNode)} · ${target.role}`,
    typeText: portTypeText(graph)(source.id),
    status: "Connected"
  });
}

function portTypeText(graph: Graph): (port: PortId | undefined) => string {
  const typing = typeGraph(graph);
  const types = typing.ok ? typing.typedGraph.portTypes : typing.partialPortTypes;
  const holes = typing.ok ? typing.typedGraph.openInputs : typing.partialOpenInputs;
  return (port) => {
    const type = types.find((entry) => entry.port === port)?.type ??
      holes.find((hole) => hole.port === port)?.expected;
    return type === undefined ? "?" : prettyOpenInputExpectedType(type);
  };
}

/** Human-facing endpoint text; stable IDs remain available in advanced details. */
function graphNodeLabel(node: GraphNode): string {
  switch (node.kind) {
    case "IntLiteral": return `Int ${node.value}`;
    case "BoolLiteral": return `Bool ${node.value}`;
    case "Lambda": return `Lambda \\${node.parameter.displayName}`;
    case "LetRec": return `LetRec ${node.recursive.displayName}`;
    case "Apply": return "Application";
    case "Output": return "Output";
    default: return node.kind;
  }
}

export interface ReportDiagnostic {
  readonly source: "well-formedness" | "typing";
  readonly code: string;
  readonly subject: GraphIdentity;
  readonly message: string;
}

/** Summarises one graph for the inspector panel. */
export function graphReport(graph: Graph): GraphReport {
  const wellFormedness = validateGraph(graph);
  const typing = typeGraph(graph);

  const diagnostics: ReportDiagnostic[] = [
    ...wellFormedness.map((diagnostic) => ({
      source: "well-formedness" as const,
      code: diagnostic.code,
      subject: diagnostic.subject,
      message: diagnostic.message
    })),
    ...typing.diagnostics.map((diagnostic) => ({
      source: "typing" as const,
      code: diagnostic.code,
      subject: diagnostic.subject,
      message: diagnostic.message
    }))
  ];

  const openInputs = typing.ok
    ? typing.typedGraph.openInputs.length
    : typing.partialOpenInputs.length;

  return Object.freeze({
    nodes: graph.nodes.length,
    ports: graph.ports.length,
    edges: graph.edges.length,
    regions: graph.regions.length,
    binderUses: graph.edges.filter((edge) => edge.kind === "BinderUse").length,
    wellFormed: wellFormedness.length === 0,
    typeChecked: typing.ok,
    openInputs,
    diagnostics: Object.freeze(diagnostics)
  });
}
