import { identityText } from "./identities.js";
import { assertGraphInvariants, GraphInvariantError } from "./invariants.js";
import { immutableEdge, immutablePort, immutableRegion } from "./model.js";
import { immutableGraphNode } from "./node-algebra.js";
import { getEdge, getNode, getPort, getRegion } from "./queries.js";
function frozenArray(values) {
    return Object.freeze(Array.from(values));
}
function snapshot(graph, changes) {
    const next = Object.freeze({
        kind: "Graph",
        rootRegion: graph.rootRegion,
        nodes: changes.nodes ?? graph.nodes,
        ports: changes.ports ?? graph.ports,
        edges: changes.edges ?? graph.edges,
        regions: changes.regions ?? graph.regions
    });
    assertGraphInvariants(next);
    return next;
}
function missing(kind, id) {
    return new GraphInvariantError(`${kind} ${identityText(id)} does not exist.`);
}
function duplicate(kind, id) {
    return new GraphInvariantError(`${kind} ${identityText(id)} already exists.`);
}
function replaceAt(values, replacement) {
    const id = identityText(replacement.id);
    const index = values.findIndex((value) => identityText(value.id) === id);
    if (index < 0) {
        throw missing(replacement.kind, replacement.id);
    }
    const next = [...values];
    next[index] = replacement;
    return frozenArray(next);
}
function removeFrom(values, id, kind) {
    const target = identityText(id);
    const index = values.findIndex((value) => identityText(value.id) === target);
    if (index < 0) {
        throw missing(kind, id);
    }
    return frozenArray([
        ...values.slice(0, index),
        ...values.slice(index + 1)
    ]);
}
/** Creates an empty graph with one graph-owned root region. */
export function createGraph(rootRegion) {
    if (rootRegion.parent !== null || rootRegion.owner !== null) {
        throw new GraphInvariantError("The initial region must be a root region.");
    }
    const root = immutableRegion(rootRegion);
    const graph = Object.freeze({
        kind: "Graph",
        rootRegion: root.id,
        nodes: frozenArray([]),
        ports: frozenArray([]),
        edges: frozenArray([]),
        regions: frozenArray([root])
    });
    assertGraphInvariants(graph);
    return graph;
}
export function addNode(graph, node) {
    if (getNode(graph, node.id) !== undefined) {
        throw duplicate("Node", node.id);
    }
    return snapshot(graph, {
        nodes: frozenArray([...graph.nodes, immutableGraphNode(node)])
    });
}
export function removeNode(graph, id) {
    return snapshot(graph, { nodes: removeFrom(graph.nodes, id, "Node") });
}
/** Replaces a node's data while preserving its NodeId. */
export function replaceNode(graph, node) {
    if (getNode(graph, node.id) === undefined) {
        throw missing("Node", node.id);
    }
    return snapshot(graph, {
        nodes: replaceAt(graph.nodes, immutableGraphNode(node))
    });
}
export function addPort(graph, port) {
    if (getPort(graph, port.id) !== undefined) {
        throw duplicate("Port", port.id);
    }
    return snapshot(graph, {
        ports: frozenArray([...graph.ports, immutablePort(port)])
    });
}
export function removePort(graph, id) {
    return snapshot(graph, { ports: removeFrom(graph.ports, id, "Port") });
}
/** Replaces a port's data while preserving its PortId. */
export function replacePort(graph, port) {
    if (getPort(graph, port.id) === undefined) {
        throw missing("Port", port.id);
    }
    return snapshot(graph, {
        ports: replaceAt(graph.ports, immutablePort(port))
    });
}
export function addEdge(graph, edge) {
    if (getEdge(graph, edge.id) !== undefined) {
        throw duplicate("Edge", edge.id);
    }
    return snapshot(graph, {
        edges: frozenArray([...graph.edges, immutableEdge(edge)])
    });
}
/** Adds a variable occurrence while retaining it in the graph's edge set. */
export function addBinderUse(graph, use) {
    return addEdge(graph, use);
}
export function removeEdge(graph, id) {
    return snapshot(graph, { edges: removeFrom(graph.edges, id, "Edge") });
}
export function removeBinderUse(graph, id) {
    const edge = getEdge(graph, id);
    if (edge?.kind !== "BinderUse") {
        throw missing("BinderUse", id);
    }
    return removeEdge(graph, id);
}
/** Replaces an edge's endpoints while preserving its EdgeId. */
export function replaceEdge(graph, edge) {
    if (getEdge(graph, edge.id) === undefined) {
        throw missing("Edge", edge.id);
    }
    return snapshot(graph, {
        edges: replaceAt(graph.edges, immutableEdge(edge))
    });
}
/** Replaces a binder use while preserving its EdgeId. */
export function replaceBinderUse(graph, use) {
    const edge = getEdge(graph, use.id);
    if (edge?.kind !== "BinderUse") {
        throw missing("BinderUse", use.id);
    }
    return replaceEdge(graph, use);
}
export function addRegion(graph, region) {
    if (getRegion(graph, region.id) !== undefined) {
        throw duplicate("Region", region.id);
    }
    if (region.parent === null) {
        throw new GraphInvariantError("A graph cannot have a second root region.");
    }
    return snapshot(graph, {
        regions: frozenArray([...graph.regions, immutableRegion(region)])
    });
}
export function removeRegion(graph, id) {
    if (id === graph.rootRegion) {
        throw new GraphInvariantError("The root region cannot be removed.");
    }
    return snapshot(graph, {
        regions: removeFrom(graph.regions, id, "Region")
    });
}
/** Replaces region metadata or ownership while preserving its RegionId. */
export function replaceRegion(graph, region) {
    if (getRegion(graph, region.id) === undefined) {
        throw missing("Region", region.id);
    }
    if (region.id === graph.rootRegion && region.parent !== null) {
        throw new GraphInvariantError("The root region cannot become nested.");
    }
    if (region.id !== graph.rootRegion && region.parent === null) {
        throw new GraphInvariantError("A nested region cannot become another root.");
    }
    return snapshot(graph, {
        regions: replaceAt(graph.regions, immutableRegion(region))
    });
}
