import { immutableBinderUse } from "./binding-model.js";
export { createGraphNode, immutableGraphNode, NODE_KINDS } from "./node-algebra.js";
export { createBinderDeclaration, createBinderUse, createRecursiveBinderDeclaration, renameRecursiveBinderDisplayName, renameBinderDisplayName } from "./binding-model.js";
function requireRole(role, entity) {
    if (role.trim().length === 0) {
        throw new RangeError(`${entity} role must not be empty.`);
    }
    return role;
}
export function createPort(spec) {
    const base = {
        kind: "Port",
        id: spec.id,
        owner: spec.owner,
        direction: spec.direction,
        role: requireRole(spec.role, "Port")
    };
    return spec.staticType === undefined
        ? Object.freeze(base)
        : Object.freeze({ ...base, staticType: spec.staticType });
}
export function createEdge(spec) {
    return Object.freeze({
        kind: "Edge",
        id: spec.id,
        source: spec.source,
        target: spec.target
    });
}
export function createRootRegion(spec) {
    return Object.freeze({
        kind: "Region",
        id: spec.id,
        role: requireRole(spec.role ?? "root", "Root region"),
        parent: null,
        owner: null
    });
}
export function createNestedRegion(spec) {
    return Object.freeze({
        kind: "Region",
        id: spec.id,
        role: requireRole(spec.role, "Nested region"),
        parent: spec.parent,
        owner: spec.owner
    });
}
export function immutablePort(port) {
    return createPort(port);
}
export function immutableEdge(edge) {
    return edge.kind === "BinderUse" ? immutableBinderUse(edge) : createEdge(edge);
}
export function immutableRegion(region) {
    return region.parent === null
        ? createRootRegion({ id: region.id, role: region.role })
        : createNestedRegion({
            id: region.id,
            role: region.role,
            parent: region.parent,
            owner: region.owner
        });
}
