import type { GraphNode, NodePortRole } from "@graphlambda/core";
import type { FlowchartShapeKind } from "./FlowchartShape.js";

/**
 * The text a node shows.
 *
 * Construct nodes use semantic names rather than snippets of textual source.
 * Literal values remain program data. Nothing here is source: the projection
 * reads a node and produces strings, and never writes back.
 */
export interface NodePresentation {
  readonly shape: FlowchartShapeKind;
  /** The value, operator, or construct identity at the centre of the symbol. */
  readonly primaryText: string;
  /** A compact kind/type line which supplements the silhouette. */
  readonly secondaryText: string | undefined;
}

/** The strings one node contributes to the projection. */
export function nodePresentation(
  node: GraphNode,
  typeText = "?"
): NodePresentation {
  switch (node.kind) {
    case "IntLiteral":
      return Object.freeze({
        shape: "data",
        primaryText: String(node.value),
        secondaryText: typeText
      });
    case "BoolLiteral":
      return Object.freeze({
        shape: "data",
        primaryText: node.value ? "true" : "false",
        secondaryText: typeText
      });
    case "Lambda":
      return Object.freeze({
        shape: "preparation",
        primaryText: `λ ${node.parameter.displayName} : ${typeText}`,
        secondaryText: "Function"
      });
    case "LetRec":
      return Object.freeze({
        shape: "preparation",
        primaryText: "LetRec",
        secondaryText: "Recursion"
      });
    case "Add":
      return process("+", "Add");
    case "Sub":
      return process("−", "Sub");
    case "Mul":
      return process("×", "Mul");
    case "Less":
      return process("<", "Less");
    case "Apply":
      return process("f()", "Application");
    case "If":
      return Object.freeze({
        shape: "decision",
        primaryText: "If",
        secondaryText: undefined
      });
    case "Output":
      return Object.freeze({
        shape: "terminator",
        primaryText: "Out",
        secondaryText: undefined
      });
  }
}

function process(primaryText: string, secondaryText: string): NodePresentation {
  return Object.freeze({ shape: "process", primaryText, secondaryText });
}

const ROLE_LABELS: Readonly<Record<NodePortRole, string>> = Object.freeze({
  left: "left",
  right: "right",
  out: "output",
  body: "body",
  function: "function",
  argument: "argument",
  result: "result",
  condition: "condition",
  then: "then",
  else: "else",
  parameter: "parameter",
  definition: "definition",
  recursive: "recursive",
  value: "value"
});

/** The compact label shown beside a port socket. */
export function portRoleLabel(role: NodePortRole): string {
  return ROLE_LABELS[role];
}

const REGION_ROLE_LABELS: Readonly<Record<string, string>> = Object.freeze({
  root: "root",
  "lambda-body": "BODY",
  "letrec-scope": "LETREC SCOPE",
  "if-then": "THEN",
  "if-else": "ELSE"
});

/** The label shown on a region frame. Unknown roles are shown verbatim. */
export function regionRoleLabel(role: string): string {
  return REGION_ROLE_LABELS[role] ?? role;
}
