import { identityText } from "../graph/index.js";
import { observationReference } from "./provenance.js";
/**
 * Constructs an immutable effect, or `undefined` when the transition produced
 * nothing a renderer must redraw.
 */
export function visualEffect(spec) {
    const writtenPorts = Object.freeze([...(spec.writtenPorts ?? [])]);
    const clearedPorts = Object.freeze([...(spec.clearedPorts ?? [])]);
    const enteredRegion = spec.enteredRegion;
    const pushedFrameSite = spec.pushedFrameSite;
    const poppedFrameSite = spec.poppedFrameSite;
    const terminated = spec.terminated === true;
    const empty = writtenPorts.length === 0 &&
        clearedPorts.length === 0 &&
        enteredRegion === undefined &&
        pushedFrameSite === undefined &&
        poppedFrameSite === undefined &&
        !terminated;
    if (empty)
        return undefined;
    return Object.freeze({
        kind: "VisualEffect",
        writtenPorts,
        clearedPorts,
        enteredRegion,
        pushedFrameSite,
        poppedFrameSite,
        terminated
    });
}
/** Constructs an immutable observation. */
export function observation(focus, rule, effect) {
    return Object.freeze({ kind: "Observation", focus, rule, effect });
}
/**
 * The observation of a configuration that has not stepped yet: no focus, no
 * rule, no effect. Nothing has been observed because nothing has happened.
 */
export function initialObservation() {
    return observation(undefined, undefined, undefined);
}
/** Every source identity an effect mentions. */
export function effectSourceReferences(effect) {
    if (effect === undefined)
        return Object.freeze([]);
    const references = [
        ...effect.writtenPorts,
        ...effect.clearedPorts
    ];
    if (effect.enteredRegion !== undefined)
        references.push(effect.enteredRegion);
    if (effect.pushedFrameSite !== undefined) {
        references.push(effect.pushedFrameSite);
    }
    if (effect.poppedFrameSite !== undefined) {
        references.push(effect.poppedFrameSite);
    }
    return Object.freeze(references);
}
/** Every source identity an observation mentions, focus included. */
export function observationSourceReferences(subject) {
    const references = effectSourceReferences(subject.effect);
    return subject.focus === undefined
        ? references
        : Object.freeze([subject.focus, ...references]);
}
/**
 * Every source identity an observation mentions, paired with the position that
 * holds it and the identity domain a renderer expects to find there.
 *
 * This is what the derived-provenance obligation validates: an observation is
 * the only part of a configuration a renderer reads directly, so each field
 * must denote the kind of source entity that field is drawn from.
 */
export function observationProvenanceReferences(subject) {
    const references = [];
    if (subject.focus !== undefined) {
        // F is the element the transition acted at: a fired node or an entered
        // region. No transition is focused at a port or an edge.
        references.push(observationReference("omega.F", subject.focus, "node", "region"));
    }
    const effect = subject.effect;
    if (effect === undefined)
        return Object.freeze(references);
    effect.writtenPorts.forEach((port, index) => {
        references.push(observationReference(`omega.Delta.writtenPorts[${index}]`, port, "port"));
    });
    effect.clearedPorts.forEach((port, index) => {
        references.push(observationReference(`omega.Delta.clearedPorts[${index}]`, port, "port"));
    });
    if (effect.enteredRegion !== undefined) {
        references.push(observationReference("omega.Delta.enteredRegion", effect.enteredRegion, "region"));
    }
    if (effect.pushedFrameSite !== undefined) {
        references.push(observationReference("omega.Delta.pushedFrameSite", effect.pushedFrameSite, "node"));
    }
    if (effect.poppedFrameSite !== undefined) {
        references.push(observationReference("omega.Delta.poppedFrameSite", effect.poppedFrameSite, "node"));
    }
    return Object.freeze(references);
}
/** Renders an observation for diagnostics. */
export function describeObservation(subject) {
    const focus = subject.focus === undefined ? "_" : identityText(subject.focus);
    const rule = subject.rule ?? "_";
    const effect = subject.effect;
    if (effect === undefined)
        return `<${focus}, ${rule}, _>`;
    const parts = [];
    if (effect.writtenPorts.length > 0) {
        parts.push(`write ${effect.writtenPorts.map(identityText).join(",")}`);
    }
    if (effect.clearedPorts.length > 0) {
        parts.push(`clear ${effect.clearedPorts.map(identityText).join(",")}`);
    }
    if (effect.enteredRegion !== undefined) {
        parts.push(`enter ${identityText(effect.enteredRegion)}`);
    }
    if (effect.pushedFrameSite !== undefined) {
        parts.push(`push ${identityText(effect.pushedFrameSite)}`);
    }
    if (effect.poppedFrameSite !== undefined) {
        parts.push(`pop ${identityText(effect.poppedFrameSite)}`);
    }
    if (effect.terminated)
        parts.push("done");
    return `<${focus}, ${rule}, ${parts.join("; ")}>`;
}
