import type { JSX } from "react";

import type { SceneRegion } from "../canvas/scene.js";
import {
  REGION_HEADER_HEIGHT,
  REGION_NAV_WIDTH,
  REGION_PADDING
} from "../canvas/metrics.js";

export interface RegionViewProps {
  readonly region: SceneRegion;
  readonly hideControls?: boolean;
  readonly controlScale?: number;
  /** True when the current transition is focused at this region. */
  readonly focused?: boolean;
  /** True when the current transition's effect entered this region. */
  readonly entered?: boolean;
  /** The exact source region selected in the provenance inspector. */
  readonly provenance?: boolean;
  readonly related?: boolean;
  /** Opens this exact region. Omitted for the region already used as view root. */
  readonly onEnter?: ((region: SceneRegion) => void) | undefined;
  /** Toggles only presentation; the semantic region and contents remain in G. */
  readonly onToggle?: ((region: SceneRegion) => void) | undefined;
}

/**
 * One region frame.
 *
 * Regions are the graph's hierarchy, not a decoration: a lambda body, a letrec
 * scope, and each branch of an `If` are frames drawn inside the node that owns
 * them. Nesting depth is shown by a flat step in the fill, never by a shadow.
 *
 * During a run a region can be the transition's focus, or the region a step's
 * effect entered. Both are drawn as a change of border, so the depth fill keeps
 * meaning nesting and nothing else.
 */
export function RegionView({
  region,
  hideControls = false,
  controlScale = 1,
  focused = false,
  entered = false,
  provenance = false,
  related = false,
  onEnter,
  onToggle
}: RegionViewProps): JSX.Element {
  const { box } = region;

  return (
    <g
      className={`gl-region gl-region--${region.role}${
        focused ? " gl-region--focus" : ""
      }${entered ? " gl-region--entered" : ""}${provenance ? " gl-region--provenance" : ""}`}
      data-region-id={region.id}
      data-related={related || undefined}
      data-provenance-anchor={provenance || undefined}
      data-owner-id={region.owner ?? undefined}
      data-role={region.role}
      data-depth={Math.min(region.depth, 4)}
      data-collapsed={region.collapsed}
    >
      <rect
        className="gl-region-frame"
        x={box.x}
        y={box.y}
        width={box.width}
        height={box.height}
      />
      {provenance ? (
        <path
          className="gl-provenance-corners"
          d={regionCornerMarker(box.x, box.y, box.width, box.height)}
        />
      ) : null}
      <line
        className="gl-region-rule"
        x1={box.x}
        y1={box.y + REGION_HEADER_HEIGHT}
        x2={box.x + box.width}
        y2={box.y + REGION_HEADER_HEIGHT}
      />
      <text
        className="gl-region-label"
        x={box.x + REGION_PADDING}
        y={box.y + REGION_HEADER_HEIGHT - 5}
      >
        {region.label}
      </text>
      {hideControls ? null : <RegionControls region={region} controlScale={controlScale} onEnter={onEnter} onToggle={onToggle} />}

    </g>
  );
}

/** Controls are painted above wires; their CSS-pixel size is independent of fit. */
export function RegionControls({ region, controlScale = 1, onEnter, onToggle }: RegionViewProps): JSX.Element {
  const { box } = region;
  return <g className="gl-region-controls" data-owner-id={region.owner ?? undefined} data-controls-region={region.id}>
      {onEnter === undefined ? null : (
        <g
          className="gl-region-enter"
          role="button"
          tabIndex={0}
          aria-label={`Enter ${navigationLabel(region.role)} region`}
          transform={`translate(${box.x + box.width - 2 * REGION_NAV_WIDTH * controlScale} ${box.y}) scale(${controlScale})`}
          onPointerDown={(event) => {
            event.stopPropagation();
          }}
          onClick={(event) => {
            event.stopPropagation();
            onEnter(region);
          }}
          onKeyDown={(event) => {
            if (event.key !== "Enter" && event.key !== " ") return;
            event.preventDefault();
            onEnter(region);
          }}
        >
          <rect width={REGION_NAV_WIDTH} height={32} />
          <text
            x={REGION_NAV_WIDTH / 2}
            y={21}
            textAnchor="middle"
          >
            Enter
          </text>
        </g>
      )}
      {onToggle === undefined ? null : (
        <g
          className="gl-region-toggle"
          role="button"
          tabIndex={0}
          aria-expanded={!region.collapsed}
          aria-label={`${region.collapsed ? "Expand" : "Collapse"} ${navigationLabel(region.role)} region`}
          transform={`translate(${box.x + box.width - REGION_NAV_WIDTH * controlScale} ${box.y}) scale(${controlScale})`}
          onPointerDown={(event) => {
            event.stopPropagation();
          }}
          onClick={(event) => {
            event.stopPropagation();
            onToggle(region);
          }}
          onKeyDown={(event) => {
            if (event.key !== "Enter" && event.key !== " ") return;
            event.preventDefault();
            onToggle(region);
          }}
        >
          <rect width={REGION_NAV_WIDTH} height={32} />
          <text x={REGION_NAV_WIDTH / 2} y={21} textAnchor="middle">
            {region.collapsed ? "Expand" : "Collapse"}
          </text>
        </g>
      )}
  </g>;
}

function regionCornerMarker(x: number, y: number, width: number, height: number): string {
  const right = x + width;
  const bottom = y + height;
  return [
    `M ${x + 12} ${y + 4} H ${x + 4} V ${y + 12}`,
    `M ${right - 12} ${y + 4} H ${right - 4} V ${y + 12}`,
    `M ${x + 4} ${bottom - 12} V ${bottom - 4} H ${x + 12}`,
    `M ${right - 4} ${bottom - 12} V ${bottom - 4} H ${right - 12}`
  ].join(" ");
}

function navigationLabel(role: string): string {
  switch (role) {
    case "lambda-body": return "Body";
    case "if-then": return "Then";
    case "if-else": return "Else";
    case "letrec-scope": return "Scope";
    default: return role;
  }
}
