import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type JSX,
  type ReactNode,
  type PointerEvent as ReactPointerEvent
} from "react";

import type { EdgeId, NodeId, PortId, RegionId, SourceId } from "@graphlambda/core";

import { NodeView } from "../nodes/NodeView.js";
import { VariableUseView } from "../nodes/VariableUseView.js";
import { PortTarget, PortView } from "../ports/PortView.js";
import { RegionControls, RegionView } from "../regions/RegionView.js";
import { CaptureBoundaryView } from "../regions/CaptureBoundaryView.js";
import { IfBranchView } from "../regions/IfBranchView.js";
import { WireView } from "../wires/WireView.js";
import { routedWireArrowhead } from "../wires/wire-appearance.js";
import {
  NO_OVERLAY,
  type Scene,
  type SceneNode,
  type SceneOverlay,
  type Point,
  type ScenePort,
  type SceneWire
} from "./scene.js";
import {
  fitViewport,
  panViewport,
  resolveViewport,
  viewportViewBox,
  zoomViewportAt,
  type Viewport
} from "./viewport.js";

export interface GraphCanvasProps {
  readonly scene: Scene;
  readonly onRequestNode?: ((point: Point) => void) | undefined;
  readonly selectedNode: NodeId | null;
  readonly breakpoints?: ReadonlySet<NodeId>;
  readonly selectedNodes?: ReadonlySet<NodeId>;
  readonly inlineEditor?: ReactNode;
  readonly onEditNode?: ((node: SceneNode) => void) | undefined;
  readonly selectedWire: EdgeId | null;
  /** The output port a connection is being drawn from, if any. */
  readonly pendingSource: PortId | null;
  readonly relatedSources?: ReadonlySet<string>;
  readonly connectionChecks?: ReadonlyMap<PortId, { readonly ok: boolean; readonly diagnostics: readonly { readonly message: string }[] } | undefined>;
  /** The presentation-only camera. Omit for a statically fitted projection. */
  readonly viewport?: Viewport;
  readonly onViewportChange?: (viewport: Viewport) => void;
  /**
   * What a run is painting over the scene. Defaults to nothing, so the canvas
   * is identical to the read-only projection when no run is in progress.
   */
  readonly overlay?: SceneOverlay;
  /** One core-provenance source, independent of user selection and focus. */
  readonly provenanceAnchor?: SourceId | null;
  readonly onSelectNode: (node: SceneNode | null, additive?: boolean) => void;
  readonly onSelectWire: (wire: SceneWire) => void;
  readonly onSelectPort: (port: ScenePort) => void;
  /** Commits a completed pointer drag as one core-owned connection edit. */
  readonly onConnect: (source: PortId, target: PortId) => void;
  /** Cancels a click or drag connection preview without touching history. */
  readonly onCancelConnection: () => void;
  readonly onEnterRegion: (region: RegionId) => void;
  readonly onToggleRegion?: ((region: RegionId) => void) | undefined;
  /** Called continuously while dragging, so the projection can follow. */
  readonly onDrag: (node: NodeId, dx: number, dy: number) => void;
  /** Called once when the drag ends, with the total displacement. */
  readonly onDragEnd: (node: NodeId, dx: number, dy: number) => void;
  /** Called when a node drag is cancelled; it must not commit a displacement. */
  readonly onDragCancel: (node: NodeId) => void;
}

interface DragState {
  readonly node: NodeId;
  readonly start: Point;
  dx: number;
  dy: number;
}

interface PanState {
  readonly startX: number;
  readonly startY: number;
  readonly unitsPerPixel: number;
  readonly viewport: Viewport;
}

interface ConnectionDragState {
  readonly pointerId: number;
  readonly source: ScenePort;
  readonly start: Point;
  readonly point: Point;
  readonly target: PortId | null;
  readonly moved: boolean;
}

/**
 * The SVG projection of one source graph, with structural editing attached.
 *
 * The canvas turns pointer input into intentions — select this, connect these
 * two ports, move this node, enter this region — and nothing else. It never
 * changes a graph; it reports what the user did and the reducer decides what
 * that means. Backgrounds and wires precede active hit targets, node bodies,
 * socket details, variable glyphs, and navigation controls.
 *
 * A run adds an overlay: the source element the current transition acted at,
 * the elements the machine state still references, the ports it just wrote or
 * cleared, and the runtime values themselves. All of it is read out of a SAVAM
 * configuration; none of it is stored in the scene, and none reaches the graph.
 */
export function GraphCanvas({
  scene,
  onRequestNode,
  selectedNode,
  selectedNodes,
  breakpoints,
  inlineEditor,
  onEditNode,
  selectedWire,
  pendingSource,
  connectionChecks,
  relatedSources,
  viewport: requestedViewport,
  onViewportChange,
  overlay = NO_OVERLAY,
  provenanceAnchor = null,
  onSelectNode,
  onSelectWire,
  onSelectPort,
  onConnect,
  onCancelConnection,
  onEnterRegion,
  onToggleRegion,
  onDrag,
  onDragEnd,
  onDragCancel
}: GraphCanvasProps): JSX.Element {
  const svgRef = useRef<SVGSVGElement | null>(null);
  const dragRef = useRef<DragState | null>(null);
  const panRef = useRef<PanState | null>(null);
  const connectionRef = useRef<ConnectionDragState | null>(null);
  const suppressPortClickRef = useRef(false);
  const [connectionDrag, setConnectionDrag] = useState<ConnectionDragState | null>(null);
  const [unitsPerCssPixel, setUnitsPerCssPixel] = useState(1);
  const [projectionScale, setProjectionScale] = useState(1);
  const viewport = requestedViewport ?? fitViewport(scene);
  const viewBox = viewportViewBox(viewport);
  const detailScale = projectionScale < 1 ? 1.02 / projectionScale : 1;

  useLayoutEffect(() => {
    const svg = svgRef.current;
    if (svg === null || onViewportChange === undefined) return;
    const measure = (): void => {
      const next = resolveViewport(viewport, svg.clientWidth, svg.clientHeight);
      if (next !== viewport) onViewportChange(next);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(svg);
    return () => observer.disconnect();
  }, [viewport, onViewportChange]);

  // A dense fitted graph may map several source units onto one CSS pixel.
  // Retain the authored screen size of interactive notation without changing
  // the semantic graph or the camera's structural overview.
  useLayoutEffect(() => {
    const svg = svgRef.current;
    if (svg === null) return undefined;

    const measure = (): void => {
      const matrix = svg.getScreenCTM();
      if (matrix === null) return;
      const next = Math.max(0.001, Math.min(Math.abs(matrix.a), Math.abs(matrix.d)));
      setProjectionScale((current) => Math.abs(current - next) < 0.001 ? current : next);
    };

    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(svg);
    return () => observer.disconnect();
  }, [viewBox.x, viewBox.y, viewBox.width, viewBox.height]);

  const pointAt = (clientX: number, clientY: number): Point => {
    const svg = svgRef.current;
    if (svg === null) return { x: clientX, y: clientY };

    const matrix = svg.getScreenCTM();
    if (matrix === null) return { x: clientX, y: clientY };

    const point = svg.createSVGPoint();
    point.x = clientX;
    point.y = clientY;
    const transformed = point.matrixTransform(matrix.inverse());
    return { x: transformed.x, y: transformed.y };
  };

  const unitsPerPixel = (): number => {
    const start = pointAt(0, 0);
    const end = pointAt(1, 0);
    const distance = Math.hypot(end.x - start.x, end.y - start.y);
    return distance === 0 ? 1 : distance;
  };

  const changeViewport = (next: Viewport): void => {
    onViewportChange?.(next);
  };

  const beginDrag = (node: SceneNode, event: ReactPointerEvent): void => {
    event.currentTarget.setPointerCapture(event.pointerId);
    dragRef.current = {
      node: node.id,
      start: pointAt(event.clientX, event.clientY),
      dx: 0,
      dy: 0
    };
  };

  const continueDrag = (event: ReactPointerEvent): void => {
    const drag = dragRef.current;
    if (drag === null) return;

    const point = pointAt(event.clientX, event.clientY);
    drag.dx = Math.round(point.x - drag.start.x);
    drag.dy = Math.round(point.y - drag.start.y);
    onDrag(drag.node, drag.dx, drag.dy);
  };

  const finishDrag = (event: ReactPointerEvent): void => {
    const drag = dragRef.current;
    if (drag === null) return;

    dragRef.current = null;
    event.currentTarget.releasePointerCapture(event.pointerId);
    onDragEnd(drag.node, drag.dx, drag.dy);
  };

  const cancelDrag = (event: ReactPointerEvent): void => {
    const drag = dragRef.current;
    if (drag === null) return;

    dragRef.current = null;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    onDragCancel(drag.node);
  };

  const portAt = (clientX: number, clientY: number): ScenePort | undefined => {
    const svg = svgRef.current;
    const matrix = svg?.getScreenCTM();
    if (svg === null || svg === undefined || matrix === null || matrix === undefined) {
      return undefined;
    }

    return scene.ports
      .map((port) => {
        const point = svg.createSVGPoint();
        point.x = port.x;
        point.y = port.y;
        const screen = point.matrixTransform(matrix);
        return { port, distance: Math.hypot(screen.x - clientX, screen.y - clientY) };
      })
      .filter((candidate) => candidate.distance <= 16)
      .sort((left, right) => left.distance - right.distance ||
        String(left.port.id).localeCompare(String(right.port.id)))[0]?.port;
  };

  const beginConnectionDrag = (
    source: ScenePort,
    event: ReactPointerEvent
  ): void => {
    const nearest = portAt(event.clientX, event.clientY);
    if (nearest?.direction === "input") return;
    source = nearest ?? source;
    const start = pointAt(event.clientX, event.clientY);
    event.currentTarget.setPointerCapture(event.pointerId);
    // A drag supersedes an incomplete click-to-connect gesture. Both are
    // presentation state, so cancelling it cannot create an undo entry.
    if (pendingSource !== null) onCancelConnection();
    const next: ConnectionDragState = {
      pointerId: event.pointerId,
      source,
      start,
      point: start,
      target: null,
      moved: false
    };
    connectionRef.current = next;
    setConnectionDrag(next);
  };

  const continueConnectionDrag = (event: ReactPointerEvent<SVGSVGElement>): void => {
    const current = connectionRef.current;
    if (current === null || current.pointerId !== event.pointerId) return;

    const point = pointAt(event.clientX, event.clientY);
    const moved =
      current.moved || Math.hypot(point.x - current.start.x, point.y - current.start.y) >= 4;
    const hovered = portAt(event.clientX, event.clientY);
    const target =
      moved && hovered?.direction === "input" && hovered.id !== current.source.id
        ? hovered.id
        : null;
    const next = { ...current, point, target, moved };
    connectionRef.current = next;
    setConnectionDrag(next);
  };

  const finishConnectionDrag = (event: ReactPointerEvent<SVGSVGElement>): void => {
    const current = connectionRef.current;
    if (current === null || current.pointerId !== event.pointerId) return;

    connectionRef.current = null;
    setConnectionDrag(null);
    suppressPortClickRef.current = current.moved;
    if (!current.moved) return;

    // The final pointer move is not guaranteed to be delivered before
    // pointer-up, so resolve the release point as well as the last preview.
    const hovered = portAt(event.clientX, event.clientY);
    const target = hovered?.direction === "input"
      ? hovered
      : current.target === null
        ? undefined
        : scene.ports.find((port) => port.id === current.target);
    if (target?.direction === "input") onConnect(current.source.id, target.id);
    else onCancelConnection();
  };

  const cancelConnectionDrag = (): void => {
    if (connectionRef.current === null && pendingSource === null) return;
    connectionRef.current = null;
    setConnectionDrag(null);
    suppressPortClickRef.current = true;
    onCancelConnection();
  };

  const beginPan = (event: ReactPointerEvent<SVGSVGElement>): void => {
    if (onViewportChange === undefined) return;
    const middleButton = event.button === 1;
    const shiftedPrimaryButton = event.button === 0 && event.shiftKey;
    if (!middleButton && !shiftedPrimaryButton) return;

    event.preventDefault();
    event.currentTarget.setPointerCapture(event.pointerId);
    panRef.current = {
      startX: event.clientX,
      startY: event.clientY,
      unitsPerPixel: unitsPerPixel(),
      viewport
    };
  };

  const continuePan = (event: ReactPointerEvent<SVGSVGElement>): void => {
    const pan = panRef.current;
    if (pan === null) return;

    changeViewport(
      panViewport(
        pan.viewport,
        (event.clientX - pan.startX) * pan.unitsPerPixel,
        (event.clientY - pan.startY) * pan.unitsPerPixel
      )
    );
  };

  const finishPan = (event: ReactPointerEvent<SVGSVGElement>): void => {
    if (panRef.current === null) return;
    panRef.current = null;
    event.currentTarget.releasePointerCapture(event.pointerId);
  };

  const zoomAtPointer = (event: WheelEvent): void => {
    if (onViewportChange === undefined || event.deltaY === 0) return;
    event.preventDefault();
    const factor = Math.exp(-event.deltaY * 0.0015);
    changeViewport(
      zoomViewportAt(viewport, viewport.zoom * factor, pointAt(event.clientX, event.clientY))
    );
  };

  // React's delegated wheel listener is passive in current browsers. The
  // camera must consume the wheel so the document does not scroll beneath a
  // graph being zoomed, therefore this one handler is deliberately native and
  // explicitly non-passive.
  useEffect(() => {
    const svg = svgRef.current;
    if (svg === null) return undefined;

    svg.addEventListener("wheel", zoomAtPointer, { passive: false });
    return () => {
      svg.removeEventListener("wheel", zoomAtPointer);
    };
  }, [onViewportChange, viewport]);

  useEffect(() => {
    const svg = svgRef.current;
    if (svg === null) return undefined;

    const updateScale = (): void => {
      const matrix = svg.getScreenCTM();
      const pixelsPerUnit = matrix === null ? 1 : Math.hypot(matrix.a, matrix.b);
      const next = pixelsPerUnit <= 0 ? 1 : 1 / pixelsPerUnit;
      setUnitsPerCssPixel((current) => Math.abs(current - next) < 0.001 ? current : next);
    };
    updateScale();
    const observer = new ResizeObserver(updateScale);
    observer.observe(svg);
    window.addEventListener("resize", updateScale);
    return () => {
      observer.disconnect();
      window.removeEventListener("resize", updateScale);
    };
  }, [viewBox.x, viewBox.y, viewBox.width, viewBox.height]);

  useEffect(() => {
    const cancelOnEscape = (event: KeyboardEvent): void => {
      if (event.key !== "Escape") return;
      if (connectionRef.current === null && pendingSource === null) return;
      event.preventDefault();
      cancelConnectionDrag();
    };
    window.addEventListener("keydown", cancelOnEscape);
    return () => window.removeEventListener("keydown", cancelOnEscape);
  }, [pendingSource, onCancelConnection]);

  const regionDepth = new Map(
    scene.regions.map((region) => [region.id, region.depth])
  );

  // A value is shown once. It rides the wire that carries it out of a port,
  // and only a port whose value drives no drawn wire shows it on the socket
  // itself — the Output node's input, or a producer whose consumer is outside
  // the focused region.
  const wiredSources = new Set<PortId>(scene.wires.map((wire) => wire.source));

  const frames = [
    ...scene.regions.map((region) => ({
      depth: region.depth,
      order: 0,
      element: (
        <RegionView
          key={region.id}
          region={region}
          related={relatedSources?.has(region.id) ?? false}
          hideControls
          focused={overlay.focus === region.id}
          entered={overlay.entered === region.id}
          provenance={provenanceAnchor === region.id}
          onEnter={region.id === scene.root ? undefined : (target) => {
            onEnterRegion(target.id);
          }}
          onToggle={region.id === scene.root || onToggleRegion === undefined ? undefined : (target) => {
            onToggleRegion(target.id);
          }}
        />
      )
    })),
    ...scene.nodes.map((node) => ({
      depth: regionDepth.get(node.region) ?? 0,
      order: 1,
      element: (
        <NodeView
          key={node.id}
          node={node}
          breakpoint={breakpoints?.has(node.id) ?? false}
          selected={selectedNodes?.has(node.id) ?? node.id === selectedNode}
          focused={overlay.focus === node.id}
          anchored={overlay.anchored.has(node.id)}
          provenance={provenanceAnchor === node.id}
          onSelect={onSelectNode}
          onEdit={onEditNode}
          onExpandBody={node.collapsedBody === undefined || onToggleRegion === undefined
            ? undefined : () => onToggleRegion(node.collapsedBody!)}
          onEnter={
            node.nodeKind === "Lambda" || node.nodeKind === "LetRec"
              ? (target) => {
                  const role = target.nodeKind === "Lambda"
                    ? "lambda-body"
                    : "letrec-scope";
                  const region = scene.regions.find(
                    (candidate) => candidate.owner === target.id && candidate.role === role
                  );
                  const regionId = region?.id ?? target.collapsedBody;
                  if (regionId !== undefined) onEnterRegion(regionId);
                }
              : undefined
          }
          onDragStart={beginDrag}
          onDragMove={continueDrag}
          onDragEnd={finishDrag}
          onDragCancel={cancelDrag}
        />
      )
    }))
  ].sort((left, right) =>
    left.depth === right.depth ? left.order - right.order : left.depth - right.depth
  );

  const ifBranches = scene.nodes.flatMap((node) => {
    if (node.nodeKind !== "If") return [];
    const thenRegion = scene.regions.find(
      (region) => region.owner === node.id && region.role === "if-then"
    );
    const elseRegion = scene.regions.find(
      (region) => region.owner === node.id && region.role === "if-else"
    );
    return thenRegion === undefined || elseRegion === undefined
      ? []
      : [<IfBranchView
          key={node.id}
          node={node}
          thenRegion={thenRegion}
          elseRegion={elseRegion}
        />];
  });
  const previewArrowhead = connectionDrag?.moved
    ? routedWireArrowhead([connectionDrag.source, connectionDrag.point])
    : "";
  const [previewTipX = 0, previewTipY = 0] = previewArrowhead === ""
    ? []
    : previewArrowhead.split(" ")[0]!.split(",").map(Number);
  const screenCompensation = Math.max(1, unitsPerCssPixel);

  return (
    <svg
      ref={svgRef}
      className="gl-canvas"
      viewBox={`${viewBox.x} ${viewBox.y} ${viewBox.width} ${viewBox.height}`}
      preserveAspectRatio="xMidYMid meet"
      role="group"
      tabIndex={0}
      aria-label="Source graph projection"
      data-viewport-zoom={viewport.zoom.toFixed(3)}
      data-viewport-center={`${viewport.center.x.toFixed(3)},${viewport.center.y.toFixed(3)}`}
      data-detail-level={projectionScale < 0.55 ? "overview" : "full"}
      onDoubleClick={(event) => {
        if (event.target === event.currentTarget || (event.target instanceof Element && event.target.getAttribute("data-canvas-background") === "true")) {
          event.preventDefault(); onRequestNode?.(pointAt(event.clientX, event.clientY));
        }
      }}
      onKeyDown={(event) => {
        if ((event.ctrlKey || event.metaKey) && event.code === "Space") {
          event.preventDefault(); onRequestNode?.(viewport.center);
        }
      }}
      onPointerDown={beginPan}
      onPointerMove={(event) => {
        continuePan(event);
        continueConnectionDrag(event);
      }}
      onPointerUp={(event) => {
        finishConnectionDrag(event);
        finishPan(event);
      }}
      onPointerCancel={(event) => {
        cancelConnectionDrag();
        cancelDrag(event);
        finishPan(event);
      }}
      onClick={(event) => {
        const background =
          event.target === event.currentTarget ||
          (event.target instanceof Element &&
            event.target.getAttribute("data-canvas-background") === "true");
        if (background) onSelectNode(null);
      }}
    >
      <defs>
        <pattern
          id="gl-grid"
          width={32}
          height={32}
          patternUnits="userSpaceOnUse"
        >
          <path className="gl-grid-line" d="M 32 0 L 0 0 0 32" fill="none" />
        </pattern>
      </defs>

      <rect
        className="gl-canvas-ground"
        data-canvas-background="true"
        x={scene.origin.x}
        y={scene.origin.y}
        width={scene.width}
        height={scene.height}
      />
      <rect
        data-canvas-background="true"
        x={scene.origin.x}
        y={scene.origin.y}
        width={scene.width}
        height={scene.height}
        fill="url(#gl-grid)"
      />

      <g data-layer="frames">{frames.filter((entry) => entry.order === 0).map((entry) => entry.element)}</g>
      <g data-layer="if-branches">{ifBranches}</g>
      <g data-layer="wires">
        {scene.wires.map((wire) => (
          <WireView
            key={wire.id}
            wire={wire}
            selected={wire.id === selectedWire}
            related={relatedSources?.has(wire.id) ?? false}
            screenCompensation={screenCompensation}
            value={overlay.values.get(wire.source)}
            provenance={provenanceAnchor === wire.id}
            detailScale={detailScale}
            onSelect={onSelectWire}
          />
        ))}
        {connectionDrag?.moved ? (
          <g
            data-connection-preview="true"
            data-source-port={connectionDrag.source.id}
            data-target-port={connectionDrag.target ?? undefined}
            data-flow-direction="output-to-input"
          >
            <path
              className="gl-wire-preview"
              d={`M ${connectionDrag.source.x} ${connectionDrag.source.y} L ${connectionDrag.point.x} ${connectionDrag.point.y}`}
              fill="none"
            />
            <polygon
              className="gl-wire-preview-arrowhead"
              points={previewArrowhead}
              transform={screenCompensation <= 1
                ? undefined
                : `translate(${previewTipX} ${previewTipY}) scale(${screenCompensation}) translate(${-previewTipX} ${-previewTipY})`}
            />
          </g>
        ) : null}
      </g>
      <g data-layer="junctions">
        {scene.wires.flatMap((wire) => (wire.captureRegions ?? []).map((id) => {
          const region = scene.regions.find((entry) => entry.id === id);
          return region === undefined ? null : <CaptureBoundaryView key={`${wire.id}:${id}`} wire={wire} region={region} />;
        }))}
        {scene.junctions.map((junction) => (
          <circle
            key={junction.source}
            className={`gl-wire-junction gl-type--${junction.typeClass}`}
            data-source-port={junction.source}
            cx={junction.point.x}
            cy={junction.point.y}
            r={3.5}
          />
        ))}
      </g>
      <g data-layer="port-targets">
        {scene.ports.map((port) => <PortTarget key={port.id} port={port} radius={16 * unitsPerCssPixel}
          onSelect={(target, point) => {
            if (suppressPortClickRef.current) { suppressPortClickRef.current = false; return; }
            onSelectPort(point === undefined ? target : portAt(point.x, point.y) ?? target);
          }} onConnectionStart={beginConnectionDrag} />)}
      </g>
      <g data-layer="nodes">{frames.filter((entry) => entry.order === 1).map((entry) => entry.element)}</g>
      <g data-layer="ports">
        {scene.ports.map((port) => (
          <PortView
            key={port.id}
            port={port}
            showGuide={false}
            hitRadius={16 * unitsPerCssPixel}
            pending={port.id === pendingSource || port.id === connectionDrag?.source.id}
            candidate={port.id === connectionDrag?.target}
            connectionCheck={connectionChecks?.get(port.id)}
            related={relatedSources?.has(port.id) ?? false}
            focused={overlay.focus === port.id}
            written={overlay.written.has(port.id)}
            cleared={overlay.cleared.has(port.id)}
            provenance={provenanceAnchor === port.id}
            value={
              wiredSources.has(port.id) ? undefined : overlay.values.get(port.id)
            }
            detailScale={detailScale}
            onSelect={(port, point) => {
              if (suppressPortClickRef.current) {
                suppressPortClickRef.current = false;
                return;
              }
              onSelectPort(point === undefined ? port : portAt(point.x, point.y) ?? port);
            }}
            onConnectionStart={beginConnectionDrag}
          />
        ))}
      </g>
      <g data-layer="variable-uses">
        {scene.variableUses.map((use) => {
          const wire = scene.wires.find((candidate) => candidate.id === use.edge);
          return wire === undefined ? null : (
            <VariableUseView
              key={use.edge}
              use={use}
              related={relatedSources?.has(use.edge) ?? false}
              wire={wire}
              selected={wire.id === selectedWire}
              provenance={provenanceAnchor === use.edge}
              onSelect={onSelectWire}
            />
          );
        })}
      </g>
      <g data-layer="region-controls">
        {scene.regions.filter((region) => region.id !== scene.root).map((region) => (
          <RegionControls key={region.id} region={region} controlScale={unitsPerCssPixel}
            onEnter={(target) => onEnterRegion(target.id)}
            onToggle={onToggleRegion === undefined ? undefined : (target) => onToggleRegion(target.id)} />
        ))}
      </g>
      <g data-layer="inline-editor">{inlineEditor}</g>
    </svg>
  );
}
