import type { JSX } from "react";
import { checkConnection, prettyOpenInputExpectedType, variablesInRegion,
  type Graph, type PortId, type RegionId } from "@graphlambda/core";

import { regionBreadcrumb } from "../regions/region-navigation.js";

export function ScopeVariables({ graph, region, target, disabled = false, onUse, onHighlight }: {
  readonly graph: Graph; readonly region: RegionId; readonly target?: PortId | undefined;
  readonly disabled?: boolean;
  readonly onUse: (source: PortId) => void;
  readonly onHighlight?: (source: PortId) => void;
}): JSX.Element {
  const scopes = variablesInRegion(graph, region);
  return <section className="gl-scope-variables" aria-label="Variables in scope">
    <h3 className="gl-section-title">Variables in scope</h3>
    {scopes.length === 0 ? <p className="gl-dim">No variables in this region. Open a function body to use its parameter.</p> : scopes.map((scope) => {
      const source = scope.source;
      const origin = scope.origin;
      const type = scope.type;
      const check = target === undefined ? undefined : checkConnection(graph, source, target);
      return <div className="gl-scope-variable" key={scope.id}>
        <strong className="gl-mono">{scope.name} : {type === undefined ? "?" : prettyOpenInputExpectedType(type)}</strong>
        <span className="gl-dim">{scope.local ? "Local" : "Inherited from outer scope"} · {regionBreadcrumb(graph, origin).map((crumb) => crumb.label).join(" / ")}</span>
        <div><button type="button" className="gl-button" disabled={disabled || check?.ok === false}
          title={check?.diagnostics[0]?.message} onClick={() => onUse(source)}>Use {scope.name}</button>
          {onHighlight === undefined ? null : <button type="button" className="gl-button" onClick={() => onHighlight(source)} title="Highlight declaration and all uses">Show uses</button>}</div>
      </div>;
    })}
  </section>;
}
