import {
  add,
  apply,
  arrowType,
  compileTermToGraph,
  createFreshIdentityFactory,
  createGraph,
  createRootRegion,
  intLiteral,
  intType,
  ifExpression,
  lambda,
  less,
  letExpression,
  letRecExpression,
  mul,
  prettyExpression,
  sub,
  variable,
  type Expression,
  type Graph
} from "@graphlambda/core";

/**
 * The programs the read-only projection is exercised against.
 *
 * These are the five shapes the visual language has to carry — a bare lambda,
 * a saturated application, a higher-order application, a shared `let`, and a
 * recursive `letrec`. Each is a λG term compiled by the core compiler; the
 * editor never builds a graph itself.
 */
export interface ExampleProgram {
  readonly id: string;
  readonly name: string;
  /** What the shape is meant to show. Descriptive, not promotional. */
  readonly note: string;
  /** `null` for the empty starting graph, which has no term. */
  readonly term: Expression | null;
  readonly source: string;
}

const INT = intType();
const INT_TO_INT = arrowType(INT, INT);

const increment = lambda("x", INT, add(variable("x"), intLiteral(1)));

const PROGRAMS: readonly ExampleProgram[] = Object.freeze([
  program(
    "lambda",
    "Lambda",
    "One region, one binder, no application.",
    increment
  ),
  program(
    "application",
    "Application",
    "Apply with distinct function and argument sockets.",
    apply(increment, intLiteral(5))
  ),
  program(
    "higher-order",
    "Higher order",
    "A function value travels a wire typed Int -> Int.",
    apply(
      lambda("f", INT_TO_INT, apply(variable("f"), intLiteral(10))),
      increment
    )
  ),
  program(
    "let-sharing",
    "Let sharing",
    "One producer, two consumers: sharing is fan-out, not duplication.",
    letExpression("x", add(intLiteral(10), intLiteral(20)), mul(variable("x"), variable("x")))
  ),
  program(
    "letrec",
    "Letrec",
    "The only construct that authorises recursive reference.",
    letRecExpression(
      "fact",
      INT_TO_INT,
      lambda(
        "n",
        INT,
        ifExpression(
          less(variable("n"), intLiteral(1)),
          intLiteral(1),
          mul(
            variable("n"),
            apply(variable("fact"), sub(variable("n"), intLiteral(1)))
          )
        )
      ),
      apply(variable("fact"), intLiteral(5))
    )
  )
]);

/**
 * The empty starting point.
 *
 * It exists so structural editing can be exercised from nothing: an editor
 * that can only modify a compiled example is not an editor. Its graph is one
 * root region, built by the core's own `createGraph`.
 */
const EMPTY: ExampleProgram = Object.freeze({
  id: "empty",
  name: "Empty",
  note: "One root region. Build a program with the node palette.",
  term: null,
  source: ""
});

function program(
  id: string,
  name: string,
  note: string,
  term: Expression
): ExampleProgram {
  return Object.freeze({
    id,
    name,
    note,
    term,
    source: prettyExpression(term)
  });
}

const STARTING_POINTS: readonly ExampleProgram[] = Object.freeze([
  EMPTY,
  ...PROGRAMS
]);

/** The five documented shapes, in presentation order. */
export function examplePrograms(): readonly ExampleProgram[] {
  return PROGRAMS;
}

/** Everything the editor offers as a starting document, empty graph included. */
export function startingPoints(): readonly ExampleProgram[] {
  return STARTING_POINTS;
}

/** Looks one starting point up by id. */
export function exampleProgram(id: string): ExampleProgram | undefined {
  return STARTING_POINTS.find((candidate) => candidate.id === id);
}

/**
 * Builds an example's source graph.
 *
 * Compilation is the core's job. The editor calls the compiler — or, for the
 * empty starting point, the core's own `createGraph` — and projects the
 * result; it holds no graph-construction logic of its own.
 */
export function exampleGraph(example: ExampleProgram): Graph {
  if (example.term === null) {
    return createGraph(
      createRootRegion({ id: createFreshIdentityFactory().nextRegionId() })
    );
  }
  return compileTermToGraph(example.term);
}
