import { createDeterministicIdentityFactory, getPort, getNode, visibleBinderScopes } from "../graph/index.js";
import { typeGraph } from "../typing/index.js";
import { applyGraphEdit } from "./apply.js";
import { editDiagnostic } from "./diagnostics.js";
/** Private identities never advance the caller's factory or escape into G. */
export function previewIdentities(graph) {
    const entities = [...graph.nodes, ...graph.ports, ...graph.edges, ...graph.regions];
    let index = 0;
    while (entities.some((entity) => entity.id.includes(`authoring-preview-${index}:`)))
        index++;
    return createDeterministicIdentityFactory(`authoring-preview-${index}`);
}
/** Exactly the edit judgement used on release, including scope and cycles. */
export function checkConnection(graph, source, target) {
    const result = applyGraphEdit(graph, { kind: "Connect", source, target }, { identities: previewIdentities(graph) });
    return { ok: result.ok, diagnostics: result.ok ? [] : result.diagnostics };
}
/** All-or-nothing semantic edit transaction. Intermediate snapshots stay private. */
export function applyGraphEdits(graph, actions, context) {
    let current = graph;
    const created = [];
    const removed = [];
    for (const action of actions) {
        const result = applyGraphEdit(current, action, context);
        if (!result.ok)
            return result;
        current = result.graph;
        created.push(...result.created);
        removed.push(...result.removed);
    }
    return { ok: true, graph: current, created, removed };
}
/** Build in the input's lexical region, then connect its existing result port. */
export function createNodeForInput(graph, action, target, context) {
    const input = getPort(graph, target);
    const owner = input === undefined ? undefined : getNode(graph, input.owner);
    if (owner === undefined)
        return { ok: false, diagnostics: [editDiagnostic("UNKNOWN_PORT", "edit", target, "The input no longer exists.")] };
    const region = inputRegion(graph, target);
    const created = applyGraphEdit(graph, { ...action, region: region }, context);
    if (!created.ok)
        return created;
    const node = created.graph.nodes.find((entry) => created.created.includes(entry.id));
    const output = created.graph.ports.find((port) => port.owner === node?.id && port.direction === "output" && port.role !== "parameter" && port.role !== "recursive");
    if (output === undefined)
        return { ok: false, diagnostics: [editDiagnostic("MISSING_NODE_DETAIL", "edit", target, "Choose an expression with a result, such as Integer, Lambda, or Application.")] };
    const connected = applyGraphEdit(created.graph, { kind: "Connect", source: output.id, target }, context);
    return connected.ok ? { ...connected, created: [...created.created, ...connected.created] } : connected;
}
/** Lexical destination of an input, including Lambda/branch boundary results. */
export function inputRegion(graph, target) {
    const input = getPort(graph, target);
    const owner = input === undefined ? undefined : getNode(graph, input.owner);
    if (owner === undefined)
        return graph.rootRegion;
    const region = graph.regions.find((entry) => entry.owner === owner.id && (owner.kind === "Lambda" && input?.role === "body" ? entry.role === "lambda-body" :
        owner.kind === "If" && input?.role === "then" ? entry.role === "if-then" :
            owner.kind === "If" && input?.role === "else" ? entry.role === "if-else" :
                owner.kind === "LetRec" && (input?.role === "body" || input?.role === "definition") ? entry.role === "letrec-scope" : false));
    return region?.id ?? owner.region;
}
/** A guided recursive definition is one semantic transaction. */
export function createRecursiveFunction(graph, region, name, type, context) {
    if (type.kind !== "Arrow")
        return { ok: false, diagnostics: [editDiagnostic("INVALID_PROPERTY", "edit", region, "A recursive function needs an arrow type.")] };
    const definition = applyGraphEdit(graph, { kind: "CreateNode", nodeKind: "Lambda", region,
        binderName: "x", parameterType: type.parameter }, context);
    if (!definition.ok)
        return definition;
    const lambda = definition.graph.nodes.find((node) => definition.created.includes(node.id) && node.kind === "Lambda");
    if (!lambda)
        return definition;
    const recursive = applyGraphEdit(definition.graph, { kind: "CreateNode", nodeKind: "LetRec", region,
        binderName: name, recursiveType: type, definition: lambda.id }, context);
    return recursive.ok ? { ...recursive, created: [...definition.created, ...recursive.created] } : recursive;
}
/** Core-owned scope and type facts for the variable chooser. */
export function variablesInRegion(graph, region) {
    const typing = typeGraph(graph);
    const types = typing.ok ? typing.typedGraph.portTypes : typing.partialPortTypes;
    return visibleBinderScopes(graph, region).map((scope) => {
        const source = "letrec" in scope ? scope.letrec.recursive.valuePort : scope.lambda.parameter.parameterPort;
        const origin = "letrec" in scope ? scope.scopeRegion.id : scope.bodyRegion.id;
        return Object.freeze({ id: scope.declaration.id, name: scope.declaration.displayName, source, origin,
            type: types.find((entry) => entry.port === source)?.type, local: origin === region });
    });
}
