import { useEffect, useRef, type JSX } from "react";
import type { NodeId } from "@graphlambda/core";
import type { CreateNodeRequest } from "../state/editor-state.js";
import { Palette } from "./Palette.js";

/** Native modal supplies Escape, focus trapping, and keyboard navigation. */
export function NodePicker({ definition, onCreate, onClose }: {
  readonly definition: NodeId | null;
  readonly onCreate: (request: CreateNodeRequest) => void;
  readonly onClose: () => void;
}): JSX.Element {
  const dialog = useRef<HTMLDialogElement>(null);
  useEffect(() => {
    const previous = document.activeElement;
    dialog.current?.showModal();
    dialog.current?.querySelector<HTMLInputElement>('input[type="search"]')?.focus();
    return () => { if (previous instanceof HTMLElement || previous instanceof SVGElement) previous.focus(); };
  }, []);
  return <dialog ref={dialog} className="gl-node-picker" aria-labelledby="gl-node-picker-title"
    onCancel={(event) => { event.preventDefault(); onClose(); }}
    onClick={(event) => { if (event.target === event.currentTarget) {
      const rect = event.currentTarget.getBoundingClientRect();
      if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) onClose();
    } }}>
    <div className="gl-picker-heading"><h2 id="gl-node-picker-title">Add a node</h2>
      <button type="button" className="gl-button" aria-label="Close node picker" onClick={onClose}>×</button></div>
    <p className="gl-picker-hint">Search, then choose a node. Escape cancels.</p>
    <Palette definition={definition} autoFocusSearch onCreate={onCreate} />
  </dialog>;
}
