import {
  identityText,
  machineProvenanceReferences,
  resolveProvenanceReference,
  type Graph,
  type MachineState,
  type SourceDomain,
  type SourceId
} from "@graphlambda/core";

/**
 * Provenance inspection.
 *
 * Selecting a runtime value in the machine panel asks a single question: which
 * persistent source elements produced or anchor this value? The answer is the
 * core's own `machineProvenanceReferences`, filtered to the rows underneath the
 * selected state path. The editor does not maintain a provenance map of its
 * own — GraphLambda's anchors are intrinsic, so there is nothing to maintain.
 *
 * A row that does not resolve, or resolves in the wrong identity domain, is
 * shown as such rather than hidden. That is exactly the condition the
 * `DERIVED_PROVENANCE` obligation reports, and a debugger that quietly dropped
 * it would be hiding the very thing the checker exists to catch.
 */
export interface ProvenanceRow {
  /** The state path that reaches this reference, e.g. `sigma[0].value.lambda`. */
  readonly path: string;
  readonly id: SourceId;
  /** The identity domains this position is rendered as. */
  readonly expected: readonly SourceDomain[];
  /** The domain the graph actually resolves it in, if it resolves at all. */
  readonly resolved: SourceDomain | undefined;
  /** What the source element is, e.g. `Lambda node` or `Apply.result port`. */
  readonly description: string;
  /** True when the reference resolves in a domain the position expects. */
  readonly valid: boolean;
}

/**
 * Whether `path` is `prefix` or lies underneath it.
 *
 * The dot is required: without it `rho[1]` would claim every reference under
 * `rho[10]`.
 */
export function underPath(path: string, prefix: string): boolean {
  return path === prefix || path.startsWith(`${prefix}.`);
}

/** Every provenance reference a machine state holds. */
export function provenanceRows(
  graph: Graph,
  state: MachineState
): readonly ProvenanceRow[] {
  const describe = describeElement(graph);

  return Object.freeze(
    machineProvenanceReferences(state).map((reference) => {
      const resolution = resolveProvenanceReference(graph, reference);
      const resolved =
        resolution.kind === "Unresolved" ? undefined : resolution.domain;

      return Object.freeze({
        path: reference.path,
        id: reference.id,
        expected: reference.expected,
        resolved,
        description:
          resolution.kind === "Unresolved"
            ? `does not resolve in G`
            : describe(reference.id, resolution.domain),
        valid: resolution.kind === "Resolved"
      });
    })
  );
}

/** The provenance of one selected state row. */
export function provenanceOf(
  graph: Graph,
  state: MachineState,
  path: string
): readonly ProvenanceRow[] {
  return Object.freeze(
    provenanceRows(graph, state).filter((row) => underPath(row.path, path))
  );
}

/**
 * Renders a source element for the provenance table.
 *
 * The text names the kind of entity, never a coordinate and never a type the
 * editor inferred: a port is described by the node that owns it and the role it
 * plays there, both of which are the graph's own fields.
 */
function describeElement(
  graph: Graph
): (id: SourceId, domain: SourceDomain) => string {
  const nodeKinds = new Map<string, string>();
  for (const node of graph.nodes) nodeKinds.set(node.id, node.kind);

  const portText = new Map<string, string>();
  for (const port of graph.ports) {
    portText.set(
      port.id,
      `${nodeKinds.get(port.owner) ?? "?"}.${port.role} port`
    );
  }

  const regionText = new Map<string, string>();
  for (const region of graph.regions) {
    regionText.set(region.id, `${region.role} region`);
  }

  const edgeText = new Map<string, string>();
  for (const edge of graph.edges) {
    edgeText.set(edge.id, edge.kind === "BinderUse" ? "binder use" : "value edge");
  }

  return (id, domain) => {
    switch (domain) {
      case "node":
        return `${nodeKinds.get(id) ?? "?"} node`;
      case "port":
        return portText.get(id) ?? identityText(id);
      case "region":
        return regionText.get(id) ?? identityText(id);
      case "edge":
        return edgeText.get(id) ?? identityText(id);
    }
  };
}
