import type { JSX } from "react";

import type { SceneWire } from "../canvas/scene.js";
import { routedWireArrowhead, wireCoreWidth } from "./wire-appearance.js";

export interface WireViewProps {
  readonly wire: SceneWire;
  readonly selected: boolean;
  /** Inverse canvas scale used only for CSS-pixel interaction/arrow affordances. */
  readonly screenCompensation?: number;
  /** The runtime value this wire is carrying, rendered as text. */
  readonly value?: string | undefined;
  /** The exact source edge selected in the provenance inspector. */
  readonly provenance?: boolean;
  readonly related?: boolean;
  /** Inverse fitted scale for arrowheads and function-type badges. */
  readonly detailScale?: number;
  readonly onSelect: (wire: SceneWire) => void;
}

/**
 * One connection.
 *
 * Everything about how the wire is drawn comes from the type on the output
 * port it leaves — never from the kind of node at either end. A function type
 * is a doubled rail: a thick casing with a contrasting core drawn over it.
 *
 * A recursive occurrence additionally carries loop notation: the wire arcs over
 * the top and a circular arrow sits at its midpoint. Only a `letrec` can
 * authorise a recursive reference, so no other construct ever draws it.
 *
 * A transparent hit path runs under the visible stroke so a 1.5px wire can
 * still be selected without demanding pixel-perfect aim.
 */
export function WireView({
  wire,
  selected,
  screenCompensation = 1,
  value,
  provenance = false,
  related = false,
  detailScale = 1,
  onSelect
}: WireViewProps): JSX.Element {
  const { appearance, midpoint } = wire;
  const arrowhead = routedWireArrowhead(wire.route);
  const target = wire.route.at(-1) ?? midpoint;

  return (
    <g
      className={`gl-wire gl-type--${appearance.typeClass} gl-wire--${wire.wireKind}${
        wire.backEdge ? " gl-wire--back" : ""
      }${wire.feedback ? " gl-wire--feedback" : ""}${
        selected ? " gl-wire--selected" : ""
      }${provenance ? " gl-wire--provenance" : ""}`}
      data-edge-id={wire.id}
      data-related={related || undefined}
      data-source-port={wire.source}
      data-target-port={wire.target}
      data-type-class={appearance.typeClass}
      data-feedback={wire.feedback ? "true" : undefined}
      data-provenance-anchor={provenance || undefined}
      onClick={(event) => {
        event.stopPropagation();
        onSelect(wire);
      }}
    >
      <title>
        {wire.feedback
          ? `recursive occurrence of ${wire.binderName ?? "a binder"} : ${wire.typeText}`
          : wire.binderName === undefined
            ? wire.typeText
            : `${wire.binderName} : ${wire.typeText}`}
      </title>
      <path
        className="gl-wire-hit"
        d={wire.path}
        strokeWidth={Math.max(10, 10 * screenCompensation)}
        fill="none"
      />
      {provenance ? <path className="gl-wire-provenance-trace" d={wire.path} fill="none" /> : null}
      <path
        className="gl-wire-casing"
        d={wire.path}
        strokeWidth={appearance.strokeWidth}
        strokeDasharray={appearance.dash}
        fill="none"
      />
      {arrowhead === "" ? null : (
        <g transform={`translate(${target.x} ${target.y}) scale(${detailScale}) translate(${-target.x} ${-target.y})`}>
          <polygon
            className="gl-wire-arrowhead"
            data-flow-direction="output-to-input"
            points={arrowhead}
          />
        </g>
      )}
      {appearance.doubled ? (
        <path
          className="gl-wire-core"
          d={wire.path}
          strokeWidth={wireCoreWidth(appearance)}
          fill="none"
        />
      ) : null}
      {wire.typeLabel === undefined ? null : (
        <g
          className="gl-wire-type-label"
          data-type-text={wire.typeText}
          transform={`translate(${wire.typeLabel.box.x + wire.typeLabel.box.width / 2} ${wire.typeLabel.box.y + wire.typeLabel.box.height / 2}) scale(${detailScale}) translate(${-wire.typeLabel.box.width / 2} ${-wire.typeLabel.box.height / 2})`}
        >
          <rect
            width={wire.typeLabel.box.width}
            height={wire.typeLabel.box.height}
          />
          <text
            x={wire.typeLabel.box.width / 2}
            y={12}
            textAnchor="middle"
          >
            {wire.typeLabel.text}
          </text>
        </g>
      )}
      {wire.feedback ? (
        <g
          className="gl-wire-loop"
          transform={`translate(${midpoint.x} ${midpoint.y})`}
        >
          <path
            className="gl-wire-loop-arc"
            d="M 6 0 A 6 6 0 1 1 -4.2 -4.2"
            fill="none"
          />
          <polygon className="gl-wire-loop-tip" points="-7,-6 -1,-4.5 -4.5,0" />
        </g>
      ) : null}
      {value === undefined ? null : (
        <text
          className="gl-runtime-value"
          x={midpoint.x}
          y={midpoint.y - 6}
          textAnchor="middle"
        >
          {value}
        </text>
      )}
      {provenance ? (
        <rect
          className="gl-wire-provenance-marker"
          x={midpoint.x - 4}
          y={midpoint.y - 4}
          width={8}
          height={8}
          transform={`rotate(45 ${midpoint.x} ${midpoint.y})`}
        />
      ) : null}
    </g>
  );
}
