/** Construct an immutable typed-hole analysis fact. */
export function createOpenInput(port, expected) {
    return Object.freeze({ kind: "OpenInput", port, expected });
}
/** Projects an internal constraint without exposing its allocation identity. */
export function openInputExpectedType(type) {
    switch (type.kind) {
        case "Int":
        case "Bool":
            return type;
        case "TypeVariable":
            return Object.freeze({ kind: "TypeVariable", name: type.label });
        case "Arrow":
            return Object.freeze({
                kind: "Arrow",
                parameter: openInputExpectedType(type.parameter),
                result: openInputExpectedType(type.result)
            });
    }
}
/** Renders an expected hole constraint for diagnostics; it is not source text. */
export function prettyOpenInputExpectedType(type) {
    switch (type.kind) {
        case "Int":
            return "Int";
        case "Bool":
            return "Bool";
        case "TypeVariable":
            return `?${type.name}`;
        case "Arrow": {
            const parameter = type.parameter.kind === "Arrow"
                ? `(${prettyOpenInputExpectedType(type.parameter)})`
                : prettyOpenInputExpectedType(type.parameter);
            return `${parameter} -> ${prettyOpenInputExpectedType(type.result)}`;
        }
    }
}
