const TRUE_LITERAL = Object.freeze({
    kind: "BoolLiteral",
    value: true
});
const FALSE_LITERAL = Object.freeze({
    kind: "BoolLiteral",
    value: false
});
/** Construct a variable occurrence. Names are calculus syntax, not graph IDs. */
export function variable(name) {
    return Object.freeze({ kind: "Variable", name });
}
/** Construct an integer literal representable exactly by a JavaScript number. */
export function intLiteral(value) {
    if (!Number.isSafeInteger(value)) {
        throw new RangeError("λG integer literals must be safe integers");
    }
    return Object.freeze({
        kind: "IntLiteral",
        value: value === 0 ? 0 : value
    });
}
/** Construct either boolean literal. */
export function boolLiteral(value) {
    return value ? TRUE_LITERAL : FALSE_LITERAL;
}
/** Construct a typed lambda abstraction. */
export function lambda(parameter, parameterType, body) {
    return Object.freeze({ kind: "Lambda", parameter, parameterType, body });
}
/** Construct function application. */
export function apply(callee, argument) {
    return Object.freeze({ kind: "Apply", callee, argument });
}
/** Construct a non-recursive let binding. */
export function letExpression(binder, initializer, body) {
    return Object.freeze({ kind: "Let", binder, initializer, body });
}
/** Construct an explicitly recursive, annotated binding. */
export function letRecExpression(binder, binderType, initializer, body) {
    return Object.freeze({
        kind: "LetRec",
        binder,
        binderType,
        initializer,
        body
    });
}
/** Construct a conditional expression. */
export function ifExpression(condition, thenBranch, elseBranch) {
    return Object.freeze({
        kind: "If",
        condition,
        thenBranch,
        elseBranch
    });
}
/** Construct integer addition. */
export function add(left, right) {
    return Object.freeze({ kind: "Add", left, right });
}
/** Construct integer subtraction. */
export function sub(left, right) {
    return Object.freeze({ kind: "Sub", left, right });
}
/** Construct integer multiplication. */
export function mul(left, right) {
    return Object.freeze({ kind: "Mul", left, right });
}
/** Construct integer less-than comparison. */
export function less(left, right) {
    return Object.freeze({ kind: "Less", left, right });
}
/** Decide whether an expression is a call-by-value syntactic value. */
export function isValue(expression) {
    return (expression.kind === "IntLiteral" ||
        expression.kind === "BoolLiteral" ||
        expression.kind === "Lambda");
}
