import { identityText } from "../graph/index.js";
const EMPTY_ENVIRONMENT = Object.freeze([]);
const EMPTY_CAPTURED_PORT_ENVIRONMENT = Object.freeze([]);
function requireSafeInteger(value) {
    if (!Number.isSafeInteger(value)) {
        throw new RangeError("Machine integer values must be safe integers.");
    }
    return Object.is(value, -0) ? 0 : value;
}
/** Constructs an immutable runtime integer. */
export function intValue(value) {
    return Object.freeze({ kind: "Int", value: requireSafeInteger(value) });
}
/** Constructs an immutable runtime boolean. */
export function boolValue(value) {
    return Object.freeze({ kind: "Bool", value });
}
/** Reconstructs a value so callers cannot retain mutable nested input data. */
export function immutableMachineValue(value) {
    switch (value.kind) {
        case "Int":
            return intValue(value.value);
        case "Bool":
            return boolValue(value.value);
        case "Closure":
            return closureValue(value);
    }
}
/** Constructs one immutable rho entry. */
export function environmentBinding(binder, value) {
    return Object.freeze({
        kind: "EnvironmentBinding",
        binder,
        value: immutableMachineValue(value)
    });
}
/** Constructs a finite environment and rejects duplicate function keys. */
export function createEnvironment(bindings = []) {
    const snapshot = [];
    const seen = new Set();
    for (const binding of bindings) {
        const key = identityText(binding.binder);
        if (seen.has(key)) {
            throw new RangeError(`Environment contains duplicate binder ${key}.`);
        }
        seen.add(key);
        snapshot.push(environmentBinding(binding.binder, binding.value));
    }
    return snapshot.length === 0
        ? EMPTY_ENVIRONMENT
        : Object.freeze(snapshot);
}
/** Looks up rho by lexical identity; display names are never consulted. */
export function lookupEnvironment(environment, binder) {
    return environment.find((entry) => entry.binder === binder)?.value;
}
/**
 * Returns rho[binder := value] as a new snapshot. Unchanged rho is not
 * mutated, and an existing binding retains its stable association-list slot.
 */
export function bindEnvironment(environment, binder, value) {
    const index = environment.findIndex((entry) => entry.binder === binder);
    const binding = environmentBinding(binder, value);
    if (index < 0)
        return createEnvironment([...environment, binding]);
    const next = [...environment];
    next[index] = binding;
    return createEnvironment(next);
}
/** Constructs a finite immutable PortId-to-value closure capture. */
export function createCapturedPortEnvironment(bindings = []) {
    const snapshot = [];
    const seen = new Set();
    for (const binding of bindings) {
        const key = identityText(binding.port);
        if (seen.has(key)) {
            throw new RangeError(`Captured port environment contains duplicate port ${key}.`);
        }
        seen.add(key);
        snapshot.push(Object.freeze({
            kind: "CapturedPortBinding",
            port: binding.port,
            value: immutableMachineValue(binding.value)
        }));
    }
    return snapshot.length === 0
        ? EMPTY_CAPTURED_PORT_ENVIRONMENT
        : Object.freeze(snapshot);
}
/** Looks up a captured ordinary source value by its stable PortId. */
export function lookupCapturedPortValue(environment, port) {
    return environment.find((entry) => entry.port === port)?.value;
}
/** Constructs an immutable source-referencing closure. */
export function closureValue(spec) {
    return Object.freeze({
        kind: "Closure",
        lambda: spec.lambda,
        body: spec.body,
        parameter: spec.parameter,
        environment: createEnvironment(spec.environment),
        capturedPorts: createCapturedPortEnvironment(spec.capturedPorts),
        ...(spec.recursiveBinder === undefined
            ? {}
            : { recursiveBinder: spec.recursiveBinder })
    });
}
