import type { Box, Scene } from "./scene.js";
import type { Point } from "./scene.js";

/** The supported camera range. It is presentation-only. */
export const MIN_ZOOM = 0.25;
export const MAX_ZOOM = 2;

/**
 * A camera in source-graph coordinates.
 *
 * Resolved `width` and `height` are CSS-pixel viewport dimensions; `zoom`
 * maps scene units to screen pixels. A one-shot `sizing` request temporarily
 * carries fit bounds. Moving a node never causes an implicit zoom change.
 */
export interface Viewport {
  readonly center: Point;
  readonly width: number;
  readonly height: number;
  readonly zoom: number;
  readonly mode?: "editing" | "overview";
  /** A one-shot request, resolved against the SVG's actual CSS dimensions. */
  readonly sizing?: "fit" | "readable";
}

export interface ViewBox extends Box {}

/** Fits a scene once, without making its bounds a permanent camera input. */
export function fitViewport(scene: Scene): Viewport {
  return fitBox({
    x: scene.origin.x,
    y: scene.origin.y,
    width: scene.width,
    height: scene.height
  }, 0);
}

/** Fits a selected box with a small source-coordinate breathing room. */
export function fitBox(box: Box, padding = 24): Viewport {
  const width = Math.max(1, box.width + padding * 2);
  const height = Math.max(1, box.height + padding * 2);

  return Object.freeze({
    center: Object.freeze({
      x: box.x + box.width / 2,
      y: box.y + box.height / 2
    }),
    width,
    height,
    zoom: 1,
    sizing: "fit",
    mode: "overview"
  });
}

/** A readable initial view. Large graphs can pan; Overview remains explicit. */
export function readableViewport(scene: Scene): Viewport {
  const anchor = scene.nodes.find((node) => node.region === scene.root)?.symbolBox;
  const center = anchor === undefined ? { x: scene.origin.x + scene.width / 2, y: scene.origin.y + scene.height / 2 }
    : { x: anchor.x + anchor.width / 2, y: anchor.y + anchor.height / 2 };
  return { center, width: 1, height: 1, zoom: 1, sizing: "readable", mode: "editing" };
}

/** Resolve fit once, then preserve scale and centre when a panel is resized. */
export function resolveViewport(viewport: Viewport, width: number, height: number): Viewport {
  if (width <= 0 || height <= 0) return viewport;
  if (viewport.sizing === undefined && viewport.width === width && viewport.height === height) return viewport;
  const { sizing, ...camera } = viewport;
  if (sizing === undefined) return { ...camera, width, height };
  const fitted = Math.min(1, width / viewport.width, height / viewport.height);
  const zoom = sizing === "readable" ? 1 : fitted;
  const center = {
    x: sizing === "readable" && viewport.width * zoom > width
      ? viewport.center.x - viewport.width / 2 + width / zoom / 2 : viewport.center.x,
    y: sizing === "readable" && viewport.height * zoom > height
      ? viewport.center.y - viewport.height / 2 + height / zoom / 2 : viewport.center.y
  };
  return { ...camera, center, width, height, zoom };
}

/** Centers a source box without changing the user's current camera scale. */
export function centerViewportOnBox(viewport: Viewport, box: Box): Viewport {
  return Object.freeze({
    ...viewport,
    center: Object.freeze({
      x: box.x + box.width / 2,
      y: box.y + box.height / 2
    })
  });
}

/** The SVG viewBox represented by a camera. */
export function viewportViewBox(viewport: Viewport): ViewBox {
  const width = viewport.width / viewport.zoom;
  const height = viewport.height / viewport.zoom;

  return Object.freeze({
    x: viewport.center.x - width / 2,
    y: viewport.center.y - height / 2,
    width,
    height
  });
}

export function clampZoom(zoom: number): number {
  return Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, zoom));
}

/** Moves the camera while preserving its scale. Positive dx moves the picture left. */
export function panViewport(viewport: Viewport, dx: number, dy: number): Viewport {
  return Object.freeze({
    ...viewport,
    center: Object.freeze({
      x: viewport.center.x - dx,
      y: viewport.center.y - dy
    })
  });
}

/**
 * Changes scale around a source-coordinate anchor, keeping that source point
 * below the same CSS pixel after the zoom.
 */
export function zoomViewportAt(
  viewport: Viewport,
  zoom: number,
  anchor: Point
): Viewport {
  const nextZoom = clampZoom(zoom);
  const before = viewportViewBox(viewport);
  const nextWidth = viewport.width / nextZoom;
  const nextHeight = viewport.height / nextZoom;
  const ratioX = (anchor.x - before.x) / before.width;
  const ratioY = (anchor.y - before.y) / before.height;

  return Object.freeze({
    ...viewport,
    zoom: nextZoom,
    center: Object.freeze({
      x: anchor.x - (ratioX - 0.5) * nextWidth,
      y: anchor.y - (ratioY - 0.5) * nextHeight
    })
  });
}
