import type { JSX } from "react";
import type { Box, Point, SceneRegion, SceneWire } from "../canvas/scene.js";

/** Geometry only: callers supply the boundaries core classified as captures. */
export function captureCrossingPoint(route: readonly Point[], bounds: Box): Point | undefined {
  const inside = (point: Point): boolean => point.x > bounds.x &&
    point.x < bounds.x + bounds.width && point.y > bounds.y && point.y < bounds.y + bounds.height;
  for (let index = 1; index < route.length; index += 1) {
    const from = route[index - 1]!;
    const to = route[index]!;
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const at = (t: number): Point => ({ x: from.x + t * dx, y: from.y + t * dy });
    const candidates = dx !== 0
      ? [(bounds.x - from.x) / dx, (bounds.x + bounds.width - from.x) / dx]
      : dy !== 0 ? [(bounds.y - from.y) / dy, (bounds.y + bounds.height - from.y) / dy] : [];
    for (const t of candidates.sort((a, b) => a - b)) {
      if (t >= 0 && t <= 1 && !inside(at(t - 0.0001)) && inside(at(t + 0.0001))) return at(t);
    }
  }
  return undefined;
}

/** A small, non-interactive crossing mark, never a semantic node or port. */
export function CaptureBoundaryView({ wire, region }: {
  readonly wire: SceneWire;
  readonly region: SceneRegion;
}): JSX.Element | null {
  const point = captureCrossingPoint(wire.route, region.box);
  if (point === undefined) return null;
  return (
    <g data-capture-source={wire.source} data-capture-edge={wire.id} data-capture-region={region.id}>
      <title>{`Capture · ${wire.binderName ?? wire.typeText} · source ${wire.source}`}</title>
      <rect className="gl-socket" x={point.x - 3} y={point.y - 3} width={6} height={6} />
    </g>
  );
}
