const INT_TYPE = Object.freeze({ kind: "Int" });
const BOOL_TYPE = Object.freeze({ kind: "Bool" });
/** Construct the lambda_G integer type. */
export function intType() {
    return INT_TYPE;
}
/** Construct the lambda_G boolean type. */
export function boolType() {
    return BOOL_TYPE;
}
/** Construct a function type from its parameter and result types. */
export function arrowType(parameter, result) {
    return Object.freeze({ kind: "Arrow", parameter, result });
}
