import type { JSX } from "react";

import type { SceneNode, SceneRegion } from "../canvas/scene.js";

export interface IfBranchViewProps {
  readonly node: SceneNode;
  readonly thenRegion: SceneRegion;
  readonly elseRegion: SceneRegion;
}

/**
 * Presentation-only ownership guides from an If diamond to its two semantic
 * branch regions. They are deliberately not semantic wires and carry no IDs.
 */
export function IfBranchView({
  node,
  thenRegion,
  elseRegion
}: IfBranchViewProps): JSX.Element {
  const start = {
    x: node.symbolBox.x + node.symbolBox.width / 2,
    y: node.symbolBox.y + node.symbolBox.height
  };
  const forkY = Math.round((start.y + Math.min(thenRegion.box.y, elseRegion.box.y)) / 2);

  return (
    <g className="gl-if-branches" data-if-owner={node.id} aria-hidden="true">
      <BranchGuide start={start} forkY={forkY} region={thenRegion} role="then" />
      <BranchGuide start={start} forkY={forkY} region={elseRegion} role="else" />
    </g>
  );
}

function BranchGuide({
  start,
  forkY,
  region,
  role
}: {
  readonly start: { readonly x: number; readonly y: number };
  readonly forkY: number;
  readonly region: SceneRegion;
  readonly role: "then" | "else";
}): JSX.Element {
  const endX = region.box.x + region.box.width / 2;
  const endY = region.box.y;
  const labelX = Math.round((start.x + endX) / 2);

  return (
    <g className="gl-if-branch" data-branch-role={role}>
      <path
        className="gl-if-branch-guide"
        d={`M ${start.x} ${start.y} V ${forkY} H ${endX} V ${endY}`}
        fill="none"
      />
      <text
        className="gl-if-branch-guide-label"
        x={labelX}
        y={forkY - 4}
        textAnchor="middle"
      >
        {role}
      </text>
    </g>
  );
}
