export function isValidMachineState(graph, state) {
    return validateMachineState(graph, state).length === 0;
}
export function assertMachineStateInvariants(graph, state) {
    const diagnostics = validateMachineState(graph, state);
    if (diagnostics.length !== 0)
        throw new MachineInvariantError(diagnostics);
}
