import { useLayoutEffect, useRef, useState, type JSX, type PointerEvent } from "react";

/** Pointer and keyboard resizing changes shell geometry only. */
export function ResizeHandle({ side, onResize }: {
  readonly side: "left" | "right" | "bottom";
  readonly onResize: (size: number) => void;
}): JSX.Element {
  const element = useRef<HTMLDivElement>(null);
  const gesture = useRef<{ start: number; size: number } | null>(null);
  const [size, setSize] = useState(0);
  const horizontal = side === "bottom";
  const minimum = horizontal ? 200 : side === "left" ? 180 : 240;
  const currentSize = (): number => {
    const rect = element.current?.parentElement?.getBoundingClientRect();
    return rect === undefined ? minimum : horizontal ? rect.height : rect.width;
  };
  const limit = (next: number): number => {
    const shell = element.current?.closest(".gl-shell");
    const rect = shell?.getBoundingClientRect();
    const other = shell?.querySelector(side === "left" ? ".gl-panel--right" : ".gl-panel--left")?.getBoundingClientRect().width ?? 0;
    const maximum = horizontal ? Math.min(600, (rect?.height ?? 900) - 300)
      : Math.min(side === "left" ? 400 : 480, (rect?.width ?? 1440) - other - 320);
    return Math.round(Math.max(minimum, Math.min(Math.max(minimum, maximum), next)));
  };
  useLayoutEffect(() => {
    const parent = element.current?.parentElement;
    if (parent === null || parent === undefined) return;
    setSize(Math.round(currentSize()));
    const observer = new ResizeObserver(() => setSize(Math.round(currentSize())));
    observer.observe(parent);
    return () => observer.disconnect();
  }, []);
  const finish = (event: PointerEvent<HTMLDivElement>): void => {
    gesture.current = null;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
  };
  return <div ref={element} className={`gl-resize-handle gl-resize-handle--${side}`}
    role="separator" tabIndex={0} aria-label={`Resize ${side === "left" ? "authoring" : side === "right" ? "inspector" : "tool"} panel`}
    aria-orientation={horizontal ? "horizontal" : "vertical"} aria-valuemin={minimum} aria-valuenow={size}
    title="Drag to resize, or use arrow keys"
    onPointerDown={(event) => {
      if (event.button !== 0) return;
      event.preventDefault(); event.stopPropagation();
      gesture.current = { start: horizontal ? event.clientY : event.clientX, size: currentSize() };
      event.currentTarget.setPointerCapture(event.pointerId);
    }}
    onPointerMove={(event) => {
      if (gesture.current === null) return;
      const delta = (horizontal ? event.clientY : event.clientX) - gesture.current.start;
      onResize(limit(gesture.current.size + delta * (side === "left" ? 1 : -1)));
    }} onPointerUp={finish} onPointerCancel={finish}
    onKeyDown={(event) => {
      const direction = horizontal ? (event.key === "ArrowUp" ? 1 : event.key === "ArrowDown" ? -1 : 0)
        : (event.key === "ArrowRight" ? 1 : event.key === "ArrowLeft" ? -1 : 0) * (side === "left" ? 1 : -1);
      if (direction !== 0) { event.preventDefault(); onResize(limit(currentSize() + direction * (event.shiftKey ? 40 : 16))); }
    }} />;
}
