import {
  prettyOpenInputExpectedType,
  type OpenInputExpectedType
} from "@graphlambda/core";

/**
 * The visual classification of a semantic type.
 *
 * This is the *only* thing the projection is allowed to derive an appearance
 * from. It is computed from the type a port carries, never from a node kind,
 * so a wire out of `Apply` and a wire out of `Lambda` look the same when they
 * carry the same type and different when they do not.
 *
 * `unknown` covers a port the graph type checker left as a metavariable, which
 * only happens in a partial graph.
 */
export type TypeClass = "int" | "bool" | "function" | "unknown";

/** Socket silhouettes. Shape, not colour, distinguishes the type classes. */
export type SocketShape = "square" | "diamond" | "hexagon" | "circle";

export interface SocketAppearance {
  readonly typeClass: TypeClass;
  readonly shape: SocketShape;
  /** Half-extent of the silhouette, in SVG units. */
  readonly radius: number;
}

/**
 * Classifies a port type. `Arrow` is its own class precisely so a function
 * value is visually distinguishable from `Int` and `Bool` everywhere it
 * appears — at a socket, on a wire, and in a legend.
 */
export function classifyType(
  type: OpenInputExpectedType | undefined
): TypeClass {
  if (type === undefined) return "unknown";

  switch (type.kind) {
    case "Int":
      return "int";
    case "Bool":
      return "bool";
    case "Arrow":
      return "function";
    case "TypeVariable":
      return "unknown";
  }
}

const SHAPES: Readonly<Record<TypeClass, SocketShape>> = Object.freeze({
  int: "square",
  bool: "diamond",
  function: "hexagon",
  unknown: "circle"
});

const RADII: Readonly<Record<TypeClass, number>> = Object.freeze({
  int: 4,
  bool: 5,
  function: 6,
  unknown: 4
});

/** The socket an input port shows, derived from the type it expects. */
export function socketAppearance(
  type: OpenInputExpectedType | undefined
): SocketAppearance {
  const typeClass = classifyType(type);
  return Object.freeze({
    typeClass,
    shape: SHAPES[typeClass],
    radius: RADII[typeClass]
  });
}

/** SVG `points` for a socket silhouette centred on the origin. */
export function socketPoints(appearance: SocketAppearance): string {
  const r = appearance.radius;

  switch (appearance.shape) {
    case "square":
      return `${-r},${-r} ${r},${-r} ${r},${r} ${-r},${r}`;
    case "diamond":
      return `0,${-r} ${r},0 0,${r} ${-r},0`;
    case "hexagon": {
      const h = Math.round(r * 0.62);
      return `${-h},${-r} ${h},${-r} ${r},0 ${h},${r} ${-h},${r} ${-r},0`;
    }
    case "circle": {
      const d = Math.round(r * 0.72);
      return `${-d},${-r} ${d},${-r} ${r},${-d} ${r},${d} ${d},${r} ${-d},${r} ${-r},${d} ${-r},${-d}`;
    }
  }
}

/**
 * SVG points for an input's small right-pointing flow cue. The socket still
 * carries the expected type; this cue says that values enter its owner.
 */
export function inputArrowPoints(): string {
  return "-12,-3 -5,0 -12,3";
}

/** SVG `points` for the right-pointing arrow an output port emits. */
export function outputArrowPoints(): string {
  return "12,-4 19,0 12,4";
}

/** The label a typed hole shows next to its empty socket. */
export function expectedTypeText(type: OpenInputExpectedType): string {
  return prettyOpenInputExpectedType(type);
}
