import type { OpenInputExpectedType } from "@graphlambda/core";

import { classifyType, type TypeClass } from "../ports/port-appearance.js";

export interface Point {
  readonly x: number;
  readonly y: number;
}

/**
 * How a wire is drawn, derived from the semantic type of the *output* port it
 * leaves. Stroke geometry — not colour — carries the distinction, so the
 * projection stays legible under the monochrome palette:
 *
 * - `Int` is a single thin line
 * - `Bool` is a single thin dashed line
 * - a function type `A -> B` is a thick line drawn twice, once as a casing and
 *   once as a thin core, which reads as a doubled rail and cannot be confused
 *   with either scalar
 */
export interface WireAppearance {
  readonly typeClass: TypeClass;
  readonly strokeWidth: number;
  /** SVG `stroke-dasharray`, or `undefined` for a solid stroke. */
  readonly dash: string | undefined;
  /** Whether the wire is drawn as a casing plus a contrasting core. */
  readonly doubled: boolean;
}

const APPEARANCES: Readonly<Record<TypeClass, WireAppearance>> = Object.freeze({
  int: Object.freeze({
    typeClass: "int" as const,
    strokeWidth: 1.5,
    dash: undefined,
    doubled: false
  }),
  bool: Object.freeze({
    typeClass: "bool" as const,
    strokeWidth: 1.5,
    dash: "5 3",
    doubled: false
  }),
  function: Object.freeze({
    typeClass: "function" as const,
    strokeWidth: 4,
    dash: undefined,
    doubled: true
  }),
  unknown: Object.freeze({
    typeClass: "unknown" as const,
    strokeWidth: 1,
    dash: "2 3",
    doubled: false
  })
});

/** The wire appearance implied by the type carried on the wire. */
export function wireAppearance(
  type: OpenInputExpectedType | undefined
): WireAppearance {
  return APPEARANCES[classifyType(type)];
}

/** The stroke width of a function wire's contrasting core. */
export function wireCoreWidth(appearance: WireAppearance): number {
  return Math.max(1, appearance.strokeWidth - 2.5);
}

/**
 * The four control points of a wire, in SVG cubic order.
 *
 * Routing is expressed as control points rather than as a path string so the
 * path and its midpoint cannot drift apart: both are derived from this one
 * function.
 */
interface Curve {
  readonly p0: Point;
  readonly c1: Point;
  readonly c2: Point;
  readonly p3: Point;
}

/** Upward bow of a recursion loop, in scene units. */
const LOOP_BOW = 44;

function curve(source: Point, target: Point, feedback: boolean): Curve {
  if (feedback) {
    // A recursive occurrence is drawn as a loop over the top. Its geometry is
    // deliberately unlike every other wire: the reference is a cycle in the
    // program's meaning even when the wire happens to run left to right, and
    // that is exactly what the notation has to say.
    const handle = Math.max(48, Math.abs(target.x - source.x) * 0.45);
    return {
      p0: source,
      c1: { x: source.x + handle, y: source.y - LOOP_BOW },
      c2: { x: target.x - handle, y: target.y - LOOP_BOW },
      p3: target
    };
  }

  const span = target.x - source.x;

  if (span >= 0) {
    const handle = Math.min(72, Math.max(20, span * 0.5));
    return {
      p0: source,
      c1: { x: source.x + handle, y: source.y },
      c2: { x: target.x - handle, y: target.y },
      p3: target
    };
  }

  const handle = Math.min(96, Math.max(40, -span * 0.35));
  const bow = 28;
  return {
    p0: source,
    c1: { x: source.x + handle, y: source.y + bow },
    c2: { x: target.x - handle, y: target.y + bow },
    p3: target
  };
}

/**
 * Routes one wire.
 *
 * A wire leaves an output port to the right and enters an input port from the
 * left, so the ordinary case is a horizontal cubic. When the target sits to
 * the left of the source the wire is a back edge; it is bowed downward so it
 * cannot be mistaken for a straight forward connection. A `feedback` wire —
 * a recursive occurrence, which only a `letrec` can authorise — arcs over the
 * top instead.
 */
export function wirePath(
  source: Point,
  target: Point,
  feedback = false
): string {
  const { p0, c1, c2, p3 } = curve(source, target, feedback);
  return (
    `M ${p0.x} ${p0.y} ` +
    `C ${c1.x} ${c1.y}, ${c2.x} ${c2.y}, ${p3.x} ${p3.y}`
  );
}

/**
 * The point halfway along a wire, where a runtime value or a loop marker is
 * placed. This is the cubic evaluated at `t = 1/2`, so it lies on the drawn
 * path rather than near it.
 */
export function wireMidpoint(
  source: Point,
  target: Point,
  feedback = false
): Point {
  const { p0, c1, c2, p3 } = curve(source, target, feedback);
  return Object.freeze({
    x: Math.round((p0.x + 3 * c1.x + 3 * c2.x + p3.x) / 8),
    y: Math.round((p0.y + 3 * c1.y + 3 * c2.y + p3.y) / 8)
  });
}

/** SVG path for a deterministic orthogonal route. */
export function routedWirePath(points: readonly Point[]): string {
  const first = points[0];
  if (first === undefined) return "";
  return [
    `M ${first.x} ${first.y}`,
    ...points.slice(1).map((point) => `L ${point.x} ${point.y}`)
  ].join(" ");
}

/**
 * A triangle placed on the final segment of a routed semantic edge.
 *
 * The point deliberately stops before the target socket. The underlying wire
 * still reaches the semantic input port, while the visible direction mark
 * stays clear of the node frame and the socket's type silhouette. Coordinates
 * remain entirely in the Scene, so this is presentation geometry only.
 */
export function routedWireArrowhead(points: readonly Point[]): string {
  const target = points[points.length - 1];
  if (target === undefined) return "";

  let previous: Point | undefined;
  for (let index = points.length - 2; index >= 0; index -= 1) {
    const candidate = points[index]!;
    if (candidate.x !== target.x || candidate.y !== target.y) {
      previous = candidate;
      break;
    }
  }
  if (previous === undefined) return "";

  const length = Math.hypot(target.x - previous.x, target.y - previous.y);
  if (length === 0) return "";

  const ux = (target.x - previous.x) / length;
  const uy = (target.y - previous.y) / length;
  // A preview can be shorter than the normal final routing lead, so bound the
  // glyph to the available segment rather than letting it point behind its
  // source. Routed graph edges retain the standard 8/7/4 geometry.
  const inset = Math.min(8, length * 0.45);
  const arrowLength = Math.min(7, length * 0.4);
  const halfWidth = Math.min(4, length * 0.23);
  const tip = { x: target.x - ux * inset, y: target.y - uy * inset };
  const base = { x: tip.x - ux * arrowLength, y: tip.y - uy * arrowLength };
  const perpendicular = { x: -uy * halfWidth, y: ux * halfWidth };

  return [
    `${tip.x},${tip.y}`,
    `${base.x + perpendicular.x},${base.y + perpendicular.y}`,
    `${base.x - perpendicular.x},${base.y - perpendicular.y}`
  ].join(" ");
}

/**
 * Halfway point by painted route length, rather than by vertex count. This
 * keeps runtime markers centred even when a wire detours around an obstacle.
 */
export function routedWireMidpoint(points: readonly Point[]): Point {
  if (points.length === 0) return Object.freeze({ x: 0, y: 0 });
  if (points.length === 1) return Object.freeze({ ...points[0]! });

  const lengths = points.slice(1).map((point, index) => {
    const previous = points[index]!;
    return Math.hypot(point.x - previous.x, point.y - previous.y);
  });
  const halfway = lengths.reduce((total, length) => total + length, 0) / 2;
  let travelled = 0;

  for (let index = 0; index < lengths.length; index += 1) {
    const length = lengths[index]!;
    if (travelled + length < halfway) {
      travelled += length;
      continue;
    }

    const from = points[index]!;
    const to = points[index + 1]!;
    const ratio = length === 0 ? 0 : (halfway - travelled) / length;
    return Object.freeze({
      x: Math.round(from.x + (to.x - from.x) * ratio),
      y: Math.round(from.y + (to.y - from.y) * ratio)
    });
  }

  return Object.freeze({ ...points[points.length - 1]! });
}

/** Whether a wire runs against the left-to-right dataflow direction. */
export function isBackEdge(source: Point, target: Point): boolean {
  return target.x < source.x;
}
